// Content for Mind Matters (node g38, ages 9-12, Chapter 3): NEW v2 build to GDD 38 (mechanic-embodying),
// the mental-wellbeing game (Thread C). "Your mind matters too." 84 researched, India-grounded scenarios
// across six categories, each encoded as one of the shared v2 play actions (branch / strike-rewrite / sort /
// reflect / role-play / build / match): no binary "tap the right card", led by the **coping chooser**
// (branch ×25: decide a healthy response, see it help), the **build-your-toolkit** board (build), and
// de-stigmatising myth-flips (strike-rewrite). Teaches: the mind has health too, stress & pressure, handling
// rejection & setbacks (resilience), a personal toolkit of healthy coping moves, asking for help (the
// bravest skill), and being kind to your own mind (self-compassion). WELLBEING-SAFE: healthy coping only
// (breathe, talk, move, rest, problem-break: NO pain-based or risky 'tricks'); NEVER diagnoses or labels;
// NO harsh self-talk (actively replaces self-criticism with self-compassion); normalising, never alarmist;
// ALWAYS A WAY TO HELP: big/lasting feelings or dark thoughts route firmly to a trusted adult & Childline
// 1098 / 112. Builds on g01 (Feelings Friends); prereq g13; pairs with g39 (Bounce) & g41 (Heart Smart) and
// shares the coping-chooser / toolkit-builder. Rendered by the shared engine (components/games/v2-engine.tsx).
// gameId "mind-matters". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // Your mind matters too
  {"id":"mm-001","cat":"mind-matters-too","type":"strike-rewrite","hook":"\"Only your body can be healthy or unwell, not your mind.\"","myth":{"un":"Only the body can be healthy or unwell.","re":"Your mind has health too, and it matters just as much.","why":"Mental health is part of being well."},"relearn":"Your mind has health too; it matters as much as your body.","persona":"any","source":"mental health literacy"},
  {"id":"mm-002","cat":"mind-matters-too","type":"strike-rewrite","hook":"\"Feeling down or worried means something is wrong with me.\"","myth":{"un":"Feeling down or worried means I'm broken.","re":"Everyone feels down or worried sometimes; it's part of being human.","why":"Ups and downs are normal, not a fault."},"relearn":"Everyone has ups and downs; difficult feelings are normal.","persona":"Aarav","source":"normalising"},
  {"id":"mm-003","cat":"mind-matters-too","type":"strike-rewrite","hook":"\"Big feelings last forever.\"","myth":{"un":"Once a hard feeling hits, it stays forever.","re":"Feelings rise, peak and pass, like weather.","why":"No feeling is permanent."},"relearn":"Hard feelings pass; they're like weather, not the climate.","persona":"any","source":"normalising"},
  {"id":"mm-004","cat":"mind-matters-too","type":"strike-rewrite","hook":"\"Caring for your mind is silly or a waste of time.\"","myth":{"un":"Looking after your mind is silly.","re":"Caring for your mind is as sensible as brushing your teeth.","why":"A cared-for mind helps with everything else."},"relearn":"Caring for your mind is sensible self-care, not silly.","persona":"any","source":"mental health literacy"},
  {"id":"mm-005","cat":"mind-matters-too","type":"reflect","hook":"Lensy: your mind works hard all day, thinking, feeling, learning. Deserves care?","prompt":"What do you think?","options":["Yes","It works so hard","I'll care for it"],"affirm":"A mind that's cared for feels steadier and stronger.","relearn":"Your hard-working mind deserves care and rest.","persona":"any","source":"mental health literacy"},
  {"id":"mm-006","cat":"mind-matters-too","type":"reflect","hook":"Lensy: how's your mind feeling today, honestly?","prompt":"Check in.","options":["Pretty good","A bit heavy","Up and down","Not sure"],"affirm":"Just checking in with yourself is a real mind-care skill.","relearn":"Checking in with how you feel is a healthy habit.","persona":"any","source":"self-awareness"},
  {"id":"mm-007","cat":"mind-matters-too","type":"reflect","hook":"Lensy: everyone, even the calmest-looking person, has tough days. Reassuring?","prompt":"What do you think?","options":["Yes","I'm not alone","Everyone struggles sometimes"],"affirm":"Tough days are part of every human life; you're not alone in them.","relearn":"Everyone has tough days; you're never alone in that.","persona":"any","source":"normalising"},
  {"id":"mm-008","type":"sort","hook":"Sort: a sign of a cared-for mind, or a neglected one?","items":[{"id":"a","text":"Enough sleep and rest"},{"id":"b","text":"Bottling everything up"},{"id":"c","text":"Talking about feelings"},{"id":"d","text":"Never taking a break"},{"id":"e","text":"Doing something you enjoy"},{"id":"f","text":"Pretending you're always fine"}],"bins":[{"id":"cared","label":"Cared-for mind","valence":"pos"},{"id":"neglected","label":"Neglected mind","valence":"neg"}],"key":{"a":"cared","b":"neglected","c":"cared","d":"neglected","e":"cared","f":"neglected"},"relearn":"Rest, talking and enjoyment help the mind; bottling up and no breaks harm it.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-009","type":"sort","hook":"Sort: true or false about feelings?","items":[{"id":"a","text":"All feelings are allowed"},{"id":"b","text":"Some feelings make you bad"},{"id":"c","text":"Feelings give us useful information"},{"id":"d","text":"You should never feel sad"},{"id":"e","text":"Hard feelings rise, peak and pass"},{"id":"f","text":"You must be happy all the time"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"All feelings are allowed and pass; none make you 'bad', and you needn't fake being happy.","persona":"any","source":"emotional literacy (links g01)","cat":"mind-matters-too"},
  {"id":"mm-010","type":"sort","hook":"Sort: helps your mind, or just feels good for a second?","items":[{"id":"a","text":"A good night's sleep"},{"id":"b","text":"Hours of doomscrolling"},{"id":"c","text":"Time with people who care"},{"id":"d","text":"Comparing yourself online all day"},{"id":"e","text":"A walk or play outside"},{"id":"f","text":"Skipping rest to never stop"}],"bins":[{"id":"helps","label":"Truly helps","valence":"pos"},{"id":"empty","label":"Empty / hurts","valence":"neg"}],"key":{"a":"helps","b":"empty","c":"helps","d":"empty","e":"helps","f":"empty"},"relearn":"Sleep, real connection and play help; endless scrolling, comparing and no rest drain you.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-011","type":"match","hook":"Match the part of you to its care.","pairs":[{"left":"Body","right":"Food, sleep, movement"},{"left":"Mind","right":"Rest, talking, calm"},{"left":"Both","right":"Kindness and care"},{"left":"A tired mind","right":"A break and some rest"},{"left":"A heavy mind","right":"Talking to someone you trust"}],"relearn":"Body and mind both need care; they work together.","persona":"Rohit","source":"mental health literacy","cat":"mind-matters-too"},
  {"id":"mm-012","type":"match","hook":"Match the feeling to what it might be telling you.","pairs":[{"left":"Worry","right":"Something matters to me"},{"left":"Sadness","right":"I've lost something"},{"left":"Anger","right":"Something feels unfair"},{"left":"Tiredness","right":"I need rest"},{"left":"Loneliness","right":"I'd like to connect"}],"relearn":"Feelings carry useful messages worth listening to.","persona":"any","source":"emotional literacy","cat":"mind-matters-too"},
  // Stress & pressure
  {"id":"mm-013","cat":"stress-and-pressure","type":"branch","hook":"Exams are near and your chest feels tight with stress.","options":[{"text":"Pause, breathe slowly, and make a small study plan","consequence":"The stress eases enough to start.","outcome":"coped","best":true},{"text":"Panic and stare at everything at once","consequence":"A breath and a small plan calm the overwhelm."}],"debrief":"Stress shrinks when you breathe and break it into small steps.","relearn":"Breathe and break a big task into small steps to ease stress.","persona":"Aarav","source":"stress management"},
  {"id":"mm-014","cat":"stress-and-pressure","type":"branch","hook":"Everyone seems to be doing better than you, and it stings.","options":[{"text":"Remind yourself comparison isn't the full story; focus on your own steps","consequence":"You feel steadier and less behind.","outcome":"grounded","best":true},{"text":"Spiral into 'I'm the worst'","consequence":"Comparison shows a highlight reel, not the truth; focus on you."}],"debrief":"Comparison steals calm; your own progress is what counts.","relearn":"Don't measure yourself by others' highlight reels.","persona":"Diya","source":"comparison / stress"},
  {"id":"mm-015","cat":"stress-and-pressure","type":"branch","hook":"A parent says \"just study harder\" but you're already overwhelmed.","options":[{"text":"Calmly share that you're stressed and ask for support","consequence":"They understand better and help.","outcome":"supported","best":true},{"text":"Bottle it up and feel worse","consequence":"Telling someone how you really feel invites support."}],"debrief":"Naming stress to a caring adult turns pressure into support.","relearn":"You can tell a caring adult you're overwhelmed and ask for help.","persona":"Rohit","source":"stress / help-seeking"},
  {"id":"mm-016","cat":"stress-and-pressure","type":"branch","hook":"Stress is making it hard to sleep before a big day.","options":[{"text":"Wind down: screens off, slow breaths, calm routine","consequence":"Your body settles enough to rest.","outcome":"rested","best":true},{"text":"Scroll your phone in bed for hours","consequence":"A calm wind-down helps sleep more than scrolling."}],"debrief":"A calm wind-down routine helps a stressed mind rest.","relearn":"Wind down calmly, not on a screen, to sleep when stressed.","persona":"any","source":"stress / sleep"},
  {"id":"mm-017","cat":"stress-and-pressure","type":"branch","hook":"You have so much to do you don't know where to start.","options":[{"text":"Write it down and pick just the first small thing","consequence":"Starting small breaks the freeze.","outcome":"unstuck","best":true},{"text":"Avoid it all and feel guilty","consequence":"One small first step beats freezing under the pile."}],"debrief":"A big pile feels lighter once you start with one small step.","relearn":"Start with one small step when everything feels too much.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-018","cat":"stress-and-pressure","type":"sort","hook":"Sort: a sign your body shows when stressed, or not?","items":[{"id":"a","text":"Tight chest or tummy"},{"id":"b","text":"Growing taller instantly"},{"id":"c","text":"Racing heart"},{"id":"d","text":"Turning invisible"},{"id":"e","text":"Trouble falling asleep"},{"id":"f","text":"Sprouting wings"}],"bins":[{"id":"sign","label":"A stress sign","valence":"uhoh"},{"id":"no","label":"Not a stress sign","valence":"neutral"}],"key":{"a":"sign","b":"no","c":"sign","d":"no","e":"sign","f":"no"},"relearn":"Stress shows in the body, like a tight chest, racing heart or restless sleep.","persona":"any","source":"stress signals"},
  {"id":"mm-019","cat":"stress-and-pressure","type":"sort","hook":"Sort: eases stress, or adds to it?","items":[{"id":"a","text":"A short walk or play"},{"id":"b","text":"Skipping all sleep to cram"},{"id":"c","text":"Talking to a friend"},{"id":"d","text":"Telling yourself you'll fail"},{"id":"e","text":"Slow, deep breaths"},{"id":"f","text":"Comparing your marks all day"}],"bins":[{"id":"eases","label":"Eases stress","valence":"pos"},{"id":"adds","label":"Adds stress","valence":"neg"}],"key":{"a":"eases","b":"adds","c":"eases","d":"adds","e":"eases","f":"adds"},"relearn":"Walking, talking and slow breaths ease stress; no sleep, harsh self-talk and comparison add to it.","persona":"any","source":"stress management"},
  {"id":"mm-020","cat":"stress-and-pressure","type":"sort","hook":"Sort: a normal amount of stress, or too much to handle alone?","items":[{"id":"a","text":"Butterflies before a test"},{"id":"b","text":"Feeling hopeless for weeks"},{"id":"c","text":"Nerves before a match"},{"id":"d","text":"Stress that never lets up"},{"id":"e","text":"A jumpy tummy on result day"},{"id":"f","text":"Crying every day for a long time"}],"bins":[{"id":"normal","label":"Normal, manageable","valence":"neutral"},{"id":"gethelp","label":"Time to tell an adult","valence":"tell"}],"key":{"a":"normal","b":"gethelp","c":"normal","d":"gethelp","e":"normal","f":"gethelp"},"relearn":"Some stress is normal; stress that won't lift is a signal to tell a trusted adult.","persona":"any","source":"stress / help-seeking"},
  {"id":"mm-021","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Feeling stressed means you're weak.\"","myth":{"un":"Stress is a sign of weakness.","re":"Stress is a normal response to pressure that everyone feels.","why":"Even strong, capable people get stressed."},"relearn":"Stress is normal under pressure, not a sign of weakness.","persona":"Aarav","source":"stress / de-stigmatise"},
  {"id":"mm-022","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Your marks decide your whole worth.\"","myth":{"un":"My exam marks decide how much I'm worth.","re":"Marks measure one test, not your value as a person.","why":"Your worth is far bigger than a score."},"relearn":"Exam marks measure a test, not your worth as a person.","persona":"Diya","source":"exam pressure / India"},
  {"id":"mm-023","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"You should be able to handle everything on your own.\"","myth":{"un":"I should handle all my stress completely alone.","re":"Everyone needs support sometimes; sharing the load is wise.","why":"No one copes with everything alone."},"relearn":"Sharing the load is wise; no one copes alone.","persona":"any","source":"stress / help-seeking"},
  {"id":"mm-024","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: what's one thing that stresses you most right now?","prompt":"Name it (just to yourself).","options":["Exams","Friend stuff","Family stuff","Comparing myself"],"affirm":"Naming the stressor is the first step to handling it.","relearn":"Naming what stresses you helps you start to handle it.","persona":"any","source":"self-awareness"},
  {"id":"mm-025","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: a little stress before something big is your body getting ready. Reframe it?","prompt":"What do you think?","options":["Yes","It's energy","Less scary now"],"affirm":"Some nerves are just your body powering up to do well.","relearn":"A little pre-event stress is your body getting ready.","persona":"any","source":"reframing"},
  {"id":"mm-026","cat":"stress-and-pressure","type":"branch","hook":"Pressure from everywhere is piling up and you feel close to tears.","options":[{"text":"Step away, breathe, and let the feeling out safely","consequence":"Releasing it gently helps you reset.","outcome":"regulated","best":true},{"text":"Push it all down and carry on","consequence":"Letting feelings out safely beats bottling them up."}],"debrief":"Letting a big feeling out safely is healthier than burying it.","relearn":"It's okay to step away and let big feelings out safely.","persona":"Aarav","source":"emotion regulation"},
  // Handling rejection
  {"id":"mm-027","cat":"handling-rejection","type":"branch","hook":"You weren't picked for the team and feel crushed.","options":[{"text":"Let yourself feel sad, then plan to try again or find another spot","consequence":"You honour the hurt and keep going.","outcome":"resilient","best":true},{"text":"Decide you're worthless at everything","consequence":"One 'no' isn't about your whole worth; feel it, then keep going."}],"debrief":"Rejection hurts and passes; it isn't a verdict on all of you.","relearn":"A rejection stings but isn't a verdict on your whole worth.","persona":"Aarav","source":"rejection / resilience"},
  {"id":"mm-028","cat":"handling-rejection","type":"branch","hook":"A friend didn't invite you to something and it really hurts.","options":[{"text":"Feel it, then check in kindly instead of assuming the worst","consequence":"You may learn it wasn't a snub at all.","outcome":"grounded","best":true},{"text":"Decide nobody likes you","consequence":"Check before concluding; one miss isn't 'nobody likes me'."}],"debrief":"One left-out moment isn't proof you're unliked.","relearn":"Being left out once isn't proof that no one likes you.","persona":"Diya","source":"rejection / thinking traps"},
  {"id":"mm-029","cat":"handling-rejection","type":"branch","hook":"You failed a test you studied hard for.","options":[{"text":"Be kind to yourself, then learn what to try differently","consequence":"You bounce back wiser.","outcome":"growth","best":true},{"text":"Call yourself stupid and give up","consequence":"Kindness plus a new plan beats harsh self-blame."}],"debrief":"A failure is information for next time, not proof you're 'stupid'.","relearn":"Treat a failure as a lesson, not a label.","persona":"any","source":"rejection / growth mindset"},
  {"id":"mm-030","cat":"handling-rejection","type":"branch","hook":"Someone you liked as a friend pulled away.","options":[{"text":"Let yourself be sad, lean on other friends, stay open","consequence":"You heal and keep your circle warm.","outcome":"resilient","best":true},{"text":"Shut everyone out","consequence":"Leaning on others helps more than shutting them out."}],"debrief":"Losing one connection doesn't mean closing all of them.","relearn":"When one friendship fades, lean on others; stay open.","persona":"Diya","source":"rejection / connection"},
  {"id":"mm-031","cat":"handling-rejection","type":"branch","hook":"You made a mistake in front of everyone and feel like hiding forever.","options":[{"text":"Remind yourself everyone messes up; let the moment pass","consequence":"The embarrassment fades faster than you fear.","outcome":"resilient","best":true},{"text":"Replay it forever and avoid people","consequence":"Embarrassment fades; everyone has these moments."}],"debrief":"Embarrassing moments pass; they feel bigger than they are.","relearn":"Everyone has cringe moments; they pass faster than you think.","persona":"any","source":"rejection / self-compassion"},
  {"id":"mm-032","cat":"handling-rejection","type":"branch","hook":"You keep dwelling on a disappointment from days ago.","options":[{"text":"Do one small kind or fun thing to shift the loop","consequence":"You gently break the rumination.","outcome":"unstuck","best":true},{"text":"Keep replaying it on repeat","consequence":"A small positive action can interrupt the dwelling."}],"debrief":"Dwelling deepens a rut; a small action helps you climb out.","relearn":"Break a dwelling loop with one small, kind action.","persona":"any","source":"rumination"},
  {"id":"mm-033","cat":"handling-rejection","type":"strike-rewrite","hook":"\"If someone rejects me, it means I'm not good enough.\"","myth":{"un":"Being rejected means I'm not good enough.","re":"Rejection often isn't about your worth at all.","why":"Many reasons have nothing to do with you."},"relearn":"Rejection usually isn't about your worth.","persona":"Diya","source":"rejection / cognitive"},
  {"id":"mm-034","cat":"handling-rejection","type":"strike-rewrite","hook":"\"Failing once means I'll always fail.\"","myth":{"un":"Failing once means I'll fail at everything forever.","re":"One setback doesn't decide your future.","why":"People grow and improve all the time."},"relearn":"One failure doesn't decide your future.","persona":"Aarav","source":"resilience"},
  {"id":"mm-035","cat":"handling-rejection","type":"strike-rewrite","hook":"\"I should never feel sad about being left out.\"","myth":{"un":"I shouldn't feel sad about being left out.","re":"It's natural to feel hurt; the feeling is allowed.","why":"Pretending not to care doesn't help."},"relearn":"It's natural and okay to feel hurt by being left out.","persona":"any","source":"emotional validation"},
  {"id":"mm-036","cat":"handling-rejection","type":"role-play","hook":"A friend is crushed after being rejected.","setup":"Comfort them. Say:","yourLine":[{"text":"\"That really hurts. I'm here, and it's not about your worth.\"","best":true},{"text":"\"Just get over it.\""}],"relearn":"You can comfort a friend by validating the hurt, not dismissing it.","persona":"any","source":"peer support"},
  {"id":"mm-037","cat":"handling-rejection","type":"role-play","hook":"You need to be kinder to yourself after a setback.","setup":"Talk to yourself like a friend. Say:","yourLine":[{"text":"\"That was hard. I'll be okay, and I can try again.\"","best":true},{"text":"\"I'm useless and always will be.\""}],"relearn":"Talk to yourself as kindly as you'd talk to a friend.","persona":"any","source":"self-compassion"},
  {"id":"mm-038","cat":"handling-rejection","type":"reflect","hook":"Lensy: think of a past disappointment you got through. Proof you can again?","prompt":"What do you think?","options":["Yes","I've bounced back before","I'm stronger than I feel"],"affirm":"You've survived hard things before; that's real evidence you can again.","relearn":"Remembering past bounce-backs reminds you that you can cope.","persona":"any","source":"resilience"},
  {"id":"mm-039","cat":"handling-rejection","type":"reflect","hook":"Lensy: a 'no' can sometimes point you to a better 'yes' later. Open to that?","prompt":"What do you think?","options":["Maybe","I hope so","New doors"],"affirm":"Some closed doors gently steer you to better ones.","relearn":"A rejection can sometimes open the way to something better.","persona":"any","source":"reframing"},
  {"id":"mm-040","cat":"handling-rejection","type":"sort","hook":"Sort: kind self-talk, or harsh self-talk?","persona":"any","source":"self-talk","relearn":"Kind self-talk helps you recover; harsh self-talk keeps you stuck.","items":[{"id":"a","text":"\"I'll be okay\""},{"id":"b","text":"\"I'm a total failure\""},{"id":"c","text":"\"I can try again\""},{"id":"d","text":"\"Everyone hates me\""},{"id":"e","text":"\"That hurt, and it'll pass\""},{"id":"f","text":"\"I ruin everything\""}],"bins":[{"id":"kind","label":"Kind self-talk","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"}},
  // Your mind-care toolkit
  {"id":"mm-041","cat":"mind-care-toolkit","type":"build","hook":"Build your calm-down toolkit. Pick the healthy tools.","prompt":"Choose what belongs in a mind-care kit.","pieces":["slow breathing","talk to someone you trust","move your body","do something you enjoy"],"mode":"assemble","key":["slow breathing","talk to someone you trust","move your body","do something you enjoy"],"relearn":"A mind-care kit: breathe, talk, move, and do what you enjoy.","persona":"any","source":"coping toolkit"},
  {"id":"mm-042","cat":"mind-care-toolkit","type":"build","hook":"Build the steps of slow 'square' breathing.","prompt":"Put the calm-breathing steps in order.","pieces":["breathe in for four","hold for four","breathe out for four","pause for four"],"mode":"sequence","key":["breathe in for four","hold for four","breathe out for four","pause for four"],"relearn":"Slow square breathing calms your body: in, hold, out, pause.","persona":"any","source":"breathing technique"},
  {"id":"mm-043","cat":"mind-care-toolkit","type":"build","hook":"Build a wind-down routine for a hard day.","prompt":"Order a calming evening.","pieces":["finish screens early","do something soothing","slow breaths in bed","sleep"],"mode":"sequence","key":["finish screens early","do something soothing","slow breaths in bed","sleep"],"relearn":"A calming wind-down helps your mind rest after a hard day.","persona":"any","source":"sleep / routine"},
  {"id":"mm-044","cat":"mind-care-toolkit","type":"build","hook":"Build a 'shrink the problem' plan.","prompt":"Order how to handle something overwhelming.","pieces":["name the problem","break it into small parts","do the first small part","ask for help if stuck"],"mode":"sequence","key":["name the problem","break it into small parts","do the first small part","ask for help if stuck"],"relearn":"Shrink a big problem: name it, break it, start small, ask if stuck.","persona":"Aarav","source":"problem-solving"},
  {"id":"mm-045","cat":"mind-care-toolkit","type":"build","hook":"Build a quick mood-lifter list (healthy ones).","prompt":"Pick healthy mood-lifters.","pieces":["go outside","listen to music you love","play or move","spend time with someone kind"],"mode":"assemble","key":["go outside","listen to music you love","play or move","spend time with someone kind"],"relearn":"Healthy mood-lifters: nature, music, movement, kind company.","persona":"any","source":"behavioural activation"},
  {"id":"mm-046","cat":"mind-care-toolkit","type":"build","hook":"Build the 'name it to tame it' steps.","prompt":"Order how to handle a big feeling.","pieces":["notice the feeling","name it","breathe","choose what it needs"],"mode":"sequence","key":["notice the feeling","name it","breathe","choose what it needs"],"relearn":"Notice, name, breathe, then choose what the feeling needs.","persona":"any","source":"emotion regulation"},
  {"id":"mm-047","cat":"mind-care-toolkit","type":"build","hook":"Build a 'grounding' move for a panicky moment.","prompt":"Order a simple grounding step.","pieces":["feel your feet on the floor","name five things you see","take slow breaths","let the wave pass"],"mode":"sequence","key":["feel your feet on the floor","name five things you see","take slow breaths","let the wave pass"],"relearn":"Grounding (feet, look, breathe) helps a panicky moment pass.","persona":"any","source":"grounding technique"},
  {"id":"mm-048","cat":"mind-care-toolkit","type":"branch","hook":"A wave of worry hits before bed.","options":[{"text":"Use slow breathing and a calming thought","consequence":"Your body settles and the wave passes.","outcome":"calm","best":true},{"text":"Lie there letting worries spiral","consequence":"Slow breathing helps the worry wave pass."}],"debrief":"Breathing tools turn down the volume on worry.","relearn":"Slow breathing helps a worry wave settle.","persona":"any","source":"coping in action"},
  {"id":"mm-049","cat":"mind-care-toolkit","type":"branch","hook":"You feel a big feeling building in class.","options":[{"text":"Quietly breathe and ground yourself until it eases","consequence":"You ride it out calmly.","outcome":"regulated","best":true},{"text":"Let it explode or freeze","consequence":"A quiet grounding move helps you ride the feeling out."}],"debrief":"You can use a calm tool even in the middle of class.","relearn":"You can quietly use a calming tool wherever you are.","persona":"any","source":"coping in action"},
  {"id":"mm-050","cat":"mind-care-toolkit","type":"branch","hook":"You've had a heavy day and don't know what you need.","options":[{"text":"Try one toolkit tool, rest, a walk, or a chat","consequence":"You give your mind what it needs.","outcome":"cared","best":true},{"text":"Numb out on screens for hours","consequence":"A real toolkit tool helps more than numbing out."}],"debrief":"On a heavy day, one caring tool beats numbing out.","relearn":"Reach for a real coping tool on a heavy day.","persona":"any","source":"coping in action"},
  {"id":"mm-051","cat":"mind-care-toolkit","type":"branch","hook":"Anger is rising fast and you might say something you'll regret.","options":[{"text":"Step away and breathe before responding","consequence":"You cool down and avoid harm.","outcome":"regulated","best":true},{"text":"Lash out right away","consequence":"A pause and a breath prevent regret."}],"debrief":"A pause when angry protects you and others.","relearn":"Step away and breathe before acting on anger.","persona":"Aarav","source":"anger management (links g41)"},
  {"id":"mm-052","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: a healthy coping tool, or an unhealthy one?","items":[{"id":"a","text":"Talking to someone you trust"},{"id":"b","text":"Taking it out on others"},{"id":"c","text":"Moving your body"},{"id":"d","text":"Hiding from everyone for days"},{"id":"e","text":"Resting when you're worn out"},{"id":"f","text":"Bottling it all up"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"unhealthy","label":"Unhealthy","valence":"neg"}],"key":{"a":"healthy","b":"unhealthy","c":"healthy","d":"unhealthy","e":"healthy","f":"unhealthy"},"relearn":"Talking, moving and resting help; lashing out and shutting in don't."},
  {"id":"mm-053","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: calms the body, or revs up the stress?","items":[{"id":"a","text":"Slow, deep breaths"},{"id":"b","text":"Holding your breath in panic"},{"id":"c","text":"A gentle walk"},{"id":"d","text":"Endless worried scrolling"},{"id":"e","text":"A long, easy stretch"},{"id":"f","text":"Clenching your fists tight"}],"bins":[{"id":"calms","label":"Calms the body","valence":"pos"},{"id":"revs","label":"Revs up stress","valence":"neg"}],"key":{"a":"calms","b":"revs","c":"calms","d":"revs","e":"calms","f":"revs"},"relearn":"Slow breaths, gentle walks and stretches calm the body."},
  {"id":"mm-054","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: which tool fits, in-the-moment calm, or longer-term care?","items":[{"id":"a","text":"Square breathing right now"},{"id":"b","text":"Getting enough sleep daily"},{"id":"c","text":"Grounding during a panic"},{"id":"d","text":"Regular time with friends"},{"id":"e","text":"A quick walk to cool off"},{"id":"f","text":"A hobby you keep up"}],"bins":[{"id":"now","label":"In-the-moment","valence":"pos"},{"id":"longterm","label":"Longer-term care","valence":"neutral"}],"key":{"a":"now","b":"longterm","c":"now","d":"longterm","e":"now","f":"longterm"},"relearn":"Some tools calm you now; others keep your mind well over time."},
  {"id":"mm-055","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the feeling to a helpful tool.","pairs":[{"left":"Panic","right":"Grounding and breathing"},{"left":"Sadness","right":"Talk to someone kind"},{"left":"Restlessness","right":"Move your body"},{"left":"Overwhelm","right":"Break it into small steps"},{"left":"Anger","right":"Step away to cool down"}],"relearn":"Different feelings respond to different healthy tools."},
  {"id":"mm-056","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the tool to what it does.","pairs":[{"left":"Slow breathing","right":"Calms the body"},{"left":"Talking it out","right":"Lightens the load"},{"left":"Movement","right":"Shifts the mood"},{"left":"Rest","right":"Refills your energy"},{"left":"Grounding","right":"Steadies a racing mind"}],"relearn":"Each coping tool helps your mind in its own way."},
  // Asking for help
  {"id":"mm-057","cat":"ask-for-help","type":"role-play","hook":"A feeling is too big to handle alone.","setup":"Reach out. Say:","yourLine":[{"text":"\"I'm not okay right now, can we talk?\"","best":true},{"text":"Say nothing and struggle alone"}],"relearn":"You can tell a trusted person 'I'm not okay, can we talk?'.","persona":"any","source":"help-seeking"},
  {"id":"mm-058","cat":"ask-for-help","type":"role-play","hook":"You want to tell a parent you've been feeling low.","setup":"Open up simply. Say:","yourLine":[{"text":"\"I've been feeling really low lately, I need some help.\"","best":true},{"text":"\"Nothing's wrong\" (when something is)"}],"relearn":"You can name a low mood and ask a parent for help.","persona":"Rohit","source":"help-seeking"},
  {"id":"mm-059","cat":"ask-for-help","type":"role-play","hook":"A friend confides they feel really down.","setup":"Support and guide them. Say:","yourLine":[{"text":"\"Thank you for telling me. Let's also talk to an adult who can help.\"","best":true},{"text":"\"Don't tell anyone, just forget it.\""}],"relearn":"Support a struggling friend and help them reach a trusted adult.","persona":"Asha","source":"peer support / help-routing"},
  {"id":"mm-060","cat":"ask-for-help","type":"role-play","hook":"You're nervous to ask the school counsellor for help.","setup":"Take the step. Say:","yourLine":[{"text":"\"Can I talk to you about something that's bothering me?\"","best":true},{"text":"Walk away and keep it in"}],"relearn":"A counsellor is there to help; you can simply ask to talk.","persona":"any","source":"help-seeking"},
  {"id":"mm-061","cat":"ask-for-help","type":"role-play","hook":"Someone says talking about feelings is 'for the weak'.","setup":"Reframe it. Say:","yourLine":[{"text":"\"Asking for help is actually strong.\"","best":true},{"text":"\"You're right, I'll keep quiet.\""}],"relearn":"You can push back on the idea that help-seeking is weak.","persona":"Aarav","source":"de-stigmatise"},
  {"id":"mm-062","cat":"ask-for-help","type":"branch","hook":"Heavy feelings have lasted a long time and won't lift.","options":[{"text":"Tell a trusted adult; ask them to help you find support","consequence":"You get the care you need.","outcome":"supported","best":true},{"text":"Keep waiting for it to pass alone","consequence":"Long-lasting heavy feelings deserve a trusted adult's help."}],"debrief":"Feelings that stay heavy for a long time are a sign to get help.","relearn":"If heavy feelings last, tell a trusted adult and get support.","persona":"any","source":"help-seeking / safety"},
  {"id":"mm-063","cat":"ask-for-help","type":"branch","hook":"You don't know who's safe to talk to about your feelings.","options":[{"text":"Pick any trusted adult, or call Childline 1098 / 112","consequence":"You find a caring first listener.","outcome":"resourceful","best":true},{"text":"Decide there's no one","consequence":"There's always someone, a trusted adult or Childline 1098."}],"debrief":"There's always somewhere to turn, including Childline 1098.","relearn":"A trusted adult or Childline 1098 is always there to listen.","persona":"Asha","source":"help-seeking / helpline"},
  {"id":"mm-064","cat":"ask-for-help","type":"branch","hook":"You told one adult and they brushed it off.","options":[{"text":"Tell another trusted adult; keep going until you're heard","consequence":"Someone listens and helps.","outcome":"persistent","best":true},{"text":"Give up on getting help","consequence":"If one adult misses it, tell another, don't give up."}],"debrief":"If the first person doesn't hear you, tell someone else.","relearn":"Keep reaching out until a trusted adult really listens.","persona":"any","source":"help-seeking / persistence"},
  {"id":"mm-065","cat":"ask-for-help","type":"branch","hook":"A friend hints they're having scary or very dark thoughts.","options":[{"text":"Take it seriously and tell a trusted adult right away","consequence":"You help keep your friend safe.","outcome":"caring","best":true},{"text":"Keep it a secret because they asked","consequence":"For safety, this is a 'tell a trusted adult now' moment."}],"debrief":"Some worries are too big to hold alone, telling an adult keeps a friend safe.","relearn":"If a friend has dark thoughts, tell a trusted adult right away.","persona":"Asha","source":"safeguarding / help-routing"},
  {"id":"mm-066","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Asking for help with feelings is shameful.\"","myth":{"un":"Asking for help with my feelings is shameful.","re":"Reaching out is brave and a sign of strength.","why":"Everyone needs support sometimes."},"relearn":"Reaching out for help is brave, not shameful.","persona":"Aarav","source":"de-stigmatise"},
  {"id":"mm-067","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Counsellors and helplines are only for 'crazy' people.\"","myth":{"un":"Counsellors and helplines are only for 'crazy' people.","re":"They're for anyone who needs a listening ear or support.","why":"Getting support is normal and healthy."},"relearn":"Counsellors and helplines are for anyone who needs support.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-068","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Talking about a problem won't change anything.\"","myth":{"un":"Talking about a problem is pointless.","re":"Sharing a worry often makes it lighter and clearer.","why":"A problem shared is a problem halved."},"relearn":"Talking about a worry can make it lighter and clearer.","persona":"any","source":"help-seeking"},
  {"id":"mm-069","cat":"ask-for-help","type":"match","hook":"Match the situation to where to turn.","pairs":[{"left":"A worry at school","right":"A teacher or counsellor"},{"left":"Feelings at home","right":"A trusted family adult"},{"left":"An urgent crisis","right":"Childline 1098 / 112"},{"left":"A body or health worry","right":"An ASHA or NGO didi"},{"left":"A lasting low mood","right":"A school counsellor's care"}],"relearn":"Different worries have a right person or helpline to turn to.","persona":"Asha","source":"help-routing / UNESCO 5.5"},
  {"id":"mm-070","cat":"ask-for-help","type":"match","hook":"Match: myth about help, to the truth.","pairs":[{"left":"\"Help is for the weak\"","right":"Help is for everyone"},{"left":"\"I'll be a burden\"","right":"People want to help"},{"left":"\"Nothing will help\"","right":"Support really does help"},{"left":"\"I should cope alone\"","right":"Asking is the strong move"},{"left":"\"It's too small to tell\"","right":"If it hurts, it counts"}],"relearn":"The fears that stop us asking for help are usually untrue.","persona":"any","source":"de-stigmatise"},
  // Be kind to your mind
  {"id":"mm-071","cat":"be-kind-to-mind","type":"branch","hook":"You catch yourself thinking \"I'm so stupid\" after a mistake.","options":[{"text":"Swap it for what you'd tell a friend: \"that's okay, try again\"","consequence":"Kind self-talk softens the blow.","outcome":"self-kind","best":true},{"text":"Repeat 'I'm stupid' all day","consequence":"Talk to yourself like a friend, not a critic."}],"debrief":"Be as kind to yourself as you'd be to a good friend.","relearn":"Replace harsh self-talk with what you'd tell a friend.","persona":"any","source":"self-compassion"},
  {"id":"mm-072","cat":"be-kind-to-mind","type":"branch","hook":"You're tempted to skip rest and push through exhaustion.","options":[{"text":"Let yourself rest; rest is productive too","consequence":"You recharge and do better after.","outcome":"balanced","best":true},{"text":"Push till you crash","consequence":"Rest isn't lazy; it's part of doing well."}],"debrief":"Rest is part of looking after your mind, not a weakness.","relearn":"Rest is productive and part of mind-care.","persona":"any","source":"rest / balance"},
  {"id":"mm-073","cat":"be-kind-to-mind","type":"branch","hook":"You feel guilty for taking time to do something you enjoy.","options":[{"text":"Allow it; joy refuels your mind","consequence":"You return lighter and steadier.","outcome":"balanced","best":true},{"text":"Feel you must always be 'productive'","consequence":"Joy and downtime are fuel, not waste."}],"debrief":"Doing things you enjoy is real mind-care, not slacking.","relearn":"Enjoyable downtime refuels your mind; it's not slacking.","persona":"any","source":"self-care"},
  {"id":"mm-074","cat":"be-kind-to-mind","type":"branch","hook":"A classmate is being teased for seeing a counsellor.","options":[{"text":"Stand up: \"getting help is smart, leave them alone\"","consequence":"You reduce the stigma for everyone.","outcome":"ally","best":true},{"text":"Join the teasing","consequence":"Defending help-seeking makes it safer for everyone."}],"debrief":"Standing up for help-seekers reduces mental-health stigma.","relearn":"Defend people who seek help; it's smart, not shameful.","persona":"any","source":"de-stigmatise / upstander (links g19)"},
  {"id":"mm-075","cat":"be-kind-to-mind","type":"branch","hook":"Your inner voice is being a harsh critic today.","options":[{"text":"Notice it and gently talk back with kindness","consequence":"You loosen the critic's grip.","outcome":"self-kind","best":true},{"text":"Believe every harsh thought","consequence":"You don't have to believe every harsh thought."}],"debrief":"You can notice harsh thoughts without believing them.","relearn":"You don't have to believe every harsh thought you have.","persona":"any","source":"cognitive defusion"},
  {"id":"mm-076","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Being hard on myself makes me do better.\"","myth":{"un":"Being harsh with myself pushes me to do better.","re":"Self-kindness helps you grow more than harshness.","why":"Cruelty drains you; encouragement fuels you."},"relearn":"Self-kindness helps you improve more than self-criticism.","persona":"any","source":"self-compassion"},
  {"id":"mm-077","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"I have to be happy and positive all the time.\"","myth":{"un":"I must feel happy and positive all the time.","re":"All feelings are okay; you don't have to fake being fine.","why":"Forcing happiness ignores real feelings."},"relearn":"You don't have to be happy all the time; all feelings are okay.","persona":"any","source":"emotional honesty"},
  {"id":"mm-078","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Other people's feelings matter more than mine.\"","myth":{"un":"My feelings matter less than everyone else's.","re":"Your feelings matter just as much as anyone's.","why":"You deserve care too."},"relearn":"Your feelings matter just as much as anyone else's.","persona":"Diya","source":"self-worth"},
  {"id":"mm-079","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: name one kind thing you could say to yourself today.","prompt":"Pick one.","options":["\"I'm doing my best\"","\"I'm allowed to rest\"","\"I'll be okay\""],"affirm":"Saying it counts; your mind hears your kindness.","relearn":"A kind word to yourself genuinely helps your mind.","persona":"any","source":"self-compassion"},
  {"id":"mm-080","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what's one small thing that reliably lifts your mood?","prompt":"Think of one.","options":["A favourite song","Time outside","A chat with someone","A hobby"],"affirm":"Keep that close, it's a tool you can use any time.","relearn":"Knowing your reliable mood-lifters gives you a ready tool.","persona":"any","source":"self-care"},
  {"id":"mm-081","cat":"be-kind-to-mind","type":"role-play","hook":"A friend is being very hard on themselves.","setup":"Offer kindness. Say:","yourLine":[{"text":"\"Be kind to yourself, you'd forgive a friend for this.\"","best":true},{"text":"\"Yeah, you did mess up.\""}],"relearn":"You can help a friend be kinder to themselves.","persona":"any","source":"self-compassion / peer"},
  {"id":"mm-082","cat":"be-kind-to-mind","type":"sort","hook":"Sort: kind-to-your-mind, or hard-on-your-mind?","items":[{"id":"a","text":"Resting when tired"},{"id":"b","text":"Never forgiving a mistake"},{"id":"c","text":"Celebrating small wins"},{"id":"d","text":"Comparing yourself non-stop"},{"id":"e","text":"Talking when it's heavy"},{"id":"f","text":"Calling yourself names"}],"bins":[{"id":"kind","label":"Kind to your mind","valence":"pos"},{"id":"hard","label":"Hard on your mind","valence":"neg"}],"key":{"a":"kind","b":"hard","c":"kind","d":"hard","e":"kind","f":"hard"},"relearn":"Rest, celebrating wins and talking are kind; comparison and name-calling are hard.","persona":"any","source":"self-care"},
  {"id":"mm-083","cat":"be-kind-to-mind","type":"build","hook":"Build your personal mind-care promise.","prompt":"Pick promises to your own mind.","pieces":["I'll rest when I need to","I'll talk to someone when it's heavy","I'll be kind to myself","I'll ask for help if it's too big"],"mode":"assemble","key":["I'll rest when I need to","I'll talk to someone when it's heavy","I'll be kind to myself","I'll ask for help if it's too big"],"relearn":"Your mind-care promise: rest, talk, be kind, and ask for help.","persona":"any","source":"consolidation"},
  {"id":"mm-084","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: biggest take-away from Mind Matters?","prompt":"Pick your motto.","options":["My mind matters","Feelings pass","I have tools","Asking for help is strong"],"affirm":"Your mind matters, you have tools, and help is always there.","relearn":"Your mind matters, feelings pass, you have tools, and help is strong.","persona":"any","source":"consolidation"},
  {"id":"mm-900","cat":"ask-for-help","type":"role-play","hook":"You want to tell your class teacher you're struggling.","setup":"Catch her after class. Say:","yourLine":[{"text":"\"Ma'am, I've been having a hard time. Can we talk for a minute?\"","best":true},{"text":"Pretend everything is fine and leave"}],"relearn":"You can simply ask a teacher for a minute to talk.","persona":"any","source":"help-seeking"},
  {"id":"mm-901","cat":"ask-for-help","type":"role-play","hook":"You feel low but worry you'll bother your mother.","setup":"Tell her anyway. Say:","yourLine":[{"text":"\"Maa, I know you're busy, but I really need to talk.\"","best":true},{"text":"Wait for a 'perfect time' that never comes"}],"relearn":"You're never a burden for asking someone you trust to talk.","persona":"any","source":"help-seeking"},
  {"id":"mm-902","cat":"ask-for-help","type":"role-play","hook":"Aarav's friends say boys shouldn't cry or complain.","setup":"Speak up for yourself. Say:","yourLine":[{"text":"\"Talking about feelings takes guts. I'm asking for help.\"","best":true},{"text":"\"Yeah, I'll just deal with it alone.\""}],"relearn":"Asking for help is brave, whoever you are.","persona":"Aarav","source":"de-stigmatise"},
  {"id":"mm-903","cat":"ask-for-help","type":"role-play","hook":"The ASHA didi visits and asks how you're doing.","setup":"Be honest with her. Say:","yourLine":[{"text":"\"Honestly, I've been worried a lot lately. Can you help?\"","best":true},{"text":"\"I'm fine\" (when you're not)"}],"relearn":"An ASHA or NGO didi is a safe person to be honest with.","persona":"Asha","source":"help-routing"},
  {"id":"mm-904","cat":"ask-for-help","type":"role-play","hook":"You finally want to tell your elder sister what's wrong.","setup":"Open up to her. Say:","yourLine":[{"text":"\"Didi, something's been bothering me. Will you listen?\"","best":true},{"text":"Change the subject and stay quiet"}],"relearn":"A trusted sibling can be your first listener.","persona":"any","source":"help-seeking"},
  {"id":"mm-905","cat":"ask-for-help","type":"role-play","hook":"Asha asks if you'd like to meet the school counsellor.","setup":"Take her up on it. Say:","yourLine":[{"text":"\"Yes, please. Can you come with me the first time?\"","best":true},{"text":"\"No, people will think I'm weird.\""}],"relearn":"It's okay to ask someone to come with you the first time.","persona":"Asha","source":"help-routing"},
  {"id":"mm-906","cat":"ask-for-help","type":"role-play","hook":"A friend texts that they feel hopeless tonight.","setup":"Reply with care. Say:","yourLine":[{"text":"\"I'm really glad you told me. Let's tell an adult who can help.\"","best":true},{"text":"\"Get some sleep, you'll be fine.\""}],"relearn":"Take a friend's dark feelings seriously and reach an adult.","persona":"any","source":"safeguarding"},
  {"id":"mm-907","cat":"ask-for-help","type":"role-play","hook":"You don't have the words for what you're feeling.","setup":"It's okay to start small. Say:","yourLine":[{"text":"\"I can't explain it yet, but I'm not okay. Can you help me?\"","best":true},{"text":"Stay silent until you 'figure it out' alone"}],"relearn":"You don't need perfect words to ask for help.","persona":"any","source":"help-seeking"},
  {"id":"mm-908","cat":"ask-for-help","type":"role-play","hook":"Rohit asks his son what's been going on lately.","setup":"Let your dad in. Say:","yourLine":[{"text":"\"Papa, I've been stressed and I don't know what to do.\"","best":true},{"text":"\"Nothing, leave it.\""}],"relearn":"A caring adult wants to know when you're struggling.","persona":"Rohit","source":"help-seeking"},
  {"id":"mm-909","cat":"ask-for-help","type":"role-play","hook":"You're scared the counsellor will tell your parents everything.","setup":"Just ask first. Say:","yourLine":[{"text":"\"Before we start, can you tell me what stays private?\"","best":true},{"text":"Decide not to go at all"}],"relearn":"You're allowed to ask how your privacy is protected.","persona":"any","source":"help-seeking"},
  {"id":"mm-910","cat":"ask-for-help","type":"role-play","hook":"A classmate seems sad and alone every day.","setup":"Reach out gently. Say:","yourLine":[{"text":"\"You seem down lately. I'm here if you want to talk.\"","best":true},{"text":"Ignore it, it's not your problem"}],"relearn":"Offering to listen can help a friend start asking for help.","persona":"any","source":"peer support"},
  {"id":"mm-911","cat":"ask-for-help","type":"role-play","hook":"You've tried to ask twice and your voice keeps shaking.","setup":"Try once more anyway. Say:","yourLine":[{"text":"\"This is hard for me to say, but I need some help.\"","best":true},{"text":"Decide your shaky voice means you should stop"}],"relearn":"It's okay if your voice shakes; saying it still counts.","persona":"any","source":"help-seeking"},
  {"id":"mm-912","cat":"ask-for-help","type":"role-play","hook":"Diya wants to tell a teacher she's being left out and teased.","setup":"Name it plainly. Say:","yourLine":[{"text":"\"Some classmates keep teasing me and it's really hurting.\"","best":true},{"text":"Laugh it off and say it's nothing"}],"relearn":"You can tell a teacher exactly what's hurting you.","persona":"Diya","source":"help-seeking"},
  {"id":"mm-913","cat":"ask-for-help","type":"role-play","hook":"You feel too embarrassed to bring up your feelings at home.","setup":"A note can be a start. Say:","yourLine":[{"text":"\"I wrote this because it's hard to say out loud. Can we talk?\"","best":true},{"text":"Tear up the note and say nothing"}],"relearn":"Writing it down first is a real, brave way to ask.","persona":"any","source":"help-seeking"},
  {"id":"mm-914","cat":"ask-for-help","type":"role-play","hook":"A trusted uncle asks if you're alright before he leaves.","setup":"Be truthful. Say:","yourLine":[{"text":"\"Actually, not really. Can I talk to you about something?\"","best":true},{"text":"Smile and say 'all good'"}],"relearn":"When someone you trust asks, it's okay to say the truth.","persona":"any","source":"help-seeking"},
  {"id":"mm-915","cat":"ask-for-help","type":"role-play","hook":"You worry asking for help means you've 'failed' on your own.","setup":"Reframe it out loud. Say:","yourLine":[{"text":"\"Asking for help is me taking care of myself, not failing.\"","best":true},{"text":"\"I should be able to handle this alone.\""}],"relearn":"Reaching out is taking care of yourself, not failing.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-916","cat":"ask-for-help","type":"role-play","hook":"Your coaching is too much but you're afraid to say so.","setup":"Tell a parent honestly. Say:","yourLine":[{"text":"\"The coaching load is too much for me right now. Can we talk?\"","best":true},{"text":"Keep pushing until you burn out"}],"relearn":"You can tell a parent when the pressure is too much.","persona":"any","source":"help-seeking"},
  {"id":"mm-917","cat":"ask-for-help","type":"role-play","hook":"A friend confides, then says 'don't tell anyone, promise'.","setup":"Be a caring, honest friend. Say:","yourLine":[{"text":"\"I care too much to keep this secret. Let's find help together.\"","best":true},{"text":"\"Okay, I promise I'll never tell.\""}],"relearn":"Some worries are too big to keep secret; getting help is kind.","persona":"any","source":"safeguarding"},
  {"id":"mm-918","cat":"ask-for-help","type":"role-play","hook":"You want to call Childline but feel nervous to dial.","setup":"Remind yourself, then call. Say:","yourLine":[{"text":"\"It's okay to be nervous. I can call Childline 1098 and just talk.\"","best":true},{"text":"Put the phone down and keep it all in"}],"relearn":"Childline 1098 is there to listen, even if you feel nervous.","persona":"any","source":"helpline"},
  {"id":"mm-919","cat":"ask-for-help","type":"branch","hook":"You've felt heavy and tearful for weeks and hidden it well.","options":[{"text":"Tell a trusted adult it's been weeks and ask for support","consequence":"Someone finally helps carry it with you.","outcome":"supported","best":true},{"text":"Keep hiding it so no one worries","consequence":"Feelings this heavy for weeks deserve a trusted adult's help."}],"debrief":"When a heavy feeling lasts for weeks, that's the signal to tell someone.","relearn":"Lasting heavy feelings are a sign to tell a trusted adult.","persona":"any","source":"help-seeking / safety"},
  {"id":"mm-920","cat":"ask-for-help","type":"branch","hook":"You want help but every adult around seems too busy.","options":[{"text":"Ask one anyway, or call Childline 1098 / 112","consequence":"You reach a listener who has time for you.","outcome":"resourceful","best":true},{"text":"Decide everyone's too busy for you","consequence":"There's always someone, a trusted adult or Childline 1098."}],"debrief":"Even when adults look busy, asking or calling Childline still works.","relearn":"Pick any trusted adult, or call Childline 1098 / 112.","persona":"any","source":"help-seeking / helpline"},
  {"id":"mm-921","cat":"ask-for-help","type":"branch","hook":"You're worried a friend's secret about feeling unsafe is too big.","options":[{"text":"Tell a trusted adult so your friend gets real help","consequence":"Your friend gets the support they need.","outcome":"caring","best":true},{"text":"Try to fix it all by yourself","consequence":"Some worries are too big for one kid; an adult should help."}],"debrief":"You can be a great friend and still hand a big worry to an adult.","relearn":"When a friend's worry is too big, bring in a trusted adult.","persona":"Asha","source":"safeguarding"},
  {"id":"mm-922","cat":"ask-for-help","type":"branch","hook":"You feel ashamed about why you need help.","options":[{"text":"Ask anyway; the reason doesn't have to be 'big enough'","consequence":"You get heard, and the shame eases.","outcome":"brave","best":true},{"text":"Wait until it's 'serious enough' to deserve help","consequence":"You don't have to earn help; asking early is wise."}],"debrief":"You never have to wait for a crisis to deserve support.","relearn":"You don't have to wait for a crisis to ask for help.","persona":"any","source":"help-seeking"},
  {"id":"mm-923","cat":"ask-for-help","type":"branch","hook":"You told a friend you're struggling and they made a joke of it.","options":[{"text":"Tell someone who will take you seriously instead","consequence":"You find a person who really listens.","outcome":"persistent","best":true},{"text":"Decide no one will ever take you seriously","consequence":"One person missing it doesn't mean everyone will."}],"debrief":"If one person brushes you off, a different one will hear you.","relearn":"If one person doesn't hear you, tell another, don't give up.","persona":"any","source":"help-seeking / persistence"},
  {"id":"mm-924","cat":"ask-for-help","type":"branch","hook":"Exam stress is keeping you up at night, every night.","options":[{"text":"Tell a parent or teacher how bad the sleep loss is","consequence":"Together you find ways to ease the load.","outcome":"supported","best":true},{"text":"Drink more chai and push through alone","consequence":"Lost sleep this long is a sign to ask an adult for help."}],"debrief":"Stress that steals your sleep for weeks is worth telling an adult.","relearn":"Long-lasting stress signals are a reason to ask for help.","persona":"any","source":"help-seeking"},
  {"id":"mm-925","cat":"ask-for-help","type":"branch","hook":"You're not sure if what you feel is 'bad enough' to mention.","options":[{"text":"Mention it anyway and let the adult help you weigh it","consequence":"You get clarity and support, not judgement.","outcome":"wise","best":true},{"text":"Stay quiet until you're certain it's serious","consequence":"You don't have to diagnose yourself; just share it."}],"debrief":"You don't have to be sure it's serious to ask, the adult helps you tell.","relearn":"You can share a worry even when you're unsure it's 'big'.","persona":"any","source":"help-seeking"},
  {"id":"mm-926","cat":"ask-for-help","type":"branch","hook":"A new app friend says only they understand your sadness.","options":[{"text":"Tell a trusted real-life adult about the feelings too","consequence":"A safe adult helps you sort it out.","outcome":"safe","best":true},{"text":"Rely only on the online friend for support","consequence":"One online voice isn't enough; tell a trusted adult too."}],"debrief":"Online support is fine, but a trusted real-life adult should know too.","relearn":"For real support, tell a trusted adult, not only an online friend.","persona":"any","source":"help-routing / safety"},
  {"id":"mm-927","cat":"ask-for-help","type":"branch","hook":"You feel low and just want to sleep all day and skip everyone.","options":[{"text":"Tell one trusted person before pulling away completely","consequence":"You stay connected and get support.","outcome":"connected","best":true},{"text":"Shut everyone out and handle it alone","consequence":"Pulling away alone makes low feelings heavier; reach out."}],"debrief":"When you want to disappear, that's exactly when to tell someone.","relearn":"When you want to withdraw, reach out to one trusted person.","persona":"any","source":"help-seeking"},
  {"id":"mm-928","cat":"ask-for-help","type":"branch","hook":"You asked once, felt brave, but nothing changed yet.","options":[{"text":"Go back and say it's still hard and you need more help","consequence":"The adult takes a bigger step with you.","outcome":"persistent","best":true},{"text":"Decide asking was pointless","consequence":"Help can take more than one ask; it's okay to go back."}],"debrief":"Asking again isn't failing, it's making sure you're really helped.","relearn":"It's okay to ask again if the first time wasn't enough.","persona":"any","source":"help-seeking / persistence"},
  {"id":"mm-929","cat":"ask-for-help","type":"branch","hook":"You want help but worry your family has bigger problems.","options":[{"text":"Tell a trusted adult outside the family, like a teacher","consequence":"You get support without adding to home's load.","outcome":"resourceful","best":true},{"text":"Carry it silently so no one's burdened","consequence":"A teacher, didi or Childline 1098 can help when home is full."}],"debrief":"If home feels too full, a teacher, didi or Childline can help.","relearn":"If home is overloaded, a teacher or Childline 1098 can help.","persona":"any","source":"help-routing"},
  {"id":"mm-930","cat":"ask-for-help","type":"branch","hook":"A friend says they sometimes wish they weren't around.","options":[{"text":"Stay with them and tell a trusted adult right now","consequence":"Your friend is kept safe and supported.","outcome":"caring","best":true},{"text":"Hope it passes and say nothing","consequence":"Dark thoughts are a 'tell an adult now' moment, for safety."}],"debrief":"Words like that mean tell a trusted adult and Childline 1098 / 112 now.","relearn":"For dark thoughts, tell a trusted adult and Childline 1098 / 112.","persona":"any","source":"safeguarding / helpline"},
  {"id":"mm-931","cat":"ask-for-help","type":"branch","hook":"You feel panicky before a result and your heart is racing.","options":[{"text":"Breathe, then tell a calm adult you need support right now","consequence":"They steady you and you feel less alone.","outcome":"calmer","best":true},{"text":"Hide in a corner and ride it out totally alone","consequence":"In a panic, a calm adult nearby helps you settle."}],"debrief":"In a hard moment, breathing plus telling a calm adult both help.","relearn":"In a panic, breathe and tell a calm adult you need help.","persona":"any","source":"help-seeking"},
  {"id":"mm-932","cat":"ask-for-help","type":"branch","hook":"You're embarrassed your worry is 'just' friendship drama.","options":[{"text":"Tell a trusted adult anyway; small-seeming worries count","consequence":"They listen and it feels lighter.","outcome":"heard","best":true},{"text":"Decide it's too small to mention","consequence":"No worry is too small; if it hurts you, it's worth sharing."}],"debrief":"If a worry weighs on you, it's big enough to ask about.","relearn":"No worry is 'too small' to bring to a trusted adult.","persona":"Diya","source":"help-seeking"},
  {"id":"mm-933","cat":"ask-for-help","type":"branch","hook":"You don't want anyone at school to see you visit the counsellor.","options":[{"text":"Ask the counsellor for a private time or way to meet","consequence":"You get help and keep your privacy.","outcome":"resourceful","best":true},{"text":"Skip the help entirely to avoid being seen","consequence":"You can ask for a private slot; you don't have to skip help."}],"debrief":"You can protect your privacy and still get the help you need.","relearn":"You can ask for a private way to get help if you're shy.","persona":"any","source":"help-seeking"},
  {"id":"mm-934","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Strong people handle their feelings completely alone.\"","myth":{"un":"Strong people handle everything alone.","re":"Real strength includes knowing when to ask for help.","why":"Everyone needs support sometimes."},"relearn":"Real strength includes asking for help when you need it.","persona":"Aarav","source":"de-stigmatise"},
  {"id":"mm-935","cat":"ask-for-help","type":"strike-rewrite","hook":"\"If I ask for help, I'll just be a burden to everyone.\"","myth":{"un":"Asking for help makes me a burden.","re":"People who care want to help; you're not a burden.","why":"Supporting each other is what people do."},"relearn":"You're not a burden for asking someone who cares to help.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-936","cat":"ask-for-help","type":"strike-rewrite","hook":"\"I should be able to fix all my problems by myself.\"","myth":{"un":"I should fix every problem by myself.","re":"Some problems need another person, and that's normal.","why":"Even adults ask others for help."},"relearn":"Some problems need help; asking is normal, not weak.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-937","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Helplines won't understand someone like me.\"","myth":{"un":"A helpline won't understand someone like me.","re":"Childline 1098 listens to all kinds of kids, with no judging.","why":"They're trained to help every child."},"relearn":"Childline 1098 listens to every child without judging.","persona":"any","source":"helpline"},
  {"id":"mm-938","cat":"ask-for-help","type":"strike-rewrite","hook":"\"If I tell someone, they'll just tell the whole world.\"","myth":{"un":"If I tell someone, everyone will find out.","re":"A trusted adult keeps your worry private and safe.","why":"Trusted helpers protect your privacy."},"relearn":"A trusted adult keeps what you share private.","persona":"any","source":"help-seeking"},
  {"id":"mm-939","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Boys who ask for help get laughed at.\"","myth":{"un":"Boys who ask for help get laughed at.","re":"Asking for help takes courage, for any boy or girl.","why":"Courage isn't about gender."},"relearn":"Asking for help is brave for boys and girls alike.","persona":"Aarav","source":"de-stigmatise"},
  {"id":"mm-940","cat":"ask-for-help","type":"strike-rewrite","hook":"\"I have to wait until things get really bad to ask.\"","myth":{"un":"I should wait until it's really bad to ask.","re":"You can ask early; you don't have to wait for a crisis.","why":"Asking early often makes things easier."},"relearn":"You can ask for help early, before things get bad.","persona":"any","source":"help-seeking"},
  {"id":"mm-941","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Asking for help means I'll be seen as a baby.\"","myth":{"un":"Asking for help means I'm being a baby.","re":"Knowing when to reach out is a grown-up, capable skill.","why":"Even capable adults reach out."},"relearn":"Reaching out is a mature, capable skill, not childish.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-942","cat":"ask-for-help","type":"strike-rewrite","hook":"\"My problems are too small to take up a helper's time.\"","myth":{"un":"My problems are too small to mention.","re":"If it weighs on you, it's worth sharing with someone.","why":"Helpers want to hear what's bothering you."},"relearn":"If a worry weighs on you, it's worth sharing.","persona":"any","source":"help-seeking"},
  {"id":"mm-943","cat":"ask-for-help","type":"strike-rewrite","hook":"\"If the first adult didn't help, no one will.\"","myth":{"un":"If one adult doesn't help, no one will.","re":"If one person misses it, another can still hear you.","why":"There's always more than one person to ask."},"relearn":"If one adult misses it, try another; don't give up.","persona":"any","source":"help-seeking / persistence"},
  {"id":"mm-944","cat":"ask-for-help","type":"strike-rewrite","hook":"\"Telling a teacher about my feelings will get me in trouble.\"","myth":{"un":"Telling a teacher my feelings will get me in trouble.","re":"A caring teacher wants to help, not to punish you.","why":"Sharing feelings isn't doing anything wrong."},"relearn":"Telling a caring teacher your feelings won't get you in trouble.","persona":"any","source":"help-seeking"},
  {"id":"mm-945","cat":"ask-for-help","type":"match","hook":"Match each worry to a good person or route to ask.","pairs":[{"left":"Trouble keeping up in class","right":"Your subject teacher"},{"left":"Feeling low for many days","right":"A school counsellor"},{"left":"A fight at home","right":"A trusted family adult"},{"left":"A late-night dark thought","right":"Childline 1098 / 112"},{"left":"Confused about your changing body","right":"An ASHA or NGO didi"}],"relearn":"Different worries have a right person or route to turn to.","persona":"Asha","source":"help-routing / UNESCO 5.5"},
  {"id":"mm-946","cat":"ask-for-help","type":"match","hook":"Match each scared thought to the kinder truth.","pairs":[{"left":"\"I'll be a burden\"","right":"People who care want to help"},{"left":"\"It's too small\"","right":"If it hurts, it's worth sharing"},{"left":"\"They'll laugh\"","right":"Asking takes real courage"},{"left":"\"No one understands\"","right":"Helpers are trained to listen"},{"left":"\"I should cope alone\"","right":"Everyone needs support sometimes"}],"relearn":"The fears that stop us asking are usually untrue.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-947","cat":"ask-for-help","type":"match","hook":"Match the brave first line to who you'd say it to.","pairs":[{"left":"\"Can we talk after class?\"","right":"Your teacher"},{"left":"\"Maa, I need some help.\"","right":"A parent"},{"left":"\"I'm not okay, can you listen?\"","right":"A trusted friend"},{"left":"\"Can I just talk to someone?\"","right":"Childline 1098"},{"left":"\"Didi, can you help me?\"","right":"An ASHA didi"}],"relearn":"There's a simple brave line for every trusted helper.","persona":"Asha","source":"help-seeking"},
  {"id":"mm-948","cat":"ask-for-help","type":"match","hook":"Match each step of asking for help to what it means.","pairs":[{"left":"Notice","right":"I'm not okay right now"},{"left":"Choose","right":"Pick a person I trust"},{"left":"Say","right":"\"Can we talk?\""},{"left":"Share","right":"Tell them what's wrong"},{"left":"Again","right":"Ask another if unheard"}],"relearn":"Asking has clear steps: notice, choose, say, share, ask again.","persona":"any","source":"help-seeking"},
  {"id":"mm-949","cat":"ask-for-help","type":"match","hook":"Match what a good listener does to why it helps.","pairs":[{"left":"Listens fully","right":"You feel heard"},{"left":"Keeps it private","right":"You feel safe"},{"left":"Takes you seriously","right":"You feel believed"},{"left":"Helps find next steps","right":"You're not alone with it"},{"left":"Checks back later","right":"You know they care"}],"relearn":"A good helper listens, keeps it private and follows up.","persona":"any","source":"help-seeking"},
  {"id":"mm-950","cat":"ask-for-help","type":"match","hook":"Match the helping moment to the better response.","pairs":[{"left":"Friend says they're sad","right":"\"I'm here, tell me\""},{"left":"Friend hints at dark thoughts","right":"Tell a trusted adult now"},{"left":"Friend feels left out","right":"\"That really hurts\""},{"left":"Friend is too scared to ask","right":"Go with them to ask"},{"left":"Friend says 'tell no one'","right":"Get help together anyway"}],"relearn":"Helping a friend ask for help is a kind, strong thing to do.","persona":"any","source":"peer support"},
  {"id":"mm-951","cat":"ask-for-help","type":"match","hook":"Match each excuse for staying quiet to the gentle truth.","pairs":[{"left":"\"I'll sort it tomorrow\"","right":"Today is a fine day to ask"},{"left":"\"They're too busy\"","right":"Caring people make time"},{"left":"\"I'll feel silly\"","right":"Feeling silly soon passes"},{"left":"\"What if it's nothing?\"","right":"Then you've lost nothing"},{"left":"\"I should be tougher\"","right":"Asking is the tough move"}],"relearn":"The excuses for staying quiet rarely hold up.","persona":"any","source":"help-seeking"},
  {"id":"mm-952","cat":"ask-for-help","type":"match","hook":"Match each trusted helper to what they're best for.","pairs":[{"left":"Parent","right":"Worries at home"},{"left":"Teacher","right":"Trouble at school"},{"left":"Counsellor","right":"Lasting low feelings"},{"left":"ASHA didi","right":"Health and body worries"},{"left":"Childline 1098","right":"When you need it any time"}],"relearn":"Each trusted helper is good for different kinds of worries.","persona":"Asha","source":"help-routing"},
  {"id":"mm-953","cat":"ask-for-help","type":"sort","hook":"Sort each into 'Ask for help now' or 'Handle, then share later'.","items":[{"id":"a","text":"A friend hints at dark thoughts"},{"id":"b","text":"Heavy feelings lasting for weeks"},{"id":"c","text":"A small worry that passed by evening"},{"id":"d","text":"You feel unsafe right now"},{"id":"e","text":"One bad mark you're disappointed about"},{"id":"f","text":"A bad mood that lifted after a walk"}],"bins":[{"id":"now","label":"Ask for help now","valence":"tell"},{"id":"later","label":"Handle, share later","valence":"neutral"}],"key":{"a":"now","b":"now","c":"later","d":"now","e":"later","f":"later"},"relearn":"Big, lasting or unsafe feelings mean ask for help now.","persona":"any","source":"help-seeking / safety"},
  {"id":"mm-954","cat":"ask-for-help","type":"sort","hook":"Sort each into 'A trusted helper' or 'Not a safe source of help'.","items":[{"id":"a","text":"Your class teacher"},{"id":"b","text":"A stranger who DMs you online"},{"id":"c","text":"The school counsellor"},{"id":"d","text":"Childline 1098"},{"id":"e","text":"An ASHA or NGO didi"},{"id":"f","text":"Someone who tells you to keep dark secrets"}],"bins":[{"id":"safe","label":"Trusted helper","valence":"pos"},{"id":"unsafe","label":"Not safe","valence":"neg"}],"key":{"a":"safe","b":"unsafe","c":"safe","d":"safe","e":"safe","f":"unsafe"},"relearn":"Trusted helpers listen and keep you safe; secret-keepers don't.","persona":"any","source":"help-routing / safety"},
  {"id":"mm-955","cat":"ask-for-help","type":"sort","hook":"Sort each line into 'Brave ask' or 'Staying stuck'.","items":[{"id":"a","text":"\"Can we talk? I'm not okay.\""},{"id":"b","text":"\"Nothing's wrong\" (when it is)"},{"id":"c","text":"\"I need some help with this.\""},{"id":"d","text":"Bottling it up alone"},{"id":"e","text":"\"Will you listen for a minute?\""},{"id":"f","text":"\"I'll just deal with it myself.\""}],"bins":[{"id":"brave","label":"Brave ask","valence":"tell"},{"id":"stuck","label":"Staying stuck","valence":"uhoh"}],"key":{"a":"brave","b":"stuck","c":"brave","d":"stuck","e":"brave","f":"stuck"},"relearn":"A brave ask names it out loud; staying stuck keeps it hidden.","persona":"any","source":"help-seeking"},
  {"id":"mm-956","cat":"ask-for-help","type":"sort","hook":"Sort each belief into 'True about asking' or 'A myth'.","items":[{"id":"a","text":"Asking for help is brave"},{"id":"b","text":"Asking means you're weak"},{"id":"c","text":"Helpers keep your worry private"},{"id":"d","text":"You'll always be a burden"},{"id":"e","text":"You can ask early, before a crisis"},{"id":"f","text":"Only 'crazy' people use helplines"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Asking is brave, private and for everyone; the rest are myths.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-957","cat":"ask-for-help","type":"sort","hook":"Sort each into 'A good first step' or 'Not a real step yet'.","items":[{"id":"a","text":"Picking one person you trust"},{"id":"b","text":"Waiting silently for it to vanish"},{"id":"c","text":"Writing down what's wrong first"},{"id":"d","text":"Pretending you're totally fine"},{"id":"e","text":"Saying \"can we talk?\""},{"id":"f","text":"Telling yourself it's too small"}],"bins":[{"id":"step","label":"A good step","valence":"pos"},{"id":"none","label":"Not a step","valence":"uhoh"}],"key":{"a":"step","b":"none","c":"step","d":"none","e":"step","f":"none"},"relearn":"Real first steps move you toward asking, not away from it.","persona":"any","source":"help-seeking"},
  {"id":"mm-958","cat":"ask-for-help","type":"sort","hook":"Sort each into 'Helps a friend ask' or 'Holds a friend back'.","items":[{"id":"a","text":"\"I'm here, you can tell me\""},{"id":"b","text":"\"Just get over it\""},{"id":"c","text":"Offering to go with them"},{"id":"d","text":"\"Don't tell anyone, ever\""},{"id":"e","text":"Telling an adult about dark thoughts"},{"id":"f","text":"Laughing off their worry"}],"bins":[{"id":"helps","label":"Helps them ask","valence":"pos"},{"id":"holds","label":"Holds them back","valence":"neg"}],"key":{"a":"helps","b":"holds","c":"helps","d":"holds","e":"helps","f":"holds"},"relearn":"Validating and routing to an adult helps; dismissing holds them back.","persona":"any","source":"peer support"},
  {"id":"mm-959","cat":"ask-for-help","type":"sort","hook":"Sort each into 'When to ask now' or 'Can wait a bit'.","items":[{"id":"a","text":"You can't stop crying for days"},{"id":"b","text":"Nervous before one test"},{"id":"c","text":"You feel unsafe with someone"},{"id":"d","text":"A small argument with a friend"},{"id":"e","text":"Dark thoughts won't leave"},{"id":"f","text":"One bad day that ended okay"}],"bins":[{"id":"now","label":"Ask now","valence":"tell"},{"id":"wait","label":"Can wait","valence":"neutral"}],"key":{"a":"now","b":"wait","c":"now","d":"wait","e":"now","f":"wait"},"relearn":"Lasting, unsafe or dark feelings mean ask now, not later.","persona":"any","source":"help-seeking / safety"},
  {"id":"mm-960","cat":"ask-for-help","type":"sort","hook":"Sort each into 'A real reason to ask' or 'A fake reason to stay quiet'.","items":[{"id":"a","text":"\"This feeling won't lift\""},{"id":"b","text":"\"They'll think I'm weak\""},{"id":"c","text":"\"I can't handle it alone\""},{"id":"d","text":"\"It's too small to mention\""},{"id":"e","text":"\"I keep losing sleep over it\""},{"id":"f","text":"\"Strong people cope alone\""}],"bins":[{"id":"real","label":"Reason to ask","valence":"pos"},{"id":"fake","label":"Fake excuse","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Lasting hurt is a real reason to ask; 'I'll look weak' is an excuse.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-961","cat":"ask-for-help","type":"reflect","hook":"Picture telling someone you trust 'I'm not okay'.","prompt":"Who comes to mind first as your person to tell?","options":["A parent or family adult","A teacher or counsellor","A friend or didi"],"affirm":"Whoever you pictured, that's a real person you can reach for.","relearn":"You already have a trusted person you can tell 'I'm not okay'.","persona":"any","source":"help-seeking"},
  {"id":"mm-962","cat":"ask-for-help","type":"reflect","hook":"Asking for help can feel scary the first time.","prompt":"What makes asking feel hardest for you?","options":["Worrying I'll be judged","Not knowing the words","Feeling like a bother"],"affirm":"Naming what's hard is the first brave step toward asking anyway.","relearn":"Knowing what makes asking hard helps you ask anyway.","persona":"any","source":"help-seeking"},
  {"id":"mm-963","cat":"ask-for-help","type":"reflect","hook":"There are many ways to start a conversation about feelings.","prompt":"How would you most likely start?","options":["Saying it out loud","Writing a short note","Asking 'can we talk?'"],"affirm":"Any of these is a real, brave way to begin.","relearn":"There are many brave ways to start asking for help.","persona":"any","source":"help-seeking"},
  {"id":"mm-964","cat":"ask-for-help","type":"reflect","hook":"Imagine a friend just told you they're struggling.","prompt":"What would you want to do for them?","options":["Listen without judging","Sit with them a while","Help them tell an adult"],"affirm":"Each one shows you'd be a caring friend to lean on.","relearn":"Being there and helping a friend reach an adult is real care.","persona":"any","source":"peer support"},
  {"id":"mm-965","cat":"ask-for-help","type":"reflect","hook":"Think about a time you felt better after talking.","prompt":"What helped most about sharing it?","options":["Feeling less alone","The worry felt lighter","Someone helped me act"],"affirm":"That's why reaching out is worth it, again and again.","relearn":"Sharing a worry makes it lighter and you less alone.","persona":"any","source":"help-seeking"},
  {"id":"mm-966","cat":"ask-for-help","type":"reflect","hook":"Everyone has a different first place they'd turn.","prompt":"Where would you feel safest asking for help?","options":["At home","At school","On a helpline call"],"affirm":"Wherever feels safest to you is a good place to start.","relearn":"You can start asking wherever feels safest to you.","persona":"any","source":"help-routing"},
  {"id":"mm-967","cat":"ask-for-help","type":"reflect","hook":"Bravery looks different for everyone.","prompt":"Which would take the most courage for you?","options":["Saying it to a parent","Telling a teacher","Calling Childline 1098"],"affirm":"Whichever you chose, doing it would be genuinely brave.","relearn":"Asking for help any way you can is genuinely brave.","persona":"any","source":"help-seeking"},
  {"id":"mm-968","cat":"ask-for-help","type":"reflect","hook":"Sometimes one ask isn't enough, and that's okay.","prompt":"If you weren't heard the first time, what might you do?","options":["Try the same person again","Tell a different adult","Call Childline 1098"],"affirm":"Any of these keeps you reaching out, which is exactly right.","relearn":"If one ask isn't heard, keep reaching out; that's right.","persona":"any","source":"help-seeking / persistence"},
  {"id":"mm-969","cat":"ask-for-help","type":"build","hook":"Build your plan for asking a trusted adult for help.","prompt":"Put the steps in order to ask for help well.","pieces":["Notice I'm not okay","Pick a person I trust","Find a quiet moment","Say 'can we talk?'","Tell them what's wrong","Ask again if unheard"],"mode":"sequence","key":["Notice I'm not okay","Pick a person I trust","Find a quiet moment","Say 'can we talk?'","Tell them what's wrong","Ask again if unheard"],"relearn":"Asking goes: notice, pick a person, find a moment, speak, share, retry.","persona":"any","source":"help-seeking"},
  {"id":"mm-970","cat":"ask-for-help","type":"build","hook":"Build your list of trusted helpers to keep ready.","prompt":"Pick the people and routes that belong on a 'who I can tell' list.","pieces":["A trusted parent","A class teacher","The school counsellor","An ASHA or NGO didi","Childline 1098","A stranger online"],"mode":"assemble","key":["A trusted parent","A class teacher","The school counsellor","An ASHA or NGO didi","Childline 1098"],"relearn":"Your helper list is trusted adults and Childline 1098, not strangers.","persona":"Asha","source":"help-routing"},
  {"id":"mm-971","cat":"ask-for-help","type":"build","hook":"Build a kind reply for a friend who's struggling.","prompt":"Pick the lines that help a friend feel safe to open up.","pieces":["\"Thank you for telling me\"","\"I'm here for you\"","\"Let's tell an adult who can help\"","\"Just get over it\"","\"You're not alone\"","\"Don't make it a big deal\""],"mode":"assemble","key":["\"Thank you for telling me\"","\"I'm here for you\"","\"Let's tell an adult who can help\"","\"You're not alone\""],"relearn":"Helping a friend means thanks, presence and routing to an adult.","persona":"any","source":"peer support"},
  {"id":"mm-972","cat":"ask-for-help","type":"build","hook":"Build the steps to call Childline when you feel low.","prompt":"Put the steps in order for calling for support.","pieces":["Find a quiet, private spot","Take a slow breath","Dial Childline 1098","Say how you're feeling","Listen to what they suggest","Tell a trusted adult too"],"mode":"sequence","key":["Find a quiet, private spot","Take a slow breath","Dial Childline 1098","Say how you're feeling","Listen to what they suggest","Tell a trusted adult too"],"relearn":"You can call Childline 1098, share how you feel, then tell an adult.","persona":"any","source":"helpline"},
  {"id":"mm-973","cat":"ask-for-help","type":"build","hook":"Build what to say when you don't have all the words.","prompt":"Pick honest openers you could use to start asking.","pieces":["\"I'm not okay\"","\"I can't explain it yet\"","\"Can we talk?\"","\"I need some help\"","\"Nothing's wrong, forget it\"","\"It's hard to say, but...\""],"mode":"assemble","key":["\"I'm not okay\"","\"I can't explain it yet\"","\"Can we talk?\"","\"I need some help\"","\"It's hard to say, but...\""],"relearn":"You don't need perfect words; honest openers are enough to start.","persona":"any","source":"help-seeking"},
  {"id":"mm-974","cat":"ask-for-help","type":"build","hook":"Build the order to help a friend who hints at dark thoughts.","prompt":"Put the caring steps in the safest order.","pieces":["Stay calm and with them","Take it seriously","Tell a trusted adult now","Call Childline 1098 / 112","Keep being there for them"],"mode":"sequence","key":["Stay calm and with them","Take it seriously","Tell a trusted adult now","Call Childline 1098 / 112","Keep being there for them"],"relearn":"For a friend's dark thoughts: stay, take it seriously, tell an adult.","persona":"Asha","source":"safeguarding / helpline"},
  {"id":"mm-975","cat":"ask-for-help","type":"build","hook":"Build your set of brave reasons to keep, for when asking feels hard.","prompt":"Pick the true reasons that make asking worth it.","pieces":["Asking is brave","I won't be alone with it","The worry gets lighter","Helpers keep it private","Asking makes me weak","I'll be a burden"],"mode":"assemble","key":["Asking is brave","I won't be alone with it","The worry gets lighter","Helpers keep it private"],"relearn":"Asking is brave, shared, lighter and private, never weak.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-976","cat":"ask-for-help","type":"build","hook":"Build a 'what to do tonight' plan when a feeling is too heavy.","prompt":"Put the steps in order for a hard night.","pieces":["Notice it's too heavy alone","Breathe slowly a few times","Message or tell one trusted person","If it's urgent, call Childline 1098 / 112","Stay with someone, not alone"],"mode":"sequence","key":["Notice it's too heavy alone","Breathe slowly a few times","Message or tell one trusted person","If it's urgent, call Childline 1098 / 112","Stay with someone, not alone"],"relearn":"On a heavy night: breathe, tell someone, call Childline 1098 if urgent.","persona":"any","source":"help-seeking / helpline"},
  {"id":"mm-990","cat":"be-kind-to-mind","type":"branch","hook":"You drop a catch in the cricket match and your mind starts piling on insults.","options":[{"text":"Say what you'd tell a teammate: \"one drop, shake it off\"","consequence":"The sting fades and you focus on the next ball.","outcome":"self-kind","best":true},{"text":"Call yourself useless for the rest of the game","consequence":"Back yourself the way you'd back a teammate.","outcome":"harsh"}],"debrief":"One mistake isn't a verdict on you, back yourself like a teammate.","relearn":"Talk to yourself like a teammate, not a critic, after a slip.","persona":"any","source":"self-compassion / sport"},
  {"id":"mm-991","cat":"be-kind-to-mind","type":"branch","hook":"Your cousin scored higher and your aunt keeps comparing you at dinner.","options":[{"text":"Tell yourself: \"my path is mine, one mark isn't me\"","consequence":"You let the comparison pass instead of soaking it in.","outcome":"self-kind","best":true},{"text":"Decide you're just the dull one of the family","consequence":"A dinner-table comparison isn't the truth about you.","outcome":"harsh"}],"debrief":"Comparison rarely tells the true story; be gentle with yourself.","relearn":"Don't let comparison decide your worth; your path is your own.","persona":"Diya","source":"comparison / self-worth"},
  {"id":"mm-992","cat":"be-kind-to-mind","type":"branch","hook":"You've been studying for hours and your brain has gone foggy and slow.","options":[{"text":"Take a short break: walk, water, then return","consequence":"You come back clearer and remember more.","outcome":"self-kind","best":true},{"text":"Force yourself on, calling yourself lazy for tiring","consequence":"A foggy brain needs a break, not an insult.","outcome":"harsh"}],"debrief":"Resting a tired mind is smart, not lazy: breaks help you learn.","relearn":"A short break for a tired mind helps you, not weakens you.","persona":"any","source":"rest / self-care"},
  {"id":"mm-993","cat":"be-kind-to-mind","type":"branch","hook":"Aarav messed up in front of the class and his mind keeps replaying it on loop.","options":[{"text":"Notice the replay and gently say \"enough, it's over now\"","consequence":"The loop loosens and he can move on.","outcome":"self-kind","best":true},{"text":"Replay it all night as proof he's an idiot","consequence":"You can notice a thought-loop without obeying it.","outcome":"harsh"}],"debrief":"You can catch a harsh replay and gently let it go. It isn't truth.","relearn":"Notice a harsh thought-loop and let it pass; it isn't a fact.","persona":"Aarav","source":"cognitive defusion"},
  {"id":"mm-994","cat":"be-kind-to-mind","type":"branch","hook":"You wake up in a low, heavy mood for no clear reason at all.","options":[{"text":"Treat yourself gently today, like a friend who's down","consequence":"The kindness helps the low mood ease through the day.","outcome":"self-kind","best":true},{"text":"Get angry at yourself for being 'moody'","consequence":"A low day deserves gentleness, not a telling-off.","outcome":"harsh"}],"debrief":"Low days happen to everyone; be gentle and let the mood pass.","relearn":"On a low day, be gentle with yourself. It will pass.","persona":"any","source":"emotional honesty"},
  {"id":"mm-995","cat":"be-kind-to-mind","type":"branch","hook":"You finally finished a hard worksheet and your mind jumps straight to the next thing.","options":[{"text":"Pause and let yourself feel proud of finishing","consequence":"The small win lands and refuels you.","outcome":"self-kind","best":true},{"text":"Skip it: only the next task counts","consequence":"Letting a win land is fuel, not a waste of time.","outcome":"harsh"}],"debrief":"Noticing your small wins is kind to your mind and keeps you going.","relearn":"Let yourself feel proud of small wins; it refuels your mind.","persona":"any","source":"self-care / wins"},
  {"id":"mm-996","cat":"be-kind-to-mind","type":"branch","hook":"A friend laughs at you for crying at a sad film and you feel embarrassed.","options":[{"text":"Tell yourself \"feeling things isn't weak, it's human\"","consequence":"You let the feeling be okay instead of hiding it.","outcome":"self-kind","best":true},{"text":"Decide you must never show feelings again","consequence":"Having feelings is human, not something to hide.","outcome":"harsh"}],"debrief":"Crying at something sad is human; feelings aren't weakness.","relearn":"Showing feelings isn't weak. It's part of being human.","persona":"Aarav","source":"de-stigmatise / toxic-toughness"},
  {"id":"mm-997","cat":"be-kind-to-mind","type":"branch","hook":"You sent a wobbly drawing to your art group and now you're cringing at it.","options":[{"text":"Remind yourself you're learning, not failing","consequence":"You keep drawing instead of quitting in shame.","outcome":"self-kind","best":true},{"text":"Delete it and decide you're hopeless at art","consequence":"Learning means wobbly tries; that isn't hopeless.","outcome":"harsh"}],"debrief":"Being a beginner means wobbly tries. That's growing, not failing.","relearn":"Wobbly first tries are part of learning, not proof you're bad.","persona":"any","source":"growth / self-compassion"},
  {"id":"mm-998","cat":"be-kind-to-mind","type":"branch","hook":"You're lying awake at 1am as your mind lists everything you got wrong today.","options":[{"text":"Tell the list \"not now\" and try a slow breath","consequence":"The mind settles enough for sleep to come.","outcome":"self-kind","best":true},{"text":"Lie there rehearsing every mistake till morning","consequence":"You can gently park the worry-list till daylight.","outcome":"harsh"}],"debrief":"You can gently park a night-time worry-list and breathe slow.","relearn":"Park a midnight worry-list gently and try a slow breath.","persona":"any","source":"self-talk / rest"},
  {"id":"mm-999","cat":"be-kind-to-mind","type":"branch","hook":"Diya feels guilty asking the counsellor didi for time when others 'have it worse'.","options":[{"text":"Remind herself her feelings count too, not less","consequence":"She lets herself accept the support she needs.","outcome":"self-kind","best":true},{"text":"Stay quiet because others 'deserve it more'","consequence":"Your feelings count too, not less than anyone's.","outcome":"harsh"}],"debrief":"You don't have to 'earn' care: your feelings matter as much as anyone's.","relearn":"Your feelings count as much as anyone's; you can accept care.","persona":"Diya","source":"self-worth / help-seeking"},
  {"id":"mm-1000","cat":"be-kind-to-mind","type":"branch","hook":"You snapped at your little brother and now you feel like a terrible person.","options":[{"text":"Own it kindly: apologise, then forgive yourself","consequence":"You repair it and don't carry shame all day.","outcome":"self-kind","best":true},{"text":"Brand yourself a bad person and stew in it","consequence":"You can make it right without branding yourself bad.","outcome":"harsh"}],"debrief":"A bad moment doesn't make you bad, repair it and be kind to you.","relearn":"You can fix a mistake without deciding you're a bad person.","persona":"any","source":"repair / self-compassion"},
  {"id":"mm-1001","cat":"be-kind-to-mind","type":"branch","hook":"You keep scrolling photos of classmates' 'perfect' trips and feel worse and worse.","options":[{"text":"Put the phone down; feeds show highlights, not lives","consequence":"The comparison loosens and your mood lifts.","outcome":"self-kind","best":true},{"text":"Keep scrolling and decide your life is boring","consequence":"Feeds show highlights, not anyone's real life.","outcome":"harsh"}],"debrief":"A highlight feed isn't real life; comparing there is unkind to you.","relearn":"Feeds show highlights, not real life. Don't compare yourself.","persona":"any","source":"comparison / online"},
  {"id":"mm-1002","cat":"be-kind-to-mind","type":"branch","hook":"You hear your inner voice say \"you should be perfect\" before the spelling bee.","options":[{"text":"Swap it for \"I'll do my best, that's enough\"","consequence":"The pressure eases and you can think clearly.","outcome":"self-kind","best":true},{"text":"Demand perfection and freeze up","consequence":"\"My best is enough\" beats an impossible perfect.","outcome":"harsh"}],"debrief":"Aiming for 'my best' instead of 'perfect' is kinder and works better.","relearn":"Swap 'be perfect' for 'do my best'. It's kinder and steadier.","persona":"any","source":"perfectionism"},
  {"id":"mm-1003","cat":"be-kind-to-mind","type":"branch","hook":"Rohit notices his son shrinking when he calls himself 'stupid' out loud.","options":[{"text":"Say warmly \"that's not how we talk about you here\"","consequence":"His son hears that he's worth kindness.","outcome":"ally","best":true},{"text":"Agree, to 'toughen him up'","consequence":"Kind words from an adult help a child be kind to themselves.","outcome":"harsh"}],"debrief":"A caring adult who models kindness teaches a child to be kind to themselves.","relearn":"A kind adult helps a child learn to talk to themselves kindly.","persona":"Rohit","source":"adult-modelling"},
  {"id":"mm-1004","cat":"be-kind-to-mind","type":"branch","hook":"You said no to a sleepover because you were drained, and now you feel guilty.","options":[{"text":"Accept that resting your mind was a fair choice","consequence":"You recover and the guilt fades.","outcome":"self-kind","best":true},{"text":"Beat yourself up for 'letting friends down'","consequence":"Looking after a drained mind is a fair, kind choice.","outcome":"harsh"}],"debrief":"Saying no to rest your mind is allowed. That isn't letting anyone down.","relearn":"Resting when drained is a fair choice, not letting people down.","persona":"any","source":"boundaries / rest"},
  {"id":"mm-1005","cat":"be-kind-to-mind","type":"branch","hook":"You forgot your lines in the school play and want to quit drama forever.","options":[{"text":"Be kind: \"nerves happen, I can try again\"","consequence":"You stay in and improve next time.","outcome":"self-kind","best":true},{"text":"Quit and tell yourself you're an embarrassment","consequence":"A nervous slip isn't a reason to quit on yourself.","outcome":"harsh"}],"debrief":"A stumble on stage is nerves, not failure. Be kind and try again.","relearn":"Be kind after a slip; nerves happen and you can try again.","persona":"any","source":"resilience / self-compassion"},
  {"id":"mm-1006","cat":"be-kind-to-mind","type":"branch","hook":"You catch a dark thought: \"nobody would miss me.\"","options":[{"text":"Treat it as a sign to tell a trusted adult today","consequence":"Sharing it lifts the weight; you're not alone.","outcome":"reach-out","best":true},{"text":"Keep the dark thought private and push it down","consequence":"A dark thought is exactly when to tell an adult.","outcome":"alone"}],"debrief":"Dark thoughts are a signal to reach out: tell a trusted adult or Childline 1098.","relearn":"For dark thoughts, tell a trusted adult or call Childline 1098 / 112.","persona":"any","source":"safety / help-seeking"},
  {"id":"mm-1007","cat":"be-kind-to-mind","type":"branch","hook":"Your team lost the quiz and you're the only one still calling yourself the reason.","options":[{"text":"Share the result kindly: \"we win and lose together\"","consequence":"You drop the lone blame and feel lighter.","outcome":"self-kind","best":true},{"text":"Carry the whole loss as your personal fault","consequence":"A team result isn't one person's fault to carry alone.","outcome":"harsh"}],"debrief":"A shared result isn't yours alone to blame yourself for.","relearn":"Don't carry a team's loss as your own personal fault.","persona":"any","source":"self-blame"},
  {"id":"mm-1008","cat":"be-kind-to-mind","type":"branch","hook":"You skipped breakfast and slept badly; now everything feels harder.","options":[{"text":"Be gentle: tired and hungry makes everything heavier","consequence":"You eat, rest a bit, and the day feels lighter.","outcome":"self-kind","best":true},{"text":"Assume you're just weak and push on grumpily","consequence":"Tired and hungry isn't weak, sort the basics first.","outcome":"harsh"}],"debrief":"When tired or hungry, be gentle: the basics change everything.","relearn":"Tired and hungry makes things harder; care for the basics first.","persona":"any","source":"body-mind link"},
  {"id":"mm-1009","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"If I'm gentle with myself I'll just become lazy.\"","myth":{"un":"Being gentle with myself will make me lazy.","re":"Self-kindness gives you the steadiness to keep trying.","why":"Encouragement keeps you going; cruelty wears you down."},"relearn":"Self-kindness fuels effort; it doesn't make you lazy.","persona":"any","source":"self-compassion"},
  {"id":"mm-1010","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Real boys don't get sad or stressed.\"","myth":{"un":"Boys aren't supposed to feel sad or stressed.","re":"Everyone feels sad and stressed. It's human, not unmanly.","why":"Feelings are part of every person, whatever their gender."},"relearn":"All people feel sad and stressed; it isn't weakness or 'unmanly'.","persona":"Aarav","source":"de-stigmatise / toxic-toughness"},
  {"id":"mm-1011","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Taking a rest day means I'm falling behind.\"","myth":{"un":"Resting means I'm falling behind everyone else.","re":"Rest restores your mind so you do better, not worse.","why":"A rested mind learns and copes more than a drained one."},"relearn":"Rest restores your mind; it isn't falling behind.","persona":"any","source":"rest / self-care"},
  {"id":"mm-1012","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"I should be able to handle everything on my own.\"","myth":{"un":"I should be able to handle everything alone.","re":"Leaning on others is normal and human, not a failing.","why":"Nobody copes with everything alone; sharing lightens it."},"relearn":"You don't have to handle everything alone; leaning on others is human.","persona":"any","source":"help-seeking / de-stigmatise"},
  {"id":"mm-1013","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Making a mistake means there's something wrong with me.\"","myth":{"un":"A mistake means something is wrong with me.","re":"Mistakes are how everyone learns; they don't define you.","why":"Every person who learns anything makes mistakes."},"relearn":"Mistakes are how you learn. They don't mean you're flawed.","persona":"any","source":"growth / self-compassion"},
  {"id":"mm-1014","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"If I'm not the best, I'm a failure.\"","myth":{"un":"If I'm not the best, then I've failed.","re":"Your effort and growth matter far more than a ranking.","why":"There's only one top rank; growth is open to everyone."},"relearn":"Not being the best isn't failing; growth and effort matter most.","persona":"Diya","source":"perfectionism / comparison"},
  {"id":"mm-1015","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Being kind to myself is just making excuses.\"","myth":{"un":"Being kind to myself is just excusing myself.","re":"Self-kindness owns the slip and still tries again.","why":"You can be honest about a mistake and gentle at once."},"relearn":"Self-kindness isn't an excuse; it owns the slip and tries again.","persona":"any","source":"self-compassion"},
  {"id":"mm-1016","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Everyone else has it together; only I struggle.\"","myth":{"un":"Everyone else copes fine; only I struggle.","re":"Most people hide their struggles behind a calm face.","why":"You only see others' outsides, not their hard days."},"relearn":"Others hide their struggles too; you aren't the only one.","persona":"any","source":"normalising / comparison"},
  {"id":"mm-1017","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"If I forgive myself, I'll just do it again.\"","myth":{"un":"Forgiving myself means I'll repeat the mistake.","re":"Forgiving yourself frees you to learn and do better.","why":"Shame keeps you stuck; kindness lets you move forward."},"relearn":"Forgiving yourself helps you learn, not repeat the mistake.","persona":"any","source":"self-forgiveness"},
  {"id":"mm-1018","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"Asking the counsellor for help means I'm a problem child.\"","myth":{"un":"Seeing a counsellor means I'm a 'problem child'.","re":"Talking to a counsellor is a smart, ordinary thing to do.","why":"A counsellor is for anyone, like a coach for your mind."},"relearn":"Seeing a counsellor is normal and smart, not a sign you're 'a problem'.","persona":"any","source":"de-stigmatise / help-seeking"},
  {"id":"mm-1019","cat":"be-kind-to-mind","type":"strike-rewrite","hook":"\"I have to push through pain to prove I'm strong.\"","myth":{"un":"Pushing through pain is what proves I'm strong.","re":"Noticing your limits and resting is real strength.","why":"Looking after yourself takes more courage than ignoring it."},"relearn":"Real strength is honouring your limits, not pushing through pain.","persona":"Aarav","source":"toxic-toughness / self-care"},
  {"id":"mm-1020","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: if a good friend had your exact hard day, what would you tell them?","prompt":"Say it to yourself instead.","options":["\"You did your best\"","\"This is hard, and that's okay\"","\"I'm proud of you for trying\""],"affirm":"You deserve those words as much as any friend does.","relearn":"Offer yourself the kindness you'd give a good friend.","persona":"any","source":"self-compassion"},
  {"id":"mm-1021","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what's one thing your mind does well that you rarely thank it for?","prompt":"Pick one.","options":["Remembering people I love","Solving puzzles","Imagining stories","Keeping me curious"],"affirm":"Your mind does a lot for you: noticing it is a kind move.","relearn":"Noticing what your mind does well is a kind, steadying habit.","persona":"any","source":"self-appreciation"},
  {"id":"mm-1022","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: where do you feel safest letting your guard down and just being you?","prompt":"Picture it.","options":["My room","With one close friend","Outdoors","At my grandparents'"],"affirm":"Knowing your safe place is a tool. Return there when it's heavy.","relearn":"A safe place where you can be yourself is a real comfort tool.","persona":"any","source":"self-care / safe-base"},
  {"id":"mm-1023","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what's a small kindness you could do for tomorrow-you tonight?","prompt":"Pick one.","options":["Pack my bag early","Sleep on time","Lay out my clothes","Charge my torch"],"affirm":"Being kind to future-you is being kind to your mind.","relearn":"Small kindnesses to future-you ease tomorrow's mind.","persona":"any","source":"self-care"},
  {"id":"mm-1024","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: when you're low, whose voice in your head is gentle with you?","prompt":"Think of one.","options":["A grandparent","A teacher","A close friend","My own kinder voice"],"affirm":"You can borrow that gentle voice any time you need it.","relearn":"A gentle voice you trust can be borrowed when you're low.","persona":"any","source":"self-compassion"},
  {"id":"mm-1025","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: name a 'flaw' you have that's actually okay, even kind of nice.","prompt":"Pick or think of one.","options":["I'm sensitive","I ask lots of questions","I'm a daydreamer","I'm slow but careful"],"affirm":"Seeing your 'flaws' kindly is being a friend to yourself.","relearn":"Many 'flaws' are strengths seen kindly; befriend them.","persona":"any","source":"self-acceptance"},
  {"id":"mm-1026","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what helps you feel like yourself again after a rough patch?","prompt":"Think of one.","options":["Old music","A long walk","Drawing","Talking it out"],"affirm":"That's a tool worth keeping close for the next hard day.","relearn":"Knowing what restores you is a tool to reuse on hard days.","persona":"any","source":"self-care"},
  {"id":"mm-1027","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what's one thing you'd like to stop saying harshly to yourself?","prompt":"Name it quietly.","options":["\"I'm so stupid\"","\"I always fail\"","\"I'm not enough\"","\"It's all my fault\""],"affirm":"Naming a harsh phrase is the first step to softening it.","relearn":"Naming a harsh self-phrase is the first step to softening it.","persona":"any","source":"self-talk"},
  {"id":"mm-1028","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what would 'being your own friend' look like this week?","prompt":"Pick one.","options":["Forgive a mistake","Rest without guilt","Ask for help","Celebrate a small win"],"affirm":"Any of these is real kindness to your own mind.","relearn":"Being your own friend means forgiving, resting, asking, celebrating.","persona":"any","source":"self-compassion"},
  {"id":"mm-1029","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: when did you last let yourself feel proud without brushing it off?","prompt":"Recall one moment.","options":["A test I prepped for","Helping someone","Finishing something hard","Being honest"],"affirm":"Letting pride land is kind. Your mind needs the good bits too.","relearn":"Letting yourself feel proud, without brushing it off, is kind.","persona":"any","source":"self-appreciation"},
  {"id":"mm-1030","cat":"be-kind-to-mind","type":"reflect","hook":"Lensy: what's one gentle reminder you'd like waiting for you on a bad day?","prompt":"Choose your note.","options":["\"This will pass\"","\"You've coped before\"","\"It's okay to rest\"","\"Ask for help\""],"affirm":"Keep that note close: your kinder voice for the hard days.","relearn":"A gentle note-to-self is a ready comfort on a bad day.","persona":"any","source":"self-compassion"},
  {"id":"mm-1031","cat":"be-kind-to-mind","type":"role-play","hook":"A friend keeps calling herself an idiot after one wrong answer in class.","setup":"Be kind back to her. Say:","yourLine":[{"text":"\"Hey, one slip doesn't make you an idiot. You'd never say that to me.\"","best":true},{"text":"\"Yeah, that was a pretty silly answer.\""}],"relearn":"Help a friend swap harsh self-talk for the kindness they'd give you.","persona":"any","source":"peer / self-compassion"},
  {"id":"mm-1032","cat":"be-kind-to-mind","type":"role-play","hook":"Aarav's mate jokes that needing a break makes you 'soft'.","setup":"Push back kindly. Say:","yourLine":[{"text":"\"Taking a break isn't soft. It's how you don't burn out.\"","best":true},{"text":"\"Yeah, breaks are for the weak ones.\""}],"relearn":"Stand up for rest; needing a break isn't being 'soft'.","persona":"Aarav","source":"de-stigmatise / rest"},
  {"id":"mm-1033","cat":"be-kind-to-mind","type":"role-play","hook":"A classmate whispers that she feels like she's 'not good enough' lately.","setup":"Answer warmly. Say:","yourLine":[{"text":"\"You are enough. A hard week doesn't change that.\"","best":true},{"text":"\"Maybe just try harder then.\""}],"relearn":"Remind a friend they're enough, even in a hard week.","persona":"any","source":"self-worth / peer"},
  {"id":"mm-1034","cat":"be-kind-to-mind","type":"role-play","hook":"Your sibling is furious at himself for losing the chess match.","setup":"Help him be gentler. Say:","yourLine":[{"text":"\"You played well, losing one game doesn't undo that.\"","best":true},{"text":"\"You should've seen that move coming.\""}],"relearn":"Help someone separate one loss from their whole self.","persona":"any","source":"resilience / peer"},
  {"id":"mm-1035","cat":"be-kind-to-mind","type":"role-play","hook":"A friend says he feels guilty for resting when his parents are working hard.","setup":"Reassure him. Say:","yourLine":[{"text":"\"Resting so you can keep going isn't letting them down.\"","best":true},{"text":"\"Yeah, you probably should be doing more.\""}],"relearn":"Reassure a friend that resting isn't letting family down.","persona":"any","source":"rest / guilt"},
  {"id":"mm-1036","cat":"be-kind-to-mind","type":"role-play","hook":"Diya overhears a girl saying her counselling sessions make her 'crazy'.","setup":"Step in kindly. Say:","yourLine":[{"text":"\"Talking to someone is smart and normal. It doesn't make you anything but brave.\"","best":true},{"text":"\"Maybe keep that quiet so no one finds out.\""}],"relearn":"De-stigmatise help-seeking out loud; it's brave, not 'crazy'.","persona":"Diya","source":"de-stigmatise"},
  {"id":"mm-1037","cat":"be-kind-to-mind","type":"role-play","hook":"Asha hears a kid say sorry over and over for one small mistake.","setup":"Coach them gently. Say:","yourLine":[{"text":"\"One sorry is enough, now be as kind to yourself as I am to you.\"","best":true},{"text":"\"Yes, you really should keep apologising.\""}],"relearn":"One apology is enough; then turn that kindness inward.","persona":"Asha","source":"self-forgiveness / near-peer"},
  {"id":"mm-1038","cat":"be-kind-to-mind","type":"sort","hook":"Sort each self-talk line: kind to your mind, or harsh on it?","items":[{"id":"a","text":"\"I'll try again tomorrow\""},{"id":"b","text":"\"I'm hopeless at everything\""},{"id":"c","text":"\"It's okay to feel sad today\""},{"id":"d","text":"\"Everyone hates me\""},{"id":"e","text":"\"I did one thing well\""},{"id":"f","text":"\"I should be perfect\""}],"bins":[{"id":"kind","label":"Kind self-talk","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Spot harsh self-talk and swap it for the kind version.","persona":"any","source":"self-talk"},
  {"id":"mm-1039","cat":"be-kind-to-mind","type":"sort","hook":"Sort: real mind-care, or unkind to your mind?","items":[{"id":"a","text":"Sleeping enough"},{"id":"b","text":"Skipping every meal to study"},{"id":"c","text":"Talking when it's heavy"},{"id":"d","text":"Bottling it all up"},{"id":"e","text":"Forgiving a mistake"},{"id":"f","text":"Punishing yourself for a slip"}],"bins":[{"id":"care","label":"Mind-care","valence":"pos"},{"id":"unkind","label":"Unkind to your mind","valence":"neg"}],"key":{"a":"care","b":"unkind","c":"care","d":"unkind","e":"care","f":"unkind"},"relearn":"Sleep, talking and forgiving are mind-care; bottling and punishing aren't.","persona":"any","source":"self-care"},
  {"id":"mm-1040","cat":"be-kind-to-mind","type":"sort","hook":"Sort: speak up to support, or stays quiet and stigmatises?","items":[{"id":"a","text":"\"Asking for help is smart\""},{"id":"b","text":"\"Don't tell anyone you cried\""},{"id":"c","text":"\"Counsellors are for everyone\""},{"id":"d","text":"\"Hide that you're struggling\""},{"id":"e","text":"\"Feelings are normal\""},{"id":"f","text":"\"Toughen up, no feelings\""}],"bins":[{"id":"support","label":"Speaks up to support","valence":"tell"},{"id":"stigma","label":"Quiet / stigmatising","valence":"neg"}],"key":{"a":"support","b":"stigma","c":"support","d":"stigma","e":"support","f":"stigma"},"relearn":"Speaking up that help is normal beats hiding and stigma.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-1041","cat":"be-kind-to-mind","type":"sort","hook":"Sort: gentle on a hard day, or piling on?","items":[{"id":"a","text":"Letting yourself rest"},{"id":"b","text":"Calling yourself lazy"},{"id":"c","text":"Doing one small thing"},{"id":"d","text":"Listing every failure"},{"id":"e","text":"Asking a friend to talk"},{"id":"f","text":"Skipping food and sleep"}],"bins":[{"id":"gentle","label":"Gentle with yourself","valence":"pos"},{"id":"pile","label":"Piling on yourself","valence":"neg"}],"key":{"a":"gentle","b":"pile","c":"gentle","d":"pile","e":"gentle","f":"pile"},"relearn":"On a hard day, rest and small steps beat piling on yourself.","persona":"any","source":"self-compassion"},
  {"id":"mm-1042","cat":"be-kind-to-mind","type":"sort","hook":"Sort each thought: a fact about you, or just a harsh thought to rewrite?","items":[{"id":"a","text":"\"I made a mistake\""},{"id":"b","text":"\"I'm worthless\""},{"id":"c","text":"\"I felt nervous\""},{"id":"d","text":"\"Everyone's better than me\""},{"id":"e","text":"\"I found this hard\""},{"id":"f","text":"\"I ruin everything\""}],"bins":[{"id":"fact","label":"A fair fact","valence":"neutral"},{"id":"harsh","label":"Harsh thought to rewrite","valence":"uhoh"}],"key":{"a":"fact","b":"harsh","c":"fact","d":"harsh","e":"fact","f":"harsh"},"relearn":"Tell a fair fact apart from a harsh thought you can rewrite kindly.","persona":"any","source":"cognitive defusion"},
  {"id":"mm-1043","cat":"be-kind-to-mind","type":"sort","hook":"Sort: a healthy way to be kind to your mind, or a harmful 'trick' that isn't?","items":[{"id":"a","text":"A short walk outside"},{"id":"b","text":"Bottling it all up"},{"id":"c","text":"Slow breathing"},{"id":"d","text":"Cutting off all friends"},{"id":"e","text":"Talking to someone you trust"},{"id":"f","text":"Numbing it and hiding away"}],"bins":[{"id":"healthy","label":"Healthy mind-care","valence":"pos"},{"id":"harmful","label":"Not a real tool","valence":"neg"}],"key":{"a":"healthy","b":"harmful","c":"healthy","d":"harmful","e":"healthy","f":"harmful"},"relearn":"Walking, breathing and talking help; numbing and isolating never do.","persona":"any","source":"healthy-coping"},
  {"id":"mm-1044","cat":"be-kind-to-mind","type":"sort","hook":"Sort: kind to a struggling friend, or unkind?","items":[{"id":"a","text":"\"I'm here, take your time\""},{"id":"b","text":"\"Just get over it\""},{"id":"c","text":"\"That sounds really hard\""},{"id":"d","text":"\"You're being dramatic\""},{"id":"e","text":"\"Want to talk about it?\""},{"id":"f","text":"\"Others have it worse\""}],"bins":[{"id":"kind","label":"Kind support","valence":"pos"},{"id":"unkind","label":"Dismissive","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Being present and validating helps; dismissing a friend's hurt doesn't.","persona":"any","source":"peer-support"},
  {"id":"mm-1045","cat":"be-kind-to-mind","type":"build","hook":"Build a kind-words shield to answer your harsh inner critic.","prompt":"Pick the kind comebacks for your shield.","pieces":["I'm doing my best","One mistake isn't all of me","I'm allowed to rest","I'd forgive a friend for this","I'm learning, not failing"],"mode":"assemble","key":["I'm doing my best","One mistake isn't all of me","I'm allowed to rest","I'd forgive a friend for this","I'm learning, not failing"],"relearn":"A shield of kind comebacks answers the harsh inner critic.","persona":"any","source":"self-talk / consolidation"},
  {"id":"mm-1046","cat":"be-kind-to-mind","type":"build","hook":"Build a 'be your own friend' checklist for a bad day.","prompt":"Pick the kind moves.","pieces":["Forgive the slip","Rest without guilt","Say one kind thing to myself","Ask for help if it's heavy","Do one small nice thing"],"mode":"assemble","key":["Forgive the slip","Rest without guilt","Say one kind thing to myself","Ask for help if it's heavy","Do one small nice thing"],"relearn":"Forgive, rest, speak kindly, ask, and do one nice thing on a bad day.","persona":"any","source":"self-compassion / consolidation"},
  {"id":"mm-1047","cat":"be-kind-to-mind","type":"build","hook":"Put the steps of rewriting a harsh thought in order.","prompt":"Order the rewrite steps.","pieces":["Catch the harsh thought","Name it as a thought, not a fact","Ask what I'd tell a friend","Say the kinder version","Let the harsh one go"],"mode":"sequence","key":["Catch the harsh thought","Name it as a thought, not a fact","Ask what I'd tell a friend","Say the kinder version","Let the harsh one go"],"relearn":"Catch it, name it, befriend it, rewrite it kindly, let it go.","persona":"any","source":"cognitive defusion"},
  {"id":"mm-1048","cat":"be-kind-to-mind","type":"build","hook":"Build a self-kindness pledge to keep for yourself.","prompt":"Pick the promises you'll keep.","pieces":["I'll talk to myself kindly","I'll let myself feel all feelings","I'll rest when I need to","I won't measure my worth in marks","I'll ask for help when it's heavy"],"mode":"assemble","key":["I'll talk to myself kindly","I'll let myself feel all feelings","I'll rest when I need to","I won't measure my worth in marks","I'll ask for help when it's heavy"],"relearn":"Your self-kindness pledge: speak kindly, feel, rest, value yourself, ask.","persona":"any","source":"consolidation"},
  {"id":"mm-1049","cat":"be-kind-to-mind","type":"build","hook":"Order how to repair after you snapped at someone and feel bad.","prompt":"Put the repair steps in order.","pieces":["Notice the guilt without piling on","Say a genuine sorry","Make one small thing right","Forgive yourself","Move on kindly"],"mode":"sequence","key":["Notice the guilt without piling on","Say a genuine sorry","Make one small thing right","Forgive yourself","Move on kindly"],"relearn":"Notice, apologise, repair, forgive yourself, and move on kindly.","persona":"any","source":"repair / self-forgiveness"},
  {"id":"mm-1050","cat":"be-kind-to-mind","type":"build","hook":"Build a comfort-kit of kind things to reach for when you're low.","prompt":"Pick what goes in your kit.","pieces":["A song that lifts me","A walk outside","One person I can text","A kind note to myself","Something I enjoy making"],"mode":"assemble","key":["A song that lifts me","A walk outside","One person I can text","A kind note to myself","Something I enjoy making"],"relearn":"A comfort-kit of kind, healthy things helps you ride out a low.","persona":"any","source":"self-care / consolidation"},
  {"id":"mm-1051","cat":"be-kind-to-mind","type":"build","hook":"Order how to be a kind friend to someone who's hard on themselves.","prompt":"Put the kind steps in order.","pieces":["Listen without judging","Tell them the hurt is okay","Remind them of one good thing","Offer to stay with it","Suggest a trusted adult if it's heavy"],"mode":"sequence","key":["Listen without judging","Tell them the hurt is okay","Remind them of one good thing","Offer to stay with it","Suggest a trusted adult if it's heavy"],"relearn":"Listen, validate, remind, stay, and route on to help if it's heavy.","persona":"any","source":"peer-support"},
  {"id":"mm-1052","cat":"be-kind-to-mind","type":"match","hook":"Match each harsh thought to the kinder rewrite.","pairs":[{"left":"\"I'm so stupid\"","right":"\"I made a mistake, I can learn\""},{"left":"\"I always fail\"","right":"\"This one was hard for me\""},{"left":"\"I'm not enough\"","right":"\"I am enough as I am\""},{"left":"\"I should be perfect\"","right":"\"My best is plenty\""},{"left":"\"Nobody likes me\"","right":"\"Some people do care for me\""}],"relearn":"Every harsh line has a kinder, truer rewrite.","persona":"any","source":"self-talk"},
  {"id":"mm-1053","cat":"be-kind-to-mind","type":"match","hook":"Match each hard moment to a kind thing to do for yourself.","pairs":[{"left":"Drained and tired","right":"Let yourself rest"},{"left":"Made a mistake","right":"Forgive and learn"},{"left":"Feeling low","right":"Do one thing you enjoy"},{"left":"Heavy and stuck","right":"Talk to someone you trust"},{"left":"Harsh thought looping","right":"Rewrite it kindly"}],"relearn":"Match each hard moment to a kind, healthy response.","persona":"any","source":"self-care"},
  {"id":"mm-1054","cat":"be-kind-to-mind","type":"match","hook":"Match the unkind self-myth to the kinder truth.","pairs":[{"left":"Rest is lazy","right":"Rest restores your mind"},{"left":"Feelings are weak","right":"Feelings are human"},{"left":"Marks are my worth","right":"Marks measure one test"},{"left":"Asking help is shameful","right":"Asking help is brave"},{"left":"I must be perfect","right":"My best is enough"}],"relearn":"Each unkind myth about yourself has a kinder, truer answer.","persona":"any","source":"de-stigmatise"},
  {"id":"mm-1055","cat":"be-kind-to-mind","type":"match","hook":"Match what a friend says to the kind reply that helps.","pairs":[{"left":"\"I feel useless\"","right":"\"You're not. A hard day says so, not you\""},{"left":"\"I'll never improve\"","right":"\"You're learning, give it time\""},{"left":"\"I'm such a burden\"","right":"\"I'm glad you told me\""},{"left":"\"I can't cope\"","right":"\"Let's find one small step\""},{"left":"\"It's all my fault\"","right":"\"You don't have to carry it alone\""}],"relearn":"Kind, validating replies help a struggling friend more than fixes.","persona":"any","source":"peer-support"},
  {"id":"mm-1056","cat":"be-kind-to-mind","type":"match","hook":"Match each kind self-care move to why it helps your mind.","pairs":[{"left":"Enough sleep","right":"A rested mind copes better"},{"left":"Naming a feeling","right":"Eases its grip on you"},{"left":"A short walk","right":"Lifts a low mood"},{"left":"Talking it out","right":"Shares the weight"},{"left":"A kind word to self","right":"Softens the harsh voice"}],"relearn":"Each kind move has a real reason it helps your mind.","persona":"any","source":"self-care"},
  {"id":"mm-1057","cat":"be-kind-to-mind","type":"match","hook":"Match the harsh inner-critic line to a gentle comeback.","pairs":[{"left":"\"You ruined it\"","right":"\"One part went wrong, not all of it\""},{"left":"\"You're too sensitive\"","right":"\"Feeling deeply is a strength\""},{"left":"\"You're behind everyone\"","right":"\"My path runs at its own pace\""},{"left":"\"You can't ask for help\"","right":"\"Asking is brave and allowed\""},{"left":"\"You're a failure\"","right":"\"I'm someone who keeps trying\""}],"relearn":"Have a gentle comeback ready for each harsh inner-critic line.","persona":"any","source":"self-talk"},
  {"id":"mm-1058","cat":"be-kind-to-mind","type":"match","hook":"Match each feeling to a kind, true thing to remember.","pairs":[{"left":"Embarrassed","right":"Everyone has off moments"},{"left":"Left out","right":"This hurts and it will pass"},{"left":"Overwhelmed","right":"I can take one small step"},{"left":"Disappointed","right":"One 'no' isn't my whole story"},{"left":"Exhausted","right":"Resting is allowed"}],"relearn":"Each hard feeling pairs with a kind, true reminder.","persona":"any","source":"emotional honesty"},
  {"id":"mm-1059","cat":"be-kind-to-mind","type":"match","hook":"Match who you can turn to when you can't be kind to yourself alone.","pairs":[{"left":"A heavy, lasting low","right":"A trusted adult or Childline 1098"},{"left":"Exam panic","right":"A teacher or counsellor"},{"left":"A friendship hurt","right":"A close friend"},{"left":"A worry you can't tell parents","right":"An ASHA / NGO didi"},{"left":"Just need a hug","right":"A parent or grandparent"}],"relearn":"Different worries have different helpers; a trusted adult or 1098 always.","persona":"Asha","source":"help-routing"},
  {"id":"mm-1080","cat":"handling-rejection","type":"branch","hook":"Your painting didn't make the school exhibition wall.","persona":"any","source":"rejection / creative setback","relearn":"One 'not chosen' isn't a verdict on your talent; keep making.","options":[{"text":"Feel the sting, then ask the teacher what to build on next","consequence":"You learn and keep painting with more skill.","outcome":"growth","best":true},{"text":"Tear up your drawings and never paint again","consequence":"Quitting buries a talent; one wall isn't the whole story."}],"debrief":"Not being picked once doesn't mean your work has no worth."},
  {"id":"mm-1081","cat":"handling-rejection","type":"branch","hook":"You asked to join the cricket game in the gully and they said 'next time'.","persona":"any","source":"rejection / being left out","relearn":"A 'next time' isn't a 'never'; the hurt eases and you can try again.","options":[{"text":"Feel a bit left out, then practise and ask again tomorrow","consequence":"They make space for you the next day.","outcome":"resilient","best":true},{"text":"Decide they all hate you and avoid the gully forever","consequence":"One 'next time' isn't proof anyone hates you."}],"debrief":"Being told 'not now' once isn't the same as being unwanted."},
  {"id":"mm-1082","cat":"handling-rejection","type":"branch","hook":"Diya scored less than her cousin and relatives keep comparing them.","persona":"Diya","source":"rejection / comparison","relearn":"Their comparison measures a number, not your worth or your path.","options":[{"text":"Let the comment sting, then remind herself her path is her own","consequence":"The comparison loses its grip on her.","outcome":"grounded","best":true},{"text":"Believe she's the family failure and stop trying","consequence":"One comparison isn't the truth about who you are."}],"debrief":"A relative's comparison is one opinion, not a verdict on you."},
  {"id":"mm-1083","cat":"handling-rejection","type":"branch","hook":"You messaged a classmate to be friends and got left on 'seen'.","persona":"any","source":"rejection / connection","relearn":"One unanswered message isn't proof you're unlikeable; stay open.","options":[{"text":"Feel the awkwardness, then keep being friendly to others too","consequence":"A different friendship grows instead.","outcome":"open","best":true},{"text":"Decide you're bad at friendship and stop reaching out","consequence":"One 'seen' isn't the whole story; keep your circle open."}],"debrief":"A single quiet reply isn't proof that nobody wants you."},
  {"id":"mm-1084","cat":"handling-rejection","type":"branch","hook":"You lost the class-monitor election by two votes.","persona":"any","source":"rejection / losing","relearn":"Losing one vote-count doesn't decide your future; try again.","options":[{"text":"Feel disappointed, congratulate the winner, plan for next term","consequence":"You bounce back with dignity and another shot.","outcome":"resilient","best":true},{"text":"Sulk and refuse to talk to anyone who didn't vote for you","consequence":"Sulking burns bridges; a loss isn't the end of the road."}],"debrief":"One election result isn't a measure of your whole worth."},
  {"id":"mm-1085","cat":"handling-rejection","type":"branch","hook":"Aarav got dropped from his online squad's group chat.","persona":"Aarav","source":"rejection / online","relearn":"Being cut from one chat isn't proof you don't matter; feel it, move on.","options":[{"text":"Admit it stings, then game with other friends who include him","consequence":"He finds a squad that actually wants him.","outcome":"resilient","best":true},{"text":"Pretend he doesn't care while quietly feeling crushed","consequence":"Bottling it up hurts more; the hurt is allowed and it passes."}],"debrief":"It's okay to feel hurt by being left out, even online."},
  {"id":"mm-1086","cat":"handling-rejection","type":"branch","hook":"You didn't get the solo in the dance for the school function.","persona":"any","source":"rejection / disappointment","relearn":"Not getting one part doesn't mean you aren't good; the hurt passes.","options":[{"text":"Feel let down, then give the group part your full energy","consequence":"You shine anyway and enjoy the show.","outcome":"resilient","best":true},{"text":"Skip the function and tell everyone dance is stupid","consequence":"Quitting in anger costs you the fun; the hurt fades if you let it."}],"debrief":"Missing one solo isn't proof you have no talent."},
  {"id":"mm-1087","cat":"handling-rejection","type":"branch","hook":"Your science-fair project came last and classmates laughed.","persona":"any","source":"rejection / public failure","relearn":"One last place isn't a label; what you learned still counts.","options":[{"text":"Feel embarrassed, then notice what you learned building it","consequence":"You keep your curiosity and improve next time.","outcome":"growth","best":true},{"text":"Decide you're stupid at science and quit it","consequence":"A last place is information, not proof you're stupid."}],"debrief":"Coming last once is a step in learning, not a verdict."},
  {"id":"mm-1088","cat":"handling-rejection","type":"branch","hook":"A best friend started sitting with someone else at lunch.","persona":"Diya","source":"rejection / friendship shift","relearn":"A friendship changing shape isn't a rejection of all of you.","options":[{"text":"Feel the loss, then talk to them and also sit with others","consequence":"You learn what's going on and keep your warmth.","outcome":"grounded","best":true},{"text":"Assume they hate you and go silent","consequence":"Assuming the worst can break a friendship that wasn't broken."}],"debrief":"One changed seat isn't proof a friend has rejected you."},
  {"id":"mm-1089","cat":"handling-rejection","type":"branch","hook":"You worked up courage to share an idea and the teacher said it was wrong.","persona":"any","source":"rejection / being corrected","relearn":"Being wrong once isn't shameful; speaking up is still brave.","options":[{"text":"Feel the flush of embarrassment, then keep raising your hand","consequence":"You stay brave and learn faster than the quiet kids.","outcome":"resilient","best":true},{"text":"Vow to never speak in class again","consequence":"One wrong answer isn't a reason to silence yourself."}],"debrief":"Getting one answer wrong doesn't make speaking up a mistake."},
  {"id":"mm-1090","cat":"handling-rejection","type":"branch","hook":"You weren't invited to a classmate's birthday party.","persona":"any","source":"rejection / being left out","relearn":"One missed invite isn't proof you're unliked; the hurt passes.","options":[{"text":"Let it sting, then make plans you'll enjoy that day instead","consequence":"You have a good day and the sting fades.","outcome":"resilient","best":true},{"text":"Decide nobody likes you and shut everyone out","consequence":"Shutting down makes it worse; the hurt is real but passes kindly."}],"debrief":"Not being invited once isn't a measure of your worth."},
  {"id":"mm-1091","cat":"handling-rejection","type":"branch","hook":"You keep replaying a rejection from last week in bed at night.","persona":"any","source":"rejection / rumination","relearn":"You can gently interrupt the replay with one small, kind action.","options":[{"text":"Name the feeling, breathe slowly, and let the thought pass","consequence":"The loop loosens and you drift to sleep.","outcome":"unstuck","best":true},{"text":"Try to force the thought out by getting angry","consequence":"Fighting a thought feeds it; naming and breathing eases it."}],"debrief":"A replaying memory fades faster when you breathe than fight it."},
  {"id":"mm-1092","cat":"handling-rejection","type":"branch","hook":"You didn't make the district team after months of training.","persona":"any","source":"rejection / big setback","relearn":"A big setback that lingers is a reason to lean on a trusted adult.","options":[{"text":"Grieve it, then talk to your coach or a trusted adult","consequence":"You feel less alone and find your next goal.","outcome":"supported","best":true},{"text":"Carry the disappointment alone for weeks","consequence":"A heavy setback is lighter shared; reach out to someone."}],"debrief":"When a setback feels too big, telling a trusted adult is strong."},
  {"id":"mm-1093","cat":"handling-rejection","type":"branch","hook":"Diya was teased about her new spectacles and felt left out.","persona":"Diya","source":"rejection / teasing","relearn":"Teasing says more about the teaser than about you; the hurt passes.","options":[{"text":"Feel hurt, then sit with kinder classmates and tell a teacher","consequence":"The teasing loses power and an adult helps it stop.","outcome":"supported","best":true},{"text":"Stop wearing the specs she needs","consequence":"Hiding to please teasers costs you; it isn't about your worth."}],"debrief":"Being teased isn't proof something's wrong with you."},
  {"id":"mm-1094","cat":"handling-rejection","type":"branch","hook":"Your story for the magazine got returned with 'not selected'.","persona":"any","source":"rejection / creative rejection","relearn":"A 'not selected' is one editor's call, not a verdict on your writing.","options":[{"text":"Feel the dip, then ask for feedback and send it somewhere else","consequence":"You grow as a writer and keep going.","outcome":"growth","best":true},{"text":"Delete everything you've ever written","consequence":"One rejection isn't proof your writing has no worth."}],"debrief":"A single 'no' from one place isn't a 'no' from everywhere."},
  {"id":"mm-1095","cat":"handling-rejection","type":"branch","hook":"You apologised to a friend but they're still not ready to talk.","persona":"any","source":"rejection / repair","relearn":"You can do your part kindly; the hurt of waiting eases with time.","options":[{"text":"Give them space, stay kind, and lean on other friends","consequence":"In time they come around and you stayed steady.","outcome":"patient","best":true},{"text":"Demand they forgive you right now","consequence":"Pushing harder pushes them away; patience works better."}],"debrief":"Someone not being ready yet isn't a final rejection of you."},
  {"id":"mm-1096","cat":"handling-rejection","type":"branch","hook":"Aarav posted a clip and barely anyone liked it; he feels small.","persona":"Aarav","source":"rejection / online comparison","relearn":"Likes count taps, not your worth; the small feeling passes.","options":[{"text":"Notice the dip, remind himself likes aren't worth, do something offline","consequence":"His mood lifts away from the counter.","outcome":"grounded","best":true},{"text":"Refresh the count every minute hoping it climbs","consequence":"Chasing the number deepens the dip; step away and it passes."}],"debrief":"A low like-count measures an app, not your value as a person."},
  {"id":"mm-1097","cat":"handling-rejection","type":"branch","hook":"You stumbled and forgot your lines on stage during the play.","persona":"any","source":"rejection / public embarrassment","relearn":"Everyone freezes sometimes; the cringe fades faster than you fear.","options":[{"text":"Breathe, pick up the next line, and let the slip go after","consequence":"The audience barely remembers; you finish proud.","outcome":"resilient","best":true},{"text":"Run off stage and avoid everyone for a week","consequence":"The moment passes faster than hiding makes it feel."}],"debrief":"One forgotten line feels huge to you and tiny to everyone else."},
  {"id":"mm-1098","cat":"handling-rejection","type":"branch","hook":"You tried to start a club and only one person signed up.","persona":"any","source":"rejection / small turnout","relearn":"A small start isn't a failure; trying again is brave, not foolish.","options":[{"text":"Feel deflated, then run it well with the one and invite more later","consequence":"Word spreads and the club grows.","outcome":"growth","best":true},{"text":"Cancel it and decide your ideas are always rubbish","consequence":"A slow start isn't proof your idea has no worth."}],"debrief":"One quiet sign-up sheet isn't a verdict on your idea."},
  {"id":"mm-1099","cat":"handling-rejection","type":"branch","hook":"Your crush said they just want to be friends and you feel crushed.","persona":"any","source":"rejection / disappointment","relearn":"The hurt is real and okay to feel; it passes, and you're still you.","options":[{"text":"Let yourself feel sad, talk to a friend, and be gentle with yourself","consequence":"The ache softens and you keep your self-respect.","outcome":"resilient","best":true},{"text":"Decide you're unlovable and avoid everyone","consequence":"One person's 'no' isn't proof you're unlovable."}],"debrief":"Hearing one 'no' doesn't decide your whole future or worth."},
  {"id":"mm-1100","cat":"handling-rejection","type":"branch","hook":"You were the only one not picked for the group project teams.","persona":"any","source":"rejection / being left out","relearn":"Being left till last once isn't proof you're unwanted; speak up.","options":[{"text":"Feel the awkwardness, then ask the teacher for a team","consequence":"You get a fair spot and the moment passes.","outcome":"supported","best":true},{"text":"Go home and skip the project","consequence":"Skipping costs your marks; the left-out feeling fades fast."}],"debrief":"Being last picked once isn't the truth about how others see you."},
  {"id":"mm-1101","cat":"handling-rejection","type":"branch","hook":"A grandparent keeps praising your sibling and rarely you.","persona":"any","source":"rejection / family comparison","relearn":"One person's praise pattern isn't the measure of your worth.","options":[{"text":"Feel the pang, then notice the people who do see and value you","consequence":"You feel steadier and less defined by one voice.","outcome":"grounded","best":true},{"text":"Start resenting your sibling and picking fights","consequence":"Resentment hurts you both; their worth and yours aren't a contest."}],"debrief":"Less praise from one person isn't proof you matter less."},
  {"id":"mm-1102","cat":"handling-rejection","type":"branch","hook":"You finally tried out for choir and your voice cracked badly.","persona":"any","source":"rejection / setback","relearn":"One rough try isn't the end; trying again is brave, not a failure.","options":[{"text":"Wince, breathe, and ask if you can sing the line again","consequence":"You get a second go and feel proud you tried.","outcome":"resilient","best":true},{"text":"Decide you can never sing and quit on the spot","consequence":"One cracked note isn't proof you can't sing."}],"debrief":"A shaky first attempt is a start, not a verdict."},
  {"id":"mm-1103","cat":"handling-rejection","type":"strike-rewrite","hook":"\"Being rejected means there's something wrong with me.\"","persona":"Diya","source":"rejection / cognitive","relearn":"Rejection often isn't about your worth at all.","myth":{"un":"If I'm rejected, something must be wrong with me.","re":"Rejection often isn't about your worth at all.","why":"Many 'no's come from timing or fit, not your value."}},
  {"id":"mm-1104","cat":"handling-rejection","type":"strike-rewrite","hook":"\"If a friend leaves me out, it means nobody likes me.\"","persona":"any","source":"rejection / thinking traps","relearn":"Being left out once isn't proof no one likes you.","myth":{"un":"Being left out once means nobody likes me.","re":"One left-out moment doesn't mean nobody likes you.","why":"People have lots of reasons that aren't about you."}},
  {"id":"mm-1105","cat":"handling-rejection","type":"strike-rewrite","hook":"\"I should just squash the hurt and pretend I don't care.\"","persona":"Aarav","source":"rejection / emotional honesty","relearn":"The hurt of rejection is real and okay to feel; you ride it out.","myth":{"un":"I should squash the hurt and pretend I don't care.","re":"The hurt is real and okay to feel; you ride it out.","why":"Letting a feeling pass works better than bottling it up."}},
  {"id":"mm-1106","cat":"handling-rejection","type":"strike-rewrite","hook":"\"Trying again after I failed just means I'm a glutton for failure.\"","persona":"any","source":"rejection / resilience","relearn":"Trying again after a setback is brave, not a sign you failed.","myth":{"un":"Trying again after failing means I'm just asking to fail more.","re":"Trying again after a setback is brave, not foolish.","why":"People grow and improve every time they try again."}},
  {"id":"mm-1107","cat":"handling-rejection","type":"strike-rewrite","hook":"\"One bad result decides what kind of student I'll always be.\"","persona":"any","source":"rejection / labels","relearn":"One failure doesn't define you or your future.","myth":{"un":"One bad result decides the kind of student I'll always be.","re":"One result doesn't define you or your future.","why":"You keep learning and changing all the time."}},
  {"id":"mm-1108","cat":"handling-rejection","type":"strike-rewrite","hook":"\"Comforting a sad friend means telling them to get over it.\"","persona":"Asha","source":"rejection / peer support","relearn":"You comfort a friend by validating the hurt, never dismissing it.","myth":{"un":"The best way to help a sad friend is to tell them to get over it.","re":"You help most by saying the hurt is real and you're there.","why":"Feeling heard helps far more than being brushed off."}},
  {"id":"mm-1109","cat":"handling-rejection","type":"strike-rewrite","hook":"\"If the low feeling after a setback lasts, I should hide it.\"","persona":"any","source":"rejection / help-seeking","relearn":"A setback that feels too big is a reason to tell a trusted adult.","myth":{"un":"If the low feeling after a setback lasts, I should hide it.","re":"A big or lasting low feeling is a reason to tell a trusted adult.","why":"You don't have to carry a heavy setback alone."}},
  {"id":"mm-1110","cat":"handling-rejection","type":"strike-rewrite","hook":"\"Everyone else gets picked easily, so it's just me who fails.\"","persona":"Diya","source":"rejection / comparison","relearn":"Comparison rarely tells the true story; your path is your own.","myth":{"un":"Everyone else gets picked easily; only I get rejected.","re":"Everyone faces 'no's; you just don't see theirs.","why":"People hide their setbacks, so the comparison is unfair."}},
  {"id":"mm-1111","cat":"handling-rejection","type":"strike-rewrite","hook":"\"Feeling sad about being left out means I'm being dramatic.\"","persona":"any","source":"rejection / emotional validation","relearn":"It's natural and okay to feel hurt by being left out.","myth":{"un":"Feeling sad about being left out means I'm being dramatic.","re":"It's natural to feel hurt; the feeling is allowed.","why":"Pretending not to care doesn't make the hurt smaller."}},
  {"id":"mm-1112","cat":"handling-rejection","type":"strike-rewrite","hook":"\"If I get rejected, I should never put myself out there again.\"","persona":"Aarav","source":"rejection / avoidance","relearn":"One 'no' isn't a reason to stop trying; the hurt passes.","myth":{"un":"After a rejection I should never put myself out there again.","re":"One 'no' isn't a reason to stop trying; you can try again.","why":"Most good things come after a few 'no's first."}},
  {"id":"mm-1113","cat":"handling-rejection","type":"role-play","hook":"Your friend just failed an exam and is crying.","persona":"Asha","source":"rejection / peer support","relearn":"Comfort a friend by naming the hurt, not by minimising it.","setup":"Sit with them. Say:","yourLine":[{"text":"\"That's really hard. I'm here, and one exam isn't all of you.\"","best":true},{"text":"\"It's just one test, stop crying.\""}]},
  {"id":"mm-1114","cat":"handling-rejection","type":"role-play","hook":"You didn't get picked and want to speak kindly to yourself.","persona":"any","source":"rejection / self-compassion","relearn":"Talk to yourself as kindly as you'd talk to a good friend.","setup":"Say it to yourself:","yourLine":[{"text":"\"That stung. I did my best, and I can try again.\"","best":true},{"text":"\"I always ruin everything.\""}]},
  {"id":"mm-1115","cat":"handling-rejection","type":"role-play","hook":"A friend was left out of a game and looks deflated.","persona":"any","source":"rejection / inclusion","relearn":"You can include someone hurting and name their feeling out loud.","setup":"Walk over. Say:","yourLine":[{"text":"\"Come sit with us. That looked rubbish, and I get it.\"","best":true},{"text":"\"Maybe they just didn't want you.\""}]},
  {"id":"mm-1116","cat":"handling-rejection","type":"role-play","hook":"Aarav's friend pretends he doesn't care after being dropped from a squad.","persona":"Aarav","source":"rejection / de-stigmatise","relearn":"Letting a friend admit it hurt is kinder than playing it tough.","setup":"Tell him:","yourLine":[{"text":"\"You can say it stung, that's not weak. I'd feel it too.\"","best":true},{"text":"\"Don't be soft, just forget it.\""}]},
  {"id":"mm-1117","cat":"handling-rejection","type":"role-play","hook":"Your sister keeps comparing your marks to your cousin's.","persona":"any","source":"rejection / boundaries","relearn":"You can name that comparison hurts and ask for it gently to stop.","setup":"Say to her:","yourLine":[{"text":"\"Comparing me to her makes it harder. Please can we stop?\"","best":true},{"text":"\"Whatever, I'm just the dumb one.\""}]},
  {"id":"mm-1118","cat":"handling-rejection","type":"role-play","hook":"You want to ask a trusted adult for help after a setback you can't shake.","persona":"Rohit","source":"rejection / help-seeking","relearn":"Naming it plainly to a trusted adult is a brave, strong move.","setup":"Tell a parent or teacher:","yourLine":[{"text":"\"This setback is really getting to me. Can we talk?\"","best":true},{"text":"\"Nothing's wrong, I'm fine.\""}]},
  {"id":"mm-1119","cat":"handling-rejection","type":"role-play","hook":"A friend says everyone hates them after one fight.","persona":"any","source":"rejection / reframing","relearn":"Gently widen a friend's 'everyone' back to one real moment.","setup":"Reassure them. Say:","yourLine":[{"text":"\"One fight isn't everyone. I'm still here, and it'll pass.\"","best":true},{"text":"\"Yeah, maybe everyone does.\""}]},
  {"id":"mm-1120","cat":"handling-rejection","type":"reflect","hook":"Lensy: think of a setback you got past before. What helped you most?","persona":"any","source":"rejection / resilience","relearn":"Remembering what helped before reminds you that you can cope again.","prompt":"What comes to mind?","options":["A friend listened","I took a break","I tried again"],"affirm":"You've found ways through before, and those ways are still yours to use."},
  {"id":"mm-1121","cat":"handling-rejection","type":"reflect","hook":"Lensy: when a 'no' stings, what kind thing could you say to yourself?","persona":"any","source":"rejection / self-compassion","relearn":"A kind word to yourself softens a sting better than a harsh one.","prompt":"What feels true?","options":["\"I'll be okay\"","\"This will pass\"","\"I can try again\""],"affirm":"Any of those is a kind thing to tell yourself, and it's allowed."},
  {"id":"mm-1122","cat":"handling-rejection","type":"reflect","hook":"Lensy: who is one person you could lean on after a disappointment?","persona":"any","source":"rejection / support","relearn":"Naming a person to lean on makes the next hard day a little easier.","prompt":"Who comes to mind?","options":["A friend","A parent","A teacher"],"affirm":"Having even one person in mind to lean on is a real strength."},
  {"id":"mm-1123","cat":"handling-rejection","type":"reflect","hook":"Lensy: rejection hurts and then it passes, like weather. Believe that?","persona":"any","source":"rejection / normalising","relearn":"Hurt rises, peaks and passes; no rejection feeling lasts forever.","prompt":"What do you think?","options":["I think so","It's passed before","I'll let it pass"],"affirm":"Feelings move like weather, and even the heavy ones do pass."},
  {"id":"mm-1124","cat":"handling-rejection","type":"reflect","hook":"Lensy: a 'no' often isn't about you at all. Can you hold that?","persona":"Diya","source":"rejection / reframing","relearn":"Many 'no's are about timing or fit, not your worth.","prompt":"What feels right?","options":["Maybe it's not me","Worth a try","I'll remember that"],"affirm":"Holding 'maybe it isn't about me' gives the hurt much less power."},
  {"id":"mm-1125","cat":"handling-rejection","type":"reflect","hook":"Lensy: one setback doesn't decide your future. How does that land?","persona":"any","source":"rejection / hope","relearn":"One setback is a moment, not a map of your whole future.","prompt":"What do you think?","options":["It's just one moment","There's still time","I can grow"],"affirm":"One moment is small against everything still ahead of you."},
  {"id":"mm-1126","cat":"handling-rejection","type":"sort","hook":"Sort: bounces you back, or keeps you stuck?","persona":"any","source":"rejection / coping","relearn":"Feeling it, being kind and trying again bounce you back; blame and hiding keep you stuck.","items":[{"id":"a","text":"Talk to a friend about it"},{"id":"b","text":"Tell yourself you're worthless"},{"id":"c","text":"Try again or try something else"},{"id":"d","text":"Hide from everyone for days"},{"id":"e","text":"Be kind to yourself first"},{"id":"f","text":"Replay it on repeat all night"}],"bins":[{"id":"bounce","label":"Bounces you back","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"bounce","b":"stuck","c":"bounce","d":"stuck","e":"bounce","f":"stuck"}},
  {"id":"mm-1127","cat":"handling-rejection","type":"sort","hook":"Sort: comforts a rejected friend, or makes it worse?","persona":"any","source":"rejection / peer support","relearn":"Validate the hurt and stay near to comfort; dismissing or mocking makes it worse.","items":[{"id":"a","text":"\"That really hurts, I'm here\""},{"id":"b","text":"\"Just get over it\""},{"id":"c","text":"\"Want to sit with us?\""},{"id":"d","text":"\"You're being dramatic\""},{"id":"e","text":"\"It's okay to feel sad\""},{"id":"f","text":"Laugh at them for caring"}],"bins":[{"id":"comfort","label":"Comforts","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"comfort","b":"worse","c":"comfort","d":"worse","e":"comfort","f":"worse"}},
  {"id":"mm-1128","cat":"handling-rejection","type":"sort","hook":"Sort: true about rejection, or a myth?","persona":"any","source":"rejection / cognitive","relearn":"Rejection is normal, passes and isn't about your worth; the opposites are myths.","items":[{"id":"a","text":"It happens to everyone"},{"id":"b","text":"It means I'm not good enough"},{"id":"c","text":"The hurt passes"},{"id":"d","text":"One 'no' defines my future"},{"id":"e","text":"It's okay to feel hurt"},{"id":"f","text":"I should never feel sad about it"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"}},
  {"id":"mm-1129","cat":"handling-rejection","type":"sort","hook":"Sort: a healthy bounce-back move, or a not-a-real-coping 'trick'?","persona":"any","source":"rejection / coping toolkit","relearn":"Talking, kindness and a break are healthy moves; bottling up and lashing out are not.","items":[{"id":"a","text":"Name how you feel"},{"id":"b","text":"Bottle it all up"},{"id":"c","text":"Take a short break, then return"},{"id":"d","text":"Snap at people around you"},{"id":"e","text":"Lean on a trusted adult"},{"id":"f","text":"Tell yourself off harshly"}],"bins":[{"id":"healthy","label":"Healthy move","valence":"pos"},{"id":"not","label":"Not a real tool","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"}},
  {"id":"mm-1130","cat":"handling-rejection","type":"sort","hook":"Sort: kind self-talk after a 'no', or harsh self-talk?","persona":"any","source":"rejection / self-talk","relearn":"Kind self-talk helps you recover; harsh self-talk keeps the hurt loud.","items":[{"id":"a","text":"\"That's disappointing, I'll be okay\""},{"id":"b","text":"\"I ruin everything\""},{"id":"c","text":"\"I can try a different way\""},{"id":"d","text":"\"Nobody will ever pick me\""},{"id":"e","text":"\"It's fair to feel let down\""},{"id":"f","text":"\"I'm a total loser\""}],"bins":[{"id":"kind","label":"Kind self-talk","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"}},
  {"id":"mm-1131","cat":"handling-rejection","type":"sort","hook":"Sort: handle it yourself, or tell a trusted adult?","persona":"any","source":"rejection / help-seeking","relearn":"Small setbacks pass; big or lasting low feelings mean tell a trusted adult.","items":[{"id":"a","text":"A bit sad, then okay by evening"},{"id":"b","text":"The low feeling lasts for weeks"},{"id":"c","text":"Disappointed, then try again next week"},{"id":"d","text":"You feel you can't cope anymore"},{"id":"e","text":"Stung, then you talk to a friend"},{"id":"f","text":"Any dark thoughts at all"}],"bins":[{"id":"selfhandle","label":"Handle it yourself","valence":"pos"},{"id":"tell","label":"Tell a trusted adult","valence":"tell"}],"key":{"a":"selfhandle","b":"tell","c":"selfhandle","d":"tell","e":"selfhandle","f":"tell"}},
  {"id":"mm-1132","cat":"handling-rejection","type":"build","hook":"Build your bounce-back plan for after a 'no'.","persona":"any","source":"rejection / coping plan","relearn":"Bounce back by feeling it, being kind, talking, then trying again.","prompt":"Put the bounce-back steps in order.","pieces":["let yourself feel the hurt","be kind to yourself","talk to someone you trust","try again or try something else"],"mode":"sequence","key":["let yourself feel the hurt","be kind to yourself","talk to someone you trust","try again or try something else"]},
  {"id":"mm-1133","cat":"handling-rejection","type":"build","hook":"Build a kit of healthy moves for when a rejection stings.","persona":"any","source":"rejection / coping toolkit","relearn":"Healthy bounce-back moves: name it, breathe, talk, do something you enjoy.","prompt":"Choose the moves that belong in a bounce-back kit.","pieces":["name the feeling","slow breathing","talk to a trusted adult","do something you enjoy"],"mode":"assemble","key":["name the feeling","slow breathing","talk to a trusted adult","do something you enjoy"]},
  {"id":"mm-1134","cat":"handling-rejection","type":"build","hook":"Build the words to comfort a friend who got left out.","persona":"Asha","source":"rejection / peer support","relearn":"Comfort a friend: name the hurt, say you're there, then include them.","prompt":"Put the comforting steps in order.","pieces":["say 'that really hurts'","tell them you're here","invite them to join you","do something fun together"],"mode":"sequence","key":["say 'that really hurts'","tell them you're here","invite them to join you","do something fun together"]},
  {"id":"mm-1135","cat":"handling-rejection","type":"build","hook":"Build the steps to calm down right after a hard 'no'.","persona":"any","source":"rejection / grounding","relearn":"Calm a sting: feet on floor, slow breaths, name the feeling, let it pass.","prompt":"Put the calm-down steps in order.","pieces":["put your feet on the floor","take three slow breaths","name what you feel","let it pass"],"mode":"sequence","key":["put your feet on the floor","take three slow breaths","name what you feel","let it pass"]},
  {"id":"mm-1136","cat":"handling-rejection","type":"build","hook":"Build a plan for trying again after a failed attempt.","persona":"any","source":"rejection / growth","relearn":"Try again well: rest, learn one thing, make a small plan, have another go.","prompt":"Put the try-again steps in order.","pieces":["rest and be kind to yourself","learn one thing from it","make a small plan","have another go"],"mode":"sequence","key":["rest and be kind to yourself","learn one thing from it","make a small plan","have another go"]},
  {"id":"mm-1137","cat":"handling-rejection","type":"build","hook":"Build what to say when you ask a trusted adult for help after a setback.","persona":"Rohit","source":"rejection / help-seeking","relearn":"Ask plainly: name the setback, say it's heavy, ask to talk, name what you need.","prompt":"Put the asking-for-help steps in order.","pieces":["name the setback","say it's been weighing on you","ask 'can we talk?'","say what would help"],"mode":"sequence","key":["name the setback","say it's been weighing on you","ask 'can we talk?'","say what would help"]},
  {"id":"mm-1138","cat":"handling-rejection","type":"match","hook":"Match the setback to a kind, healthy response.","persona":"any","source":"rejection / coping","relearn":"Each setback has a kind next step: feel it, talk, learn, try again, lean on someone.","pairs":[{"left":"Not picked for the team","right":"Practise and try again"},{"left":"Left out by friends","right":"Talk and stay open"},{"left":"Failed a test","right":"Learn one thing for next time"},{"left":"A setback you can't shake","right":"Tell a trusted adult"},{"left":"The hurt is fresh","right":"Let yourself feel it"}]},
  {"id":"mm-1139","cat":"handling-rejection","type":"match","hook":"Match the unkind thought to a kinder rewrite.","persona":"any","source":"rejection / reframing","relearn":"Each harsh thought has a kinder, truer rewrite you can choose instead.","pairs":[{"left":"\"I'm not good enough\"","right":"\"This 'no' isn't about my worth\""},{"left":"\"Nobody likes me\"","right":"\"One miss isn't everyone\""},{"left":"\"I'll always fail\"","right":"\"One setback isn't my future\""},{"left":"\"I should hide the hurt\"","right":"\"It's okay to feel it\""},{"left":"\"Trying again is pointless\"","right":"\"Trying again is brave\""}]},
  {"id":"mm-1140","cat":"handling-rejection","type":"match","hook":"Match the comforting words to what they do for a hurting friend.","persona":"Asha","source":"rejection / peer support","relearn":"Comforting words validate the hurt, offer company, and never dismiss.","pairs":[{"left":"\"That really hurts\"","right":"Names the feeling"},{"left":"\"I'm right here\"","right":"Offers company"},{"left":"\"It's okay to be sad\"","right":"Gives permission to feel"},{"left":"\"Want to talk about it?\"","right":"Opens a door"},{"left":"\"One 'no' isn't all of you\"","right":"Widens the picture"}]},
  {"id":"mm-1141","cat":"handling-rejection","type":"match","hook":"Match the worry after a setback to the right person to turn to.","persona":"Asha","source":"rejection / routing","relearn":"Match each worry to a helper: a friend, a teacher, a parent, or Childline.","pairs":[{"left":"Just need to vent","right":"A trusted friend"},{"left":"Struggling with a subject","right":"A teacher"},{"left":"Feeling low at home","right":"A parent or ASHA didi"},{"left":"A low feeling that won't lift","right":"Childline 1098"},{"left":"Not sure who to ask","right":"A near-peer like Asha"}]},
  {"id":"mm-1142","cat":"handling-rejection","type":"match","hook":"Match the rejection myth to the truth that replaces it.","persona":"any","source":"rejection / cognitive","relearn":"Each rejection myth has a truth: it's not your worth, it passes, you can try again.","pairs":[{"left":"Rejection means I'm not good enough","right":"It often isn't about my worth"},{"left":"Big feelings last forever","right":"They rise, peak and pass"},{"left":"One failure defines me","right":"One setback isn't my future"},{"left":"Asking for help is shameful","right":"Reaching out is brave"},{"left":"I must never feel the hurt","right":"The hurt is real and okay"}]},
  {"id":"mm-1170","cat":"mind-care-toolkit","type":"build","persona":"any","source":"behavioural activation","hook":"Build a 'quick reset' kit for a stressful afternoon.","prompt":"Pick healthy moves for a quick reset.","pieces":["splash water on your face","take ten slow breaths","stretch your arms","step outside for air"],"mode":"assemble","key":["splash water on your face","take ten slow breaths","stretch your arms","step outside for air"],"relearn":"A quick reset: water, breath, stretch, fresh air."},
  {"id":"mm-1171","cat":"mind-care-toolkit","type":"build","persona":"any","source":"problem-solving","hook":"Build the steps to start homework that feels too big.","prompt":"Order how to begin a big homework pile.","pieces":["pick the easiest task first","set a small timer","do just that one task","take a short break"],"mode":"sequence","key":["pick the easiest task first","set a small timer","do just that one task","take a short break"],"relearn":"Start small: easiest task, short timer, one step, a break."},
  {"id":"mm-1172","cat":"mind-care-toolkit","type":"build","persona":"any","source":"grounding technique","hook":"Build the 5-4-3-2-1 grounding move for a racing mind.","prompt":"Order the senses you notice to ground yourself.","pieces":["five things you see","four things you can touch","three things you hear","two things you smell"],"mode":"sequence","key":["five things you see","four things you can touch","three things you hear","two things you smell"],"relearn":"Grounding: notice what you see, touch, hear and smell."},
  {"id":"mm-1173","cat":"mind-care-toolkit","type":"build","persona":"any","source":"sleep / routine","hook":"Build a 'can't sleep' kit for a worried night.","prompt":"Pick calm tools for a restless night.","pieces":["dim the lights","slow square breathing","write the worry down for morning","a soothing thought"],"mode":"assemble","key":["dim the lights","slow square breathing","write the worry down for morning","a soothing thought"],"relearn":"For a restless night: dim light, breathe, park the worry, settle."},
  {"id":"mm-1174","cat":"mind-care-toolkit","type":"build","persona":"Diya","source":"emotion regulation","hook":"Diya feels left out. Build a kind plan to feel better.","prompt":"Order a kind plan after feeling left out.","pieces":["let yourself feel the hurt","name what you need","reach out to one kind person","do something you enjoy"],"mode":"sequence","key":["let yourself feel the hurt","name what you need","reach out to one kind person","do something you enjoy"],"relearn":"Feel it, name it, reach out, then do something kind for you."},
  {"id":"mm-1175","cat":"mind-care-toolkit","type":"build","persona":"any","source":"behavioural activation","hook":"Build a 'feel-good in five minutes' kit.","prompt":"Pick quick healthy mood-lifters.","pieces":["dance to one song","call a friend","step into sunlight","pet a calm animal"],"mode":"assemble","key":["dance to one song","call a friend","step into sunlight","pet a calm animal"],"relearn":"Five-minute lifts: a song, a friend, sunlight, a gentle pet."},
  {"id":"mm-1176","cat":"mind-care-toolkit","type":"build","persona":"Aarav","source":"anger management (links g41)","hook":"Aarav feels anger flare. Build a cool-down plan.","prompt":"Order a healthy cool-down for anger.","pieces":["notice the anger rising","step away from the spot","breathe out long and slow","come back when calmer"],"mode":"sequence","key":["notice the anger rising","step away from the spot","breathe out long and slow","come back when calmer"],"relearn":"Cool down anger: notice, step away, breathe long, return calm."},
  {"id":"mm-1177","cat":"mind-care-toolkit","type":"build","persona":"any","source":"breathing technique","hook":"Build 'belly breathing' to calm a tight chest.","prompt":"Order the belly-breathing steps.","pieces":["hand on your belly","breathe in so it rises","breathe out so it falls","feel your body slow down"],"mode":"sequence","key":["hand on your belly","breathe in so it rises","breathe out so it falls","feel your body slow down"],"relearn":"Belly breathing: hand on belly, it rises, it falls, you slow."},
  {"id":"mm-1178","cat":"mind-care-toolkit","type":"build","persona":"any","source":"coping toolkit","hook":"Build an exam-morning calm kit.","prompt":"Pick steady tools for exam morning.","pieces":["eat a proper breakfast","a few slow breaths","one kind thought to yourself","go in early, not rushed"],"mode":"assemble","key":["eat a proper breakfast","a few slow breaths","one kind thought to yourself","go in early, not rushed"],"relearn":"Exam-morning calm: eat, breathe, be kind, arrive unhurried."},
  {"id":"mm-1179","cat":"mind-care-toolkit","type":"build","persona":"any","source":"problem-solving","hook":"Build a plan for a worry you keep avoiding.","prompt":"Order how to face a worry you avoid.","pieces":["write the worry plainly","ask: can I do anything about it","do one small thing you can","let go of what you can't"],"mode":"sequence","key":["write the worry plainly","ask: can I do anything about it","do one small thing you can","let go of what you can't"],"relearn":"Name the worry, act on what you can, release what you can't."},
  {"id":"mm-1180","cat":"mind-care-toolkit","type":"build","persona":"any","source":"emotion regulation","hook":"Build a 'big wave of sadness' kit.","prompt":"Pick gentle tools for a wave of sadness.","pieces":["let the tears come","wrap up warm","tell someone you trust","wait for the wave to pass"],"mode":"assemble","key":["let the tears come","wrap up warm","tell someone you trust","wait for the wave to pass"],"relearn":"Sadness passes: let it out, stay warm, tell someone, ride it out."},
  {"id":"mm-1181","cat":"mind-care-toolkit","type":"build","persona":"any","source":"behavioural activation","hook":"Build a daily mind-care habit list.","prompt":"Pick small daily habits that keep your mind well.","pieces":["enough sleep","time outdoors","talk about your day","a little movement"],"mode":"assemble","key":["enough sleep","time outdoors","talk about your day","a little movement"],"relearn":"Daily mind-care: sleep, fresh air, talking, a little movement."},
  {"id":"mm-1182","cat":"mind-care-toolkit","type":"build","persona":"Asha","source":"coping toolkit","hook":"Asha helps you make a 'who can I talk to' list.","prompt":"Pick trusted people for your talk-to list.","pieces":["a parent or guardian","a teacher you like","a close friend","an ASHA or NGO didi"],"mode":"assemble","key":["a parent or guardian","a teacher you like","a close friend","an ASHA or NGO didi"],"relearn":"Your talk-to list: a parent, a teacher, a friend, an ASHA didi."},
  {"id":"mm-1183","cat":"mind-care-toolkit","type":"build","persona":"any","source":"problem-solving","hook":"Build the steps to handle a fight with a friend.","prompt":"Order a calm way to mend a friendship fight.","pieces":["cool down first","think what you feel","talk it out gently","listen to their side"],"mode":"sequence","key":["cool down first","think what you feel","talk it out gently","listen to their side"],"relearn":"Mend a fight: cool down, know your feeling, talk gently, listen."},
  {"id":"mm-1184","cat":"mind-care-toolkit","type":"build","persona":"any","source":"grounding technique","hook":"Build a 'panic on the school bus' calm kit.","prompt":"Pick quiet tools for panic in a crowded place.","pieces":["press your feet down","count your slow breaths","hold something in your hand","remind yourself it will pass"],"mode":"assemble","key":["press your feet down","count your slow breaths","hold something in your hand","remind yourself it will pass"],"relearn":"In a crowd: feet down, slow breaths, hold something, it passes."},
  {"id":"mm-1185","cat":"mind-care-toolkit","type":"build","persona":"any","source":"sleep / routine","hook":"Build a screen-free wind-down before bed.","prompt":"Order a calming screen-free evening.","pieces":["put the phone away early","wash up and get cosy","read or listen to something calm","lights off and slow breaths"],"mode":"sequence","key":["put the phone away early","wash up and get cosy","read or listen to something calm","lights off and slow breaths"],"relearn":"Wind down: phone away, get cosy, something calm, then sleep."},
  {"id":"mm-1186","cat":"mind-care-toolkit","type":"build","persona":"any","source":"behavioural activation","hook":"Build a 'stuck and bored' lift that actually helps.","prompt":"Pick healthy lifts for a flat, stuck mood.","pieces":["change your spot","do something with your hands","help someone with a task","get a little fresh air"],"mode":"assemble","key":["change your spot","do something with your hands","help someone with a task","get a little fresh air"],"relearn":"For a flat mood: move spots, use your hands, help, get air."},
  {"id":"mm-1187","cat":"mind-care-toolkit","type":"build","persona":"any","source":"emotion regulation","hook":"Build the 'name it to tame it' kit for a confusing feeling.","prompt":"Pick steps to understand a confusing feeling.","pieces":["pause and notice it","put a name to it","find where you feel it in your body","choose one kind response"],"mode":"assemble","key":["pause and notice it","put a name to it","find where you feel it in your body","choose one kind response"],"relearn":"Name a feeling to tame it: notice, name, locate, respond kindly."},
  {"id":"mm-1188","cat":"mind-care-toolkit","type":"build","persona":"any","source":"problem-solving","hook":"Build a plan when everything feels like too much.","prompt":"Order what to do when it all feels too much.","pieces":["stop and breathe","write down everything on your mind","circle just one thing to do now","ask for help if you're stuck"],"mode":"sequence","key":["stop and breathe","write down everything on your mind","circle just one thing to do now","ask for help if you're stuck"],"relearn":"When overwhelmed: breathe, empty your mind, pick one, ask if stuck."},
  {"id":"mm-1189","cat":"mind-care-toolkit","type":"build","persona":"Aarav","source":"coping toolkit","hook":"Aarav wants tools that aren't 'cringe'. Build a real kit.","prompt":"Pick tools a 12-year-old can actually use.","pieces":["a tough workout to burn it off","music with the volume up","talk to one mate you trust","write it out, no one reads it"],"mode":"assemble","key":["a tough workout to burn it off","music with the volume up","talk to one mate you trust","write it out, no one reads it"],"relearn":"Real tools: hard exercise, loud music, one mate, private writing."},
  {"id":"mm-1190","cat":"mind-care-toolkit","type":"build","persona":"any","source":"grounding technique","hook":"Build a tiny 'pocket calm' you can use anywhere.","prompt":"Pick a calm move that's invisible to others.","pieces":["breathe in for four counts","breathe out for six counts","drop your shoulders","unclench your jaw"],"mode":"sequence","key":["breathe in for four counts","breathe out for six counts","drop your shoulders","unclench your jaw"],"relearn":"Pocket calm: in four, out six, shoulders down, jaw loose."},
  {"id":"mm-1191","cat":"mind-care-toolkit","type":"build","persona":"any","source":"behavioural activation","hook":"Build a 'weekend recharge' for a tired mind.","prompt":"Pick things that genuinely recharge you.","pieces":["sleep in a little","time with people who get you","a hobby you love","being out in nature"],"mode":"assemble","key":["sleep in a little","time with people who get you","a hobby you love","being out in nature"],"relearn":"Recharge a tired mind: rest, good company, a hobby, nature."},
  {"id":"mm-1192","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"Your mind is racing the night before a test.","options":[{"text":"Try square breathing and one kind thought","consequence":"Your body settles and you drift off.","outcome":"calm","best":true},{"text":"Keep re-reading notes at midnight","consequence":"Breathing and rest help more than midnight cramming."}],"debrief":"Rest and a calm tool serve you better than late panic.","relearn":"Breathe and rest the night before; cramming late drains you."},
  {"id":"mm-1193","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"Worry won't leave your head all morning.","options":[{"text":"Write the worry down to deal with later","consequence":"Naming it on paper loosens its grip.","outcome":"eased","best":true},{"text":"Tell yourself to just stop thinking it","consequence":"Writing a worry down eases it more than forcing it away."}],"debrief":"A worry on paper feels smaller than one stuck in your head.","relearn":"Write a sticky worry down to loosen its grip."},
  {"id":"mm-1194","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You snap at your sister and feel awful after.","options":[{"text":"Cool down, then say sorry and explain you're stressed","consequence":"You repair it and feel lighter.","outcome":"repaired","best":true},{"text":"Stay grumpy and avoid her all day","consequence":"A calm apology mends it faster than avoiding her."}],"debrief":"Cooling down then repairing beats stewing in it.","relearn":"After snapping, cool down and repair with a calm sorry."},
  {"id":"mm-1195","cat":"mind-care-toolkit","type":"branch","persona":"Diya","source":"coping in action","hook":"Diya wasn't invited to a classmate's party.","options":[{"text":"Let herself feel sad, then plan fun with her own friends","consequence":"The sting fades and her day fills up.","outcome":"bounced","best":true},{"text":"Decide nobody likes her and stay in bed","consequence":"Feeling it then reaching out helps more than shutting in."}],"debrief":"Feel the hurt, then turn toward people who do include you.","relearn":"After being left out, feel it then turn to your own people."},
  {"id":"mm-1196","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You feel a panicky wave during morning assembly.","options":[{"text":"Press your feet down and slow your breathing","consequence":"The wave peaks and passes while you stand still.","outcome":"grounded","best":true},{"text":"Try to run out, heart pounding","consequence":"Grounding where you are lets the wave pass safely."}],"debrief":"You can ride out a wave quietly, right where you are.","relearn":"Ground yourself in place; a panic wave peaks and passes."},
  {"id":"mm-1197","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You've been low for two weeks and tools aren't helping.","options":[{"text":"Tell a trusted adult that you've felt low a while","consequence":"They listen and help you find more support.","outcome":"supported","best":true},{"text":"Keep it to yourself and hope it lifts","consequence":"A lasting low is a sign to tell a trusted adult, not wait alone."}],"debrief":"When a low lasts, telling an adult is the strong next step.","relearn":"A trusted adult or Childline 1098 is always there to listen."},
  {"id":"mm-1198","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You keep scrolling reels but feel worse and worse.","options":[{"text":"Put the phone down and do one real thing you enjoy","consequence":"Your mood lifts once you switch off the scroll.","outcome":"lifted","best":true},{"text":"Scroll for another hour to feel better","consequence":"A real activity lifts a low mood more than endless scrolling."}],"debrief":"Switching off the scroll for a real thing actually helps.","relearn":"Endless scrolling rarely lifts a low mood; a real thing does."},
  {"id":"mm-1199","cat":"mind-care-toolkit","type":"branch","persona":"Aarav","source":"coping in action","hook":"Aarav loses a tough match online and feels the rage build.","options":[{"text":"Log off, walk it off, come back later","consequence":"The heat drains and he plays calmer next time.","outcome":"cooled","best":true},{"text":"Keep playing while furious","consequence":"Stepping away cools the rage better than raging on."}],"debrief":"Stepping away from the heat protects you and your game.","relearn":"When rage builds, step away and cool down before going on."},
  {"id":"mm-1200","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"A big project feels impossible and you're frozen.","options":[{"text":"Break it into tiny parts and do just the first","consequence":"Starting small breaks the freeze.","outcome":"unstuck","best":true},{"text":"Stare at the whole thing feeling stuck","consequence":"One tiny first step unfreezes you faster than staring."}],"debrief":"You're never stuck: there's always a small first step.","relearn":"Break a frozen task into tiny parts; do just the first."},
  {"id":"mm-1201","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"Your chest is tight and your thoughts are spinning fast.","options":[{"text":"Notice the signals and slow your breathing","consequence":"Naming the stress signal helps you ease it.","outcome":"eased","best":true},{"text":"Ignore it and push through harder","consequence":"Noticing and easing a stress signal beats pushing through it."}],"debrief":"Noticing a stress signal is the first step to easing it.","relearn":"Notice stress signals like a tight chest, then slow your breath."},
  {"id":"mm-1202","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You're so anxious you skipped lunch and feel shaky.","options":[{"text":"Eat something and take a slow breathing break","consequence":"Food and a pause steady your body.","outcome":"steadier","best":true},{"text":"Keep working through the shakiness","consequence":"Caring for your body with food and a break steadies you."}],"debrief":"Your mind needs your body fed and rested to cope.","relearn":"Feed and rest your body; the mind copes better when it's cared for."},
  {"id":"mm-1203","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You bottled up a hard feeling and now it's bursting out.","options":[{"text":"Find a safe way to let it out, talk or write it","consequence":"Letting it out gently releases the pressure.","outcome":"released","best":true},{"text":"Keep bottling it tighter","consequence":"Letting a feeling out safely helps more than bottling it up."}],"debrief":"Bottling up builds pressure; a safe outlet releases it.","relearn":"Let feelings out safely; bottling everything up harms your mind."},
  {"id":"mm-1204","cat":"mind-care-toolkit","type":"branch","persona":"any","source":"coping in action","hook":"You don't know which tool to reach for right now.","options":[{"text":"Match the feeling to a tool, then try one","consequence":"Picking a tool that fits helps the feeling ease.","outcome":"matched","best":true},{"text":"Decide nothing works and give up","consequence":"Matching a feeling to a fitting tool helps; you get to choose."}],"debrief":"Different tools fit different moments, and you choose which.","relearn":"Match the feeling to the tool; you choose which one to use."},
  {"id":"mm-1205","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: does this belong in a mind-care kit?","items":[{"id":"a","text":"Slow breathing"},{"id":"b","text":"Bottling it all up"},{"id":"c","text":"Talking to someone you trust"},{"id":"d","text":"Hurting yourself to cope"},{"id":"e","text":"Moving your body"},{"id":"f","text":"Numbing out for hours"}],"bins":[{"id":"in","label":"In the kit","valence":"pos"},{"id":"out","label":"Not a tool","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Only healthy tools belong in the kit; harmful 'tricks' never do."},
  {"id":"mm-1206","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: which tool calms you NOW, which keeps you well over TIME?","items":[{"id":"a","text":"Square breathing this minute"},{"id":"b","text":"Sleeping well each night"},{"id":"c","text":"Grounding during panic"},{"id":"d","text":"Regular time outdoors"},{"id":"e","text":"A quick walk to cool off"},{"id":"f","text":"Talking about your day often"}],"bins":[{"id":"now","label":"Calm right now","valence":"pos"},{"id":"over","label":"Keeps you well","valence":"neutral"}],"key":{"a":"now","b":"over","c":"now","d":"over","e":"now","f":"over"},"relearn":"Some tools calm you now; others keep your mind well over time."},
  {"id":"mm-1207","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: handle it yourself, or time to tell an adult?","items":[{"id":"a","text":"A bad mood that lifts by evening"},{"id":"b","text":"Feeling low every day for weeks"},{"id":"c","text":"Nerves before one exam"},{"id":"d","text":"Any thoughts of hurting yourself"},{"id":"e","text":"Sad after losing a game"},{"id":"f","text":"A worry too big to handle alone"}],"bins":[{"id":"self","label":"You've got this","valence":"pos"},{"id":"tell","label":"Tell an adult","valence":"tell"}],"key":{"a":"self","b":"tell","c":"self","d":"tell","e":"self","f":"tell"},"relearn":"Big or lasting feelings, or dark thoughts, mean tell a trusted adult."},
  {"id":"mm-1208","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: helps your mind, or harms it?","items":[{"id":"a","text":"Enough sleep"},{"id":"b","text":"Skipping sleep to study"},{"id":"c","text":"Taking breaks"},{"id":"d","text":"Never resting at all"},{"id":"e","text":"Naming your feelings"},{"id":"f","text":"Hiding every feeling"}],"bins":[{"id":"helps","label":"Helps your mind","valence":"pos"},{"id":"harms","label":"Harms your mind","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Rest and naming feelings help; no rest and hiding them harm."},
  {"id":"mm-1209","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: a real coping tool, or a fake 'trick'?","items":[{"id":"a","text":"A slow, steady walk"},{"id":"b","text":"Picking a fight to let it out"},{"id":"c","text":"Writing it down"},{"id":"d","text":"Skipping meals when upset"},{"id":"e","text":"Asking for a hug"},{"id":"f","text":"Shutting everyone out for days"}],"bins":[{"id":"real","label":"Real tool","valence":"pos"},{"id":"fake","label":"Fake 'trick'","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Walking, writing and a hug are real tools; the harmful ones aren't."},
  {"id":"mm-1210","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: which tool fits, feeling panicky, or feeling restless?","items":[{"id":"a","text":"Grounding with your feet"},{"id":"b","text":"Going for a run"},{"id":"c","text":"Slow square breathing"},{"id":"d","text":"Dancing it out"},{"id":"e","text":"Counting what you can see"},{"id":"f","text":"Kicking a ball outside"}],"bins":[{"id":"panic","label":"For panic","valence":"pos"},{"id":"restless","label":"For restlessness","valence":"neutral"}],"key":{"a":"panic","b":"restless","c":"panic","d":"restless","e":"panic","f":"restless"},"relearn":"Grounding suits panic; movement suits a restless, fidgety mood."},
  {"id":"mm-1211","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: calms your body, or revs up the stress?","items":[{"id":"a","text":"Long, slow out-breaths"},{"id":"b","text":"Holding your breath in fear"},{"id":"c","text":"A gentle stretch"},{"id":"d","text":"Clenching everything tight"},{"id":"e","text":"Warm tea and quiet"},{"id":"f","text":"Doom-scrolling bad news"}],"bins":[{"id":"calms","label":"Calms the body","valence":"pos"},{"id":"revs","label":"Revs up stress","valence":"neg"}],"key":{"a":"calms","b":"revs","c":"calms","d":"revs","e":"calms","f":"revs"},"relearn":"Slow breaths, stretching and quiet calm; clenching and doom-scrolling don't."},
  {"id":"mm-1212","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: which tool matches the feeling?","items":[{"id":"a","text":"Square breathing"},{"id":"b","text":"Talk to someone kind"},{"id":"c","text":"Move your body"},{"id":"d","text":"Shrink it into small steps"},{"id":"e","text":"Rest and a soothing thing"},{"id":"f","text":"Name it out loud"}],"bins":[{"id":"calm","label":"To calm down","valence":"pos"},{"id":"clear","label":"To get unstuck","valence":"neutral"}],"key":{"a":"calm","b":"calm","c":"clear","d":"clear","e":"calm","f":"clear"},"relearn":"Some tools calm a feeling; others help you get unstuck and act."},
  {"id":"mm-1213","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: kind self-talk, or harsh self-talk?","items":[{"id":"a","text":"'I can try again tomorrow'"},{"id":"b","text":"'I'm useless at everything'"},{"id":"c","text":"'It's okay to find this hard'"},{"id":"d","text":"'I should be perfect'"},{"id":"e","text":"'I did my best today'"},{"id":"f","text":"'Everyone is better than me'"}],"bins":[{"id":"kind","label":"Kind self-talk","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Talk to yourself like a friend; rewrite the harsh voice kindly."},
  {"id":"mm-1214","cat":"mind-care-toolkit","type":"sort","persona":"any","source":"coping","hook":"Sort: a quick in-the-moment tool, or a daily care habit?","items":[{"id":"a","text":"Ten slow breaths now"},{"id":"b","text":"Going to bed on time"},{"id":"c","text":"Pressing your feet down"},{"id":"d","text":"Daily time with friends"},{"id":"e","text":"Splashing cold water"},{"id":"f","text":"A regular hobby you love"}],"bins":[{"id":"quick","label":"Quick tool","valence":"pos"},{"id":"daily","label":"Daily habit","valence":"neutral"}],"key":{"a":"quick","b":"daily","c":"quick","d":"daily","e":"quick","f":"daily"},"relearn":"Quick tools steady a moment; daily habits keep your mind well."},
  {"id":"mm-1215","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the feeling to a tool that helps it.","pairs":[{"left":"Panic","right":"Grounding with your feet"},{"left":"Sadness","right":"Talking to someone kind"},{"left":"Restlessness","right":"Moving your body"},{"left":"Overwhelm","right":"Breaking it into steps"},{"left":"A tight chest","right":"Slow square breathing"}],"relearn":"Each feeling has a tool that fits it best."},
  {"id":"mm-1216","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the tool to what it does for you.","pairs":[{"left":"Slow breathing","right":"Calms the body"},{"left":"Talking it out","right":"Lightens the load"},{"left":"Movement","right":"Shifts a low mood"},{"left":"Grounding","right":"Steadies a racing mind"},{"left":"Rest","right":"Refills your energy"}],"relearn":"Each coping tool helps your mind in its own way."},
  {"id":"mm-1217","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the square-breathing step to its count.","pairs":[{"left":"Breathe in","right":"For four counts"},{"left":"Hold","right":"Then four more"},{"left":"Breathe out","right":"Slowly to four"},{"left":"Pause","right":"A still count of four"},{"left":"Repeat","right":"Until your body slows"}],"relearn":"Square breathing: in four, hold four, out four, pause four."},
  {"id":"mm-1218","cat":"mind-care-toolkit","type":"match","persona":"Asha","source":"coping","hook":"Asha asks: match each worry to a good helper.","pairs":[{"left":"Trouble at home","right":"A trusted adult"},{"left":"Struggling with a subject","right":"A teacher you like"},{"left":"A heavy feeling","right":"Childline 1098"},{"left":"A lonely day","right":"A close friend"},{"left":"A health question","right":"An ASHA didi"}],"relearn":"Match a worry to the right helper; there's always someone."},
  {"id":"mm-1219","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the moment to the tool that fits it.","pairs":[{"left":"Can't fall asleep","right":"Dim light and slow breaths"},{"left":"Frozen before homework","right":"One tiny first step"},{"left":"Anger flaring","right":"Step away to cool down"},{"left":"Feeling flat","right":"Do something you enjoy"},{"left":"A racing mind","right":"Name five things you see"}],"relearn":"The right tool depends on the moment you're in."},
  {"id":"mm-1220","cat":"mind-care-toolkit","type":"match","persona":"any","source":"coping","hook":"Match the kind self-talk to the harsh thought it replaces.","pairs":[{"left":"'I failed, I'm useless'","right":"'I can learn from this'"},{"left":"'I must be perfect'","right":"'Good enough is okay'"},{"left":"'Resting is lazy'","right":"'My mind needs rest'"},{"left":"'No one likes me'","right":"'Some people do care'"},{"left":"'I should hide this'","right":"'Asking for help is brave'"}],"relearn":"Swap a harsh thought for a kinder, truer one."},
  {"id":"mm-1221","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"Which tool do you reach for first?","prompt":"When you feel stressed, what helps you most?","options":["Slow breathing","Talking to someone","Moving my body","A quiet break"],"affirm":"There's no wrong pick: knowing your own tool is real skill.","relearn":"Knowing which tool works for you is a skill worth keeping."},
  {"id":"mm-1222","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"Where do you feel stress in your body?","prompt":"When you're stressed, where do you notice it?","options":["A tight chest","A busy head","A churning tummy","Tense shoulders"],"affirm":"Noticing your own signal is the first step to easing it.","relearn":"Noticing a stress signal is the first step to easing it."},
  {"id":"mm-1223","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"Who is on your talk-to list?","prompt":"Who could you turn to on a hard day?","options":["A parent or guardian","A teacher I trust","A close friend","An ASHA or NGO didi"],"affirm":"Any of them is a good choice. You have people to turn to.","relearn":"You have people to turn to on a hard day."},
  {"id":"mm-1224","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"What lifts your mood when it dips?","prompt":"What's your go-to mood-lifter?","options":["Music I love","Being outside","Time with a friend","A hobby I enjoy"],"affirm":"Whatever lifts you genuinely is worth keeping in your kit.","relearn":"What genuinely lifts you belongs in your mind-care kit."},
  {"id":"mm-1225","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"How does your mind rest best?","prompt":"What helps your mind truly rest?","options":["Good sleep","Quiet time alone","A calm hobby","Being in nature"],"affirm":"Rest isn't lazy. Your mind needs it, however you find it.","relearn":"Rest isn't lazy; your mind needs it to stay well."},
  {"id":"mm-1226","cat":"mind-care-toolkit","type":"reflect","persona":"Diya","source":"self check-in","hook":"Diya asks how you comfort yourself.","prompt":"When you feel low, how are you kind to yourself?","options":["I rest without guilt","I talk it out","I do something gentle","I remind myself it passes"],"affirm":"Being gentle with yourself on a hard day is real mind-care.","relearn":"Being gentle with yourself on a hard day is real mind-care."},
  {"id":"mm-1227","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"What does your mind need most right now?","prompt":"Right now, what would help your mind?","options":["A slow breath","A talk with someone","A short break","A bit of movement"],"affirm":"Checking in and choosing for yourself is a skill you keep.","relearn":"Checking in and choosing a tool for yourself is a skill."},
  {"id":"mm-1228","cat":"mind-care-toolkit","type":"reflect","persona":"any","source":"self check-in","hook":"Which calming move feels most like 'you'?","prompt":"Which calm-down move suits you best?","options":["Square breathing","Grounding my feet","A quiet walk","Writing it down"],"affirm":"There's no single right tool: yours is the one that helps you.","relearn":"There's no single right tool; yours is the one that helps you."},
  {"id":"mm-1229","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about coping tools.","myth":{"un":"You should just 'tough it out' with no tools.","re":"Healthy coping tools genuinely help you handle hard feelings.","why":"Breathing, talking and movement are proven, safe ways to cope."},"relearn":"Healthy coping tools genuinely help you handle hard feelings."},
  {"id":"mm-1230","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about resting.","myth":{"un":"Taking a break means you're being lazy.","re":"Rest is not lazy. Your mind needs breaks to stay well.","why":"A rested mind copes, focuses and feels steadier than a drained one."},"relearn":"Rest is not lazy; your mind needs breaks to stay well."},
  {"id":"mm-1231","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about big feelings.","myth":{"un":"A coping tool has to make the feeling vanish at once.","re":"Tools help a feeling pass; they don't have to erase it instantly.","why":"Feelings rise, peak and pass like weather, and tools ease the ride."},"relearn":"Tools help a feeling pass; they need not erase it instantly."},
  {"id":"mm-1232","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"Aarav","source":"de-stigmatise","hook":"Aarav flips the myth about 'real' tools.","myth":{"un":"Breathing and talking are soft, not for tough kids.","re":"Using a calm tool takes strength, and it works for everyone.","why":"Top athletes breathe to steady nerves; managing yourself is power."},"relearn":"Using a calm tool takes strength and works for everyone."},
  {"id":"mm-1233","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about bottling up.","myth":{"un":"Keeping every feeling inside makes you stronger.","re":"Letting feelings out safely keeps your mind healthier than bottling up.","why":"Bottled-up feelings build pressure; talking or writing releases it."},"relearn":"Letting feelings out safely is healthier than bottling them up."},
  {"id":"mm-1234","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about one perfect tool.","myth":{"un":"There's one magic tool that fixes every feeling.","re":"Different tools fit different moments, and you pick what fits.","why":"Grounding suits panic, movement suits restlessness; you choose."},"relearn":"Different tools fit different moments; you pick what fits."},
  {"id":"mm-1235","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about a busy mind.","myth":{"un":"Your mind doesn't need care the way your body does.","re":"Your mind needs care and rest just like your body does.","why":"Sleep, talking and breaks keep the mind well, like food keeps the body."},"relearn":"Your mind needs care and rest just like your body does."},
  {"id":"mm-1236","cat":"mind-care-toolkit","type":"strike-rewrite","persona":"any","source":"de-stigmatise","hook":"Flip the myth about needing a crisis to use tools.","myth":{"un":"You only need coping tools when things get really bad.","re":"Using your tools on ordinary days keeps the hard days easier.","why":"A kit you practise often is ready the moment you really need it."},"relearn":"Using your tools on ordinary days keeps the hard days easier."},
  {"id":"mm-1237","cat":"mind-care-toolkit","type":"role-play","persona":"any","source":"voice / ask & route","hook":"A friend looks stressed about exams. Say the words.","setup":"Your friend is panicking before the test. What do you offer?","yourLine":[{"text":"Let's take a few slow breaths together first.","best":true},{"text":"Just relax, it's not a big deal."}],"relearn":"Offering a calm tool helps a friend more than 'just relax'."},
  {"id":"mm-1238","cat":"mind-care-toolkit","type":"role-play","persona":"any","source":"voice / ask & route","hook":"Your mind is racing. Ask for a tool out loud.","setup":"You feel overwhelmed at home. What do you say?","yourLine":[{"text":"Can we sit and breathe for a minute? I'm overwhelmed.","best":true},{"text":"Nothing, I'm fine, leave me alone."}],"relearn":"Naming overwhelm and asking for a calm minute is a strong move."},
  {"id":"mm-1239","cat":"mind-care-toolkit","type":"role-play","persona":"any","source":"voice / ask & route","hook":"A classmate is crying after a bad result. Say something kind.","setup":"They got a low mark and feel awful. What do you say?","yourLine":[{"text":"That really hurts. Want to take a walk and talk?","best":true},{"text":"It's just one test, get over it."}],"relearn":"Validating the hurt and offering a tool comforts; dismissing doesn't."},
  {"id":"mm-1240","cat":"mind-care-toolkit","type":"role-play","persona":"any","source":"voice / ask & route","hook":"You need a break but feel guilty. Say it out loud.","setup":"You've worked for hours and your mind is fried. What do you say?","yourLine":[{"text":"I need a short break to rest my mind, then I'll go on.","best":true},{"text":"I'll just push through even though I'm fried."}],"relearn":"Asking for a rest break is mind-care, not laziness."},
  {"id":"mm-1241","cat":"mind-care-toolkit","type":"role-play","persona":"Asha","source":"voice / ask & route","hook":"Asha asks how you'd guide a friend to a tool.","setup":"Your friend feels panicky in the corridor. What do you say?","yourLine":[{"text":"Press your feet down and breathe slow with me; it'll pass.","best":true},{"text":"Stop panicking, everyone's looking."}],"relearn":"Walking a friend through grounding helps a panic wave pass."},
  {"id":"mm-1242","cat":"mind-care-toolkit","type":"role-play","persona":"any","source":"voice / ask & route","hook":"A friend says coping tools are 'cringe'. Say your line.","setup":"They laugh at breathing exercises. What do you say?","yourLine":[{"text":"They actually work for me, athletes use them too.","best":true},{"text":"Yeah, you're right, they're silly."}],"relearn":"Standing up for tools that work models that coping is strength."},
  {"id":"mm-1243","cat":"mind-care-toolkit","type":"role-play","persona":"Aarav","source":"voice / ask & route","hook":"Aarav wants to vent without anyone judging him.","setup":"You're carrying a lot and need to let it out. What do you say?","yourLine":[{"text":"Can I just talk for a bit? I won't be okay if I keep it in.","best":true},{"text":"I've got it handled, I don't need anyone."}],"relearn":"Asking to talk it out beats keeping a heavy feeling inside."},
  {"id":"mm-1244","cat":"mind-care-toolkit","type":"role-play","persona":"any","source":"voice / ask & route","hook":"You want to swap a harsh thought for a kind one, out loud.","setup":"You catch yourself thinking 'I'm useless'. What do you say instead?","yourLine":[{"text":"I'm struggling right now, and I can try again tomorrow.","best":true},{"text":"I'm useless and I'll never get it."}],"relearn":"Say to yourself what you'd say to a friend: kind, not cruel."},
  {"id":"mm-1260","type":"strike-rewrite","hook":"\"A strong person never feels low or worried.\"","myth":{"un":"A strong person never feels low.","re":"Even the strongest people feel low or worried sometimes.","why":"Feelings happen to everyone; they're not a sign of weakness."},"relearn":"Even strong, calm people feel low sometimes; it's human.","persona":"Aarav","source":"de-stigmatise","cat":"mind-matters-too"},
  {"id":"mm-1261","type":"strike-rewrite","hook":"\"Boys shouldn't talk about feelings.\"","myth":{"un":"Boys shouldn't talk about feelings.","re":"Everyone, including boys, feels things and can talk about them.","why":"Naming feelings is a strength, not something only girls do."},"relearn":"Talking about feelings is for everyone; it's strength, not weakness.","persona":"Aarav","source":"de-stigmatise (counters 'be a man')","cat":"mind-matters-too"},
  {"id":"mm-1262","type":"strike-rewrite","hook":"\"If you can't see it, like a cut or a cough, it isn't real.\"","myth":{"un":"A feeling isn't real unless you can see it.","re":"Feelings and your mind's health are real even when unseen.","why":"Your mind has health too, just like the body you can see."},"relearn":"Unseen feelings are real; your mind's health counts as much as your body's.","persona":"any","source":"mental health literacy","cat":"mind-matters-too"},
  {"id":"mm-1263","type":"strike-rewrite","hook":"\"Keeping a worry inside makes it go away.\"","myth":{"un":"Keeping a worry inside makes it disappear.","re":"Worries usually ease when you let them out, not when you bottle them.","why":"Bottling up keeps a worry heavy; sharing it lightens the load."},"relearn":"Worries ease when shared; bottling them up keeps them heavy.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1264","type":"strike-rewrite","hook":"\"Resting when you feel low is just being lazy.\"","myth":{"un":"Resting when low is just being lazy.","re":"Rest helps a tired mind recover; it isn't laziness.","why":"A mind needs rest to stay well, the same way a body does."},"relearn":"Rest isn't lazy; your mind needs breaks to stay well.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1265","type":"strike-rewrite","hook":"\"You should be cheerful all the time, or you're ungrateful.\"","myth":{"un":"You must be cheerful all the time.","re":"All feelings are okay; you don't have to fake being fine.","why":"Hiding every hard feeling tires your mind out."},"relearn":"You needn't be happy all the time; honest feelings are okay.","persona":"any","source":"emotional honesty","cat":"mind-matters-too"},
  {"id":"mm-1266","type":"strike-rewrite","hook":"\"A bad mood means the whole day, or you, is ruined.\"","myth":{"un":"A bad mood ruins the whole day.","re":"A mood is one passing moment, not your whole day or self.","why":"Moods rise, peak and pass like weather; they don't define you."},"relearn":"A bad mood passes; it doesn't ruin your day or define you.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1267","type":"strike-rewrite","hook":"\"Worrying about things you can't do is a waste; just stop feeling it.\"","myth":{"un":"You can just switch off a feeling on command.","re":"Feelings can't be forced off, but they do pass if you let them.","why":"Riding a feeling out works better than ordering it to vanish."},"relearn":"Feelings don't switch off on command, but they do pass.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1268","type":"strike-rewrite","hook":"\"People who go to a counsellor must be really broken.\"","myth":{"un":"Seeing a counsellor means you're broken.","re":"Talking to a counsellor is a healthy step, not a sign you're broken.","why":"Asking for support for your mind is sensible, like seeing a doctor."},"relearn":"Talking to a counsellor is sensible care, not a sign you're broken.","persona":"any","source":"de-stigmatise help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1269","type":"strike-rewrite","hook":"\"A calm-looking classmate must have no problems at all.\"","myth":{"un":"Calm-looking people have no problems.","re":"Everyone has ups and downs, even people who look calm.","why":"What you see on the outside doesn't show the whole inside."},"relearn":"Even calm-looking people have hard days; everyone has ups and downs.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1270","type":"strike-rewrite","hook":"\"Sleep is wasted time you could spend studying.\"","myth":{"un":"Sleep is wasted time.","re":"Sleep is when your mind rests and sorts things out; it isn't wasted.","why":"A rested mind learns and copes better than a tired one."},"relearn":"Sleep isn't wasted; a rested mind learns and copes better.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1271","type":"strike-rewrite","hook":"\"If a feeling is uncomfortable, something must be wrong with you.\"","myth":{"un":"Uncomfortable feelings mean something is wrong with you.","re":"Uncomfortable feelings are a normal part of being human.","why":"Hard feelings are signals, not proof you're faulty."},"relearn":"Uncomfortable feelings are normal signals, not proof you're broken.","persona":"Diya","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1272","type":"strike-rewrite","hook":"\"Caring about your mind is something only adults need to do.\"","myth":{"un":"Only adults need to care about their minds.","re":"Children's minds need care too, at every age.","why":"Looking after your mind young builds habits that help for life."},"relearn":"Your mind needs care at every age, not just when you're grown.","persona":"any","source":"mental health literacy","cat":"mind-matters-too"},
  {"id":"mm-1273","type":"strike-rewrite","hook":"\"Feeling many things at once means you're confused or odd.\"","myth":{"un":"Feeling mixed-up feelings means something's wrong.","re":"Feeling two things at once, like happy and nervous, is normal.","why":"Minds often hold mixed feelings; it doesn't mean you're confused."},"relearn":"Mixed feelings, like happy and nervous together, are completely normal.","persona":"any","source":"emotional literacy","cat":"mind-matters-too"},
  {"id":"mm-1274","type":"strike-rewrite","hook":"\"You should be able to handle everything on your own.\"","myth":{"un":"You must handle everything alone.","re":"Everyone needs support sometimes; you don't have to carry it alone.","why":"Leaning on a trusted person is what minds are meant to do."},"relearn":"You don't have to carry everything alone; everyone needs support sometimes.","persona":"any","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1275","type":"strike-rewrite","hook":"\"Big feelings are dangerous and should scare you.\"","myth":{"un":"Big feelings are dangerous.","re":"Big feelings are intense but safe; they rise and then settle.","why":"A strong feeling is like a big wave that passes, not a threat."},"relearn":"Big feelings are intense but safe; they rise and settle, like waves.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1276","type":"strike-rewrite","hook":"\"A mind can't get tired the way a body can.\"","myth":{"un":"Minds never get tired.","re":"Minds get tired too and need rest, just like bodies.","why":"After a long, hard day your mind needs a break to recover."},"relearn":"Minds get tired and need rest, just like bodies do.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1277","type":"strike-rewrite","hook":"\"Talking about a problem just makes it bigger.\"","myth":{"un":"Talking about a problem makes it bigger.","re":"Talking it through usually makes a problem feel smaller and clearer.","why":"Sharing a worry with someone you trust often eases its weight."},"relearn":"Talking a problem through usually makes it feel smaller, not bigger.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1278","type":"reflect","hook":"Lensy: your mind quietly carries every feeling you have all day. Notice it?","prompt":"Take a moment.","options":["Yes","I'll notice it","I hadn't thought about it"],"affirm":"Just noticing your mind is the first act of caring for it.","relearn":"Noticing your mind is the first step in caring for it.","persona":"any","source":"self-awareness","cat":"mind-matters-too"},
  {"id":"mm-1279","type":"reflect","hook":"Lensy: think of a hard feeling you had last week. Is it still as strong now?","prompt":"What do you notice?","options":["It faded","Mostly gone","A little still there"],"affirm":"Most hard feelings rise, peak and pass; yours did too.","relearn":"Hard feelings rise, peak and pass; they don't stay forever.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1280","type":"reflect","hook":"Lensy: name one small thing that helps when your mind feels heavy.","prompt":"What's yours?","options":["A walk","Talking to someone","Music","Some quiet time"],"affirm":"Knowing what steadies you is a tool you can reach for any time.","relearn":"Knowing what steadies you is a mind-care tool you keep.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1281","type":"reflect","hook":"Lensy: it's okay to not feel okay sometimes. Does hearing that help?","prompt":"What do you think?","options":["Yes","It's a relief","Good to hear"],"affirm":"You don't have to fake being fine; all feelings are okay.","relearn":"You don't have to fake being fine; all feelings are okay.","persona":"any","source":"emotional honesty","cat":"mind-matters-too"},
  {"id":"mm-1282","type":"reflect","hook":"Asha: when's the last time you let yourself just rest, doing nothing?","prompt":"Think back.","options":["Recently","Been a while","Not sure I do"],"affirm":"Rest isn't lazy; your mind needs breaks to stay well.","relearn":"Rest is mind-care, not laziness.","persona":"Asha","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1283","type":"reflect","hook":"Lensy: your body and mind are a team. Which one needs a little care today?","prompt":"Check in.","options":["My body","My mind","Both","Not sure"],"affirm":"Body and mind work together; caring for either helps you.","relearn":"Body and mind work together and both deserve care.","persona":"Rohit","source":"mental health literacy","cat":"mind-matters-too"},
  {"id":"mm-1284","type":"reflect","hook":"Lensy: everyone you pass today is carrying something you can't see. Does that change how you see them?","prompt":"What do you think?","options":["A bit","Yes","I'll be kinder"],"affirm":"Everyone has ups and downs; a little kindness goes far.","relearn":"Everyone carries unseen ups and downs; kindness helps.","persona":"any","source":"empathy","cat":"mind-matters-too"},
  {"id":"mm-1285","type":"reflect","hook":"Lensy: if a feeling could talk, what might today's feeling be trying to tell you?","prompt":"Listen in.","options":["I'm tired","Something matters","I need a break","Not sure yet"],"affirm":"Feelings carry useful messages worth listening to.","relearn":"Feelings carry messages worth listening to.","persona":"any","source":"emotional literacy","cat":"mind-matters-too"},
  {"id":"mm-1286","type":"reflect","hook":"Lensy: is your mind allowed to have an 'off' day, the way a body can feel under the weather?","prompt":"What do you think?","options":["Yes","Of course","I'll allow it"],"affirm":"Your mind can have off days too; that's normal, not a fault.","relearn":"Minds have off days too; that's normal, not a fault.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1287","type":"reflect","hook":"Asha: which feels truer to you, that struggling is shameful, or that it's just human?","prompt":"What do you think?","options":["Just human","It's human","Everyone struggles"],"affirm":"Struggling is human; there's nothing shameful about it.","relearn":"Struggling is human and never shameful.","persona":"Asha","source":"de-stigmatise","cat":"mind-matters-too"},
  {"id":"mm-1288","type":"reflect","hook":"Lensy: picture talking to yourself the way you'd talk to a good friend. How would that sound?","prompt":"Imagine it.","options":["Kinder","Gentler","More patient"],"affirm":"Talking to yourself like a friend is real kindness to your mind.","relearn":"Talk to yourself as kindly as you'd talk to a friend.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1289","type":"reflect","hook":"Lensy: would it be okay to tell someone you trust when your mind feels heavy?","prompt":"What do you think?","options":["Yes","Of course","I could try"],"affirm":"Telling a trusted person is brave; you don't carry it alone.","relearn":"Telling a trusted adult or Childline 1098 means you're never alone.","persona":"any","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1290","type":"reflect","hook":"Lensy: think of one thing that genuinely lifts your mood. Could you do a little of it today?","prompt":"What is it?","options":["Play","A friend","Music","Drawing"],"affirm":"Doing something you enjoy genuinely lifts a low mood.","relearn":"Doing something you enjoy genuinely lifts a low mood.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1291","type":"reflect","hook":"Diya: comparing yourself to others can wear your mind down. Is your path allowed to be your own?","prompt":"What do you think?","options":["Yes","It's mine","I'll try to remember"],"affirm":"Your path is your own; comparison rarely tells the true story.","relearn":"Your path is your own; comparison isn't the full story.","persona":"Diya","source":"comparison / mind-care","cat":"mind-matters-too"},
  {"id":"mm-1292","type":"sort","hook":"Sort: a mind-care move, or a body-care move?","items":[{"id":"a","text":"Talking about a worry"},{"id":"b","text":"Drinking water"},{"id":"c","text":"Resting a tired mind"},{"id":"d","text":"Eating a good meal"},{"id":"e","text":"Naming a feeling"},{"id":"f","text":"Stretching sore legs"}],"bins":[{"id":"mind","label":"Mind care","valence":"pos"},{"id":"body","label":"Body care","valence":"neutral"}],"key":{"a":"mind","b":"body","c":"mind","d":"body","e":"mind","f":"body"},"relearn":"Both mind and body need care; talking and resting care for the mind.","persona":"Rohit","source":"mental health literacy","cat":"mind-matters-too"},
  {"id":"mm-1293","type":"sort","hook":"Sort: which thoughts are kind to your mind, and which are harsh?","items":[{"id":"a","text":"I did my best today"},{"id":"b","text":"I'm useless"},{"id":"c","text":"I can try again"},{"id":"d","text":"Everyone's better than me"},{"id":"e","text":"It's okay to rest"},{"id":"f","text":"I should be perfect"}],"bins":[{"id":"kind","label":"Kind to my mind","valence":"pos"},{"id":"harsh","label":"Harsh","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Kind self-talk helps you grow more than harsh self-talk does.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1294","type":"sort","hook":"Sort: passing feeling, or a fact about you forever?","items":[{"id":"a","text":"I feel nervous today"},{"id":"b","text":"I'm a bad person"},{"id":"c","text":"This is hard right now"},{"id":"d","text":"I'll always fail"},{"id":"e","text":"I'm sad this evening"},{"id":"f","text":"Nobody could ever like me"}],"bins":[{"id":"passing","label":"A passing feeling","valence":"pos"},{"id":"notrue","label":"Not a fact","valence":"neg"}],"key":{"a":"passing","b":"notrue","c":"passing","d":"notrue","e":"passing","f":"notrue"},"relearn":"Feelings pass; 'always' and 'never' thoughts aren't facts about you.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1295","type":"sort","hook":"Sort: does this help a heavy mind, or weigh it down more?","items":[{"id":"a","text":"Taking a short break"},{"id":"b","text":"Calling yourself names"},{"id":"c","text":"Naming the feeling"},{"id":"d","text":"Hiding it from everyone"},{"id":"e","text":"A few slow breaths"},{"id":"f","text":"Skipping sleep to worry"}],"bins":[{"id":"lifts","label":"Lifts the weight","valence":"pos"},{"id":"weighs","label":"Weighs it down","valence":"neg"}],"key":{"a":"lifts","b":"weighs","c":"lifts","d":"weighs","e":"lifts","f":"weighs"},"relearn":"Breaks, naming feelings and slow breaths lift a heavy mind; hiding and harshness weigh it down.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1296","type":"sort","hook":"Sort: a true thing about minds, or a myth?","items":[{"id":"a","text":"Everyone's mind has ups and downs"},{"id":"b","text":"Strong people never feel low"},{"id":"c","text":"Feelings carry useful messages"},{"id":"d","text":"Talking about feelings is weak"},{"id":"e","text":"Rest helps a tired mind"},{"id":"f","text":"A mind can't get tired"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Minds have ups and downs, carry messages and need rest; the rest are myths.","persona":"Aarav","source":"de-stigmatise","cat":"mind-matters-too"},
  {"id":"mm-1297","type":"sort","hook":"Sort: which of these is okay to feel?","items":[{"id":"a","text":"Sad"},{"id":"b","text":"Nervous"},{"id":"c","text":"Angry"},{"id":"d","text":"Happy"},{"id":"e","text":"Jealous"},{"id":"f","text":"Worried"}],"bins":[{"id":"ok","label":"Okay to feel","valence":"pos"}],"key":{"a":"ok","b":"ok","c":"ok","d":"ok","e":"ok","f":"ok"},"relearn":"Every feeling is okay to feel; none make you 'bad'.","persona":"any","source":"emotional honesty","cat":"mind-matters-too"},
  {"id":"mm-1298","type":"sort","hook":"Sort: speak it up, or quietly let it pass?","items":[{"id":"a","text":"A heavy feeling that won't lift"},{"id":"b","text":"A small flicker of boredom"},{"id":"c","text":"A worry that keeps you awake"},{"id":"d","text":"A passing pang of nerves"},{"id":"e","text":"A low mood lasting days"},{"id":"f","text":"A moment of mild annoyance"}],"bins":[{"id":"speak","label":"Tell someone","valence":"tell"},{"id":"pass","label":"Let it pass","valence":"pos"}],"key":{"a":"speak","b":"pass","c":"speak","d":"pass","e":"speak","f":"pass"},"relearn":"Small feelings can pass on their own; big or lasting ones are worth telling a trusted adult.","persona":"any","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1299","type":"sort","hook":"Sort: a sign your mind needs a little extra care today?","items":[{"id":"a","text":"Snapping at everyone"},{"id":"b","text":"Feeling rested and calm"},{"id":"c","text":"Can't stop worrying"},{"id":"d","text":"Enjoying your day"},{"id":"e","text":"Tired no matter what"},{"id":"f","text":"Looking forward to things"}],"bins":[{"id":"care","label":"Needs care","valence":"uhoh"},{"id":"steady","label":"Feeling steady","valence":"pos"}],"key":{"a":"care","b":"steady","c":"care","d":"steady","e":"care","f":"steady"},"relearn":"Noticing the signs your mind needs care is the first step to easing them.","persona":"any","source":"self-awareness","cat":"mind-matters-too"},
  {"id":"mm-1300","type":"sort","hook":"Sort: a healthy way to handle a low mood, or not a real tool?","items":[{"id":"a","text":"Going for a walk"},{"id":"b","text":"Bottling it all up"},{"id":"c","text":"Talking to someone you trust"},{"id":"d","text":"Pretending you're fine"},{"id":"e","text":"Doing something you enjoy"},{"id":"f","text":"Skipping rest entirely"}],"bins":[{"id":"healthy","label":"Healthy tool","valence":"pos"},{"id":"not","label":"Not a tool","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"},"relearn":"Walking, talking and enjoyment are real tools; bottling up and no rest are not.","persona":"any","source":"coping toolkit","cat":"mind-matters-too"},
  {"id":"mm-1301","type":"sort","hook":"Sort: true or false about asking for help?","items":[{"id":"a","text":"Asking for help is brave"},{"id":"b","text":"Asking for help is shameful"},{"id":"c","text":"A trusted adult can listen"},{"id":"d","text":"You must handle it alone"},{"id":"e","text":"Childline 1098 is always there"},{"id":"f","text":"Strong people never ask"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Asking for help is brave; a trusted adult or Childline 1098 is always there.","persona":"Asha","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1302","type":"sort","hook":"Sort: kind to a friend who's struggling, or unkind?","items":[{"id":"a","text":"\"That sounds really hard\""},{"id":"b","text":"\"Just get over it\""},{"id":"c","text":"\"I'm here for you\""},{"id":"d","text":"\"Stop being dramatic\""},{"id":"e","text":"\"Want to talk about it?\""},{"id":"f","text":"\"Everyone has it worse\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Validating a friend's hurt is kind; dismissing it is not.","persona":"any","source":"peer support","cat":"mind-matters-too"},
  {"id":"mm-1303","type":"sort","hook":"Sort: helps your mind rest, or keeps it wound up?","items":[{"id":"a","text":"Winding down before bed"},{"id":"b","text":"Scrolling late into the night"},{"id":"c","text":"Some quiet time alone"},{"id":"d","text":"Replaying a worry on loop"},{"id":"e","text":"A slow, calm breath"},{"id":"f","text":"Cramming with no breaks"}],"bins":[{"id":"rests","label":"Rests the mind","valence":"pos"},{"id":"winds","label":"Winds it up","valence":"neg"}],"key":{"a":"rests","b":"winds","c":"rests","d":"winds","e":"rests","f":"winds"},"relearn":"Winding down, quiet and slow breaths rest the mind; late scrolling and cramming wind it up.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1304","type":"sort","hook":"Sort: which belong in a kind inner voice?","items":[{"id":"a","text":"\"Mistakes help me learn\""},{"id":"b","text":"\"I ruin everything\""},{"id":"c","text":"\"I'm doing my best\""},{"id":"d","text":"\"I should be perfect\""},{"id":"e","text":"\"It's okay to rest\""},{"id":"f","text":"\"I'm not allowed to fail\""}],"bins":[{"id":"kind","label":"Kind voice","valence":"pos"},{"id":"harsh","label":"Harsh voice","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"A kind inner voice allows mistakes, rest and 'best'; a harsh one demands perfection.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1305","type":"sort","hook":"Sort: a feeling, or a fact?","items":[{"id":"a","text":"I feel worried"},{"id":"b","text":"The exam is on Monday"},{"id":"c","text":"I feel left out"},{"id":"d","text":"The bus comes at eight"},{"id":"e","text":"I feel hopeful"},{"id":"f","text":"It rained today"}],"bins":[{"id":"feeling","label":"A feeling","valence":"pos"},{"id":"fact","label":"A fact","valence":"neutral"}],"key":{"a":"feeling","b":"fact","c":"feeling","d":"fact","e":"feeling","f":"fact"},"relearn":"Telling a feeling from a fact helps you handle both clearly.","persona":"any","source":"emotional literacy","cat":"mind-matters-too"},
  {"id":"mm-1306","type":"match","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"Only the body gets unwell","right":"Your mind has health too"},{"left":"Big feelings last forever","right":"Feelings rise, peak and pass"},{"left":"Asking for help is shameful","right":"Reaching out is brave"},{"left":"Stress means you're weak","right":"Stress is a normal response"},{"left":"You must be happy always","right":"All feelings are okay"}],"relearn":"Each stigma myth has a kinder, truer fact that replaces it.","persona":"any","source":"mental health literacy","cat":"mind-matters-too"},
  {"id":"mm-1307","type":"match","hook":"Match the feeling to a healthy thing that helps it.","pairs":[{"left":"Worried","right":"Slow breaths"},{"left":"Lonely","right":"Reach out to a friend"},{"left":"Angry","right":"Move your body"},{"left":"Tired","right":"Rest"},{"left":"Low","right":"Do something you enjoy"}],"relearn":"Different feelings have different healthy tools that help.","persona":"any","source":"coping toolkit","cat":"mind-matters-too"},
  {"id":"mm-1308","type":"match","hook":"Match each part of you to what keeps it well.","pairs":[{"left":"Body","right":"Sleep and movement"},{"left":"Mind","right":"Talking and calm"},{"left":"Mood","right":"Things you enjoy"},{"left":"Worries","right":"Sharing them"},{"left":"Tiredness","right":"A real break"}],"relearn":"Body and mind both have ways to stay well.","persona":"Rohit","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1309","type":"match","hook":"Match the kind helper to the moment.","pairs":[{"left":"A heavy, lasting feeling","right":"A trusted adult"},{"left":"A school worry","right":"A teacher you like"},{"left":"A home worry","right":"A caring parent"},{"left":"A friend who's hurting","right":"Sit with them"},{"left":"Any big feeling","right":"Childline 1098"}],"relearn":"Matching a worry to the right helper is a skill you can learn.","persona":"Asha","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1310","type":"match","hook":"Match the harsh thought to a kinder rewrite.","pairs":[{"left":"\"I'm useless\"","right":"\"I'm still learning\""},{"left":"\"I always fail\"","right":"\"I can try again\""},{"left":"\"I must be perfect\"","right":"\"My best is enough\""},{"left":"\"Resting is lazy\"","right":"\"Rest helps me\""},{"left":"\"Nobody likes me\"","right":"\"Some people care\""}],"relearn":"A harsh thought can be rewritten into a kind, truer one.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1311","type":"match","hook":"Match the feeling word to what it often signals.","pairs":[{"left":"Nervous","right":"Something matters"},{"left":"Hurt","right":"I've been let down"},{"left":"Restless","right":"I need to move"},{"left":"Heavy","right":"I could use support"},{"left":"Calm","right":"I feel safe"}],"relearn":"Feelings are signals carrying useful messages.","persona":"any","source":"emotional literacy","cat":"mind-matters-too"},
  {"id":"mm-1312","type":"match","hook":"Match the mind-care move to what it does.","pairs":[{"left":"Slow breathing","right":"Calms the body"},{"left":"Naming a feeling","right":"Makes it less scary"},{"left":"Talking to someone","right":"Lightens the load"},{"left":"A short break","right":"Rests the mind"},{"left":"Enjoyable activity","right":"Lifts the mood"}],"relearn":"Each healthy tool does a real job for your mind.","persona":"any","source":"coping toolkit","cat":"mind-matters-too"},
  {"id":"mm-1313","type":"match","hook":"Match the moment to the kind self-talk that fits.","pairs":[{"left":"After a mistake","right":"\"I can learn from this\""},{"left":"On a tired day","right":"\"It's okay to rest\""},{"left":"After a setback","right":"\"I'll be okay\""},{"left":"When comparing","right":"\"My path is my own\""},{"left":"When low","right":"\"This feeling will pass\""}],"relearn":"Kind self-talk fits every hard moment better than harshness.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1314","type":"match","hook":"Match what's true of a cared-for mind.","pairs":[{"left":"Gets enough rest","right":"Feels steadier"},{"left":"Talks about feelings","right":"Carries less alone"},{"left":"Takes breaks","right":"Stays well"},{"left":"Allows all feelings","right":"Doesn't fake fine"},{"left":"Asks for help","right":"Grows stronger"}],"relearn":"A cared-for mind rests, talks, breaks, allows feelings and asks for help.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1315","type":"branch","hook":"Your mind feels heavy and grey for no clear reason today.","options":[{"text":"Notice it, be gentle, and do one small kind thing for yourself","consequence":"The heaviness eases a little and feels less alone.","best":true,"outcome":"steadier"},{"text":"Tell yourself off for feeling this way","consequence":"A grey day is normal; being gentle helps more than blame."}],"debrief":"A heavy mind eases faster with gentleness than with blame.","relearn":"Treat a heavy mind with kindness, not blame.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1316","type":"branch","hook":"A hard feeling hits and your first thought is 'this will never end.'","options":[{"text":"Remind yourself feelings pass, and wait it out gently","consequence":"The feeling peaks, then slowly settles, just as you reminded yourself.","best":true,"outcome":"grounded"},{"text":"Believe it will last forever","consequence":"Feelings rise, peak and pass; this one does too."}],"debrief":"No feeling is permanent; remembering that helps it pass.","relearn":"Hard feelings rise, peak and pass, like weather.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1317","type":"branch","hook":"Your friend says they feel low and 'a bit broken' inside.","options":[{"text":"Tell them feeling low is human and you're glad they shared","consequence":"They feel understood and a little lighter.","best":true,"outcome":"kind"},{"text":"Tell them to just snap out of it","consequence":"Feeling low is human; understanding helps far more than 'snap out of it'."}],"debrief":"Feeling low is human; understanding helps more than 'snap out of it'.","relearn":"Validate a friend's low mood; it's human, not broken.","persona":"any","source":"peer support","cat":"mind-matters-too"},
  {"id":"mm-1318","type":"branch","hook":"You feel embarrassed that you've been crying about something.","options":[{"text":"Accept that crying is a normal release and let yourself feel it","consequence":"The feeling moves through and you feel calmer after.","best":true,"outcome":"released"},{"text":"Push the feeling down and force a smile","consequence":"Crying is a healthy release; pushing it down only makes it heavier."}],"debrief":"Crying is a normal, healthy release, not something to hide.","relearn":"Crying is a healthy release; you don't have to hide it.","persona":"any","source":"emotional honesty","cat":"mind-matters-too"},
  {"id":"mm-1319","type":"branch","hook":"After a tiring day your mind just wants to stop, but a voice says 'keep going.'","options":[{"text":"Give your mind the rest it's asking for","consequence":"A short rest leaves you steadier and clearer.","best":true,"outcome":"rested"},{"text":"Push on with no break at all","consequence":"A mind needs rest like a body; a break helps more than pushing through."}],"debrief":"Rest isn't lazy; your mind needs breaks to stay well.","relearn":"Rest a tired mind; breaks help more than pushing through.","persona":"Aarav","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1320","type":"branch","hook":"Your mind has felt heavy for many days, not just one.","options":[{"text":"Tell a trusted adult about it","consequence":"You don't carry the heaviness alone.","best":true,"outcome":"supported"},{"text":"Wait and hope it just goes","consequence":"A lasting heavy feeling is a signal to tell someone, not push through alone."}],"debrief":"Big or lasting heavy feelings are a signal to ask for help.","relearn":"For lasting feelings, tell a trusted adult or call Childline 1098 (linked with 112).","persona":"Rohit","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1321","type":"branch","hook":"A classmate seems calm and happy, so you assume they have no worries.","options":[{"text":"Remember everyone has unseen ups and downs","consequence":"You treat them, and yourself, more kindly.","best":true,"outcome":"understanding"},{"text":"Decide they have it easy and you're the only one struggling","consequence":"What you see outside doesn't show the inside; everyone has hard days."}],"debrief":"Even calm-looking people have hard days.","relearn":"Calm-looking people have ups and downs too.","persona":"any","source":"normalising","cat":"mind-matters-too"},
  {"id":"mm-1322","type":"branch","hook":"Your inner voice is being harsh: 'you're hopeless, you got it wrong again.'","options":[{"text":"Rewrite it kindly: 'that was hard, I'm still learning'","consequence":"The kinder voice helps you keep going instead of giving up.","best":true},{"text":"Believe the harsh voice and shrink","consequence":"A harsh inner voice is a thought to rewrite kindly, not a truth about you."}],"debrief":"A harsh inner voice is a thought to rewrite kindly, not a truth.","relearn":"Rewrite a harsh inner voice kindly.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1323","type":"build","hook":"Build a 'my mind matters' promise to yourself. Pick the kind ones.","prompt":"Choose what belongs in a promise to your mind.","pieces":["Rest when I'm tired","Talk when it's heavy","Be kind to myself","Ask for help when I need it"],"mode":"assemble","key":["Rest when I'm tired","Talk when it's heavy","Be kind to myself","Ask for help when I need it"],"relearn":"A promise to your mind: rest, talk, be kind, and ask for help.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1324","type":"build","hook":"Build the steps to handle a hard feeling. Put them in order.","prompt":"Order the steps for riding out a hard feeling.","pieces":["Name the feeling","Take slow breaths","Let it pass","Be kind to yourself"],"mode":"sequence","key":["Name the feeling","Take slow breaths","Let it pass","Be kind to yourself"],"relearn":"Ride out a hard feeling: name it, breathe, let it pass, be kind.","persona":"any","source":"coping toolkit","cat":"mind-matters-too"},
  {"id":"mm-1325","type":"build","hook":"Build a 'cared-for mind' day. Pick the healthy habits.","prompt":"Choose habits that keep a mind well.","pieces":["Enough sleep","Talk about feelings","Take breaks","Do something you enjoy"],"mode":"assemble","key":["Enough sleep","Talk about feelings","Take breaks","Do something you enjoy"],"relearn":"A cared-for mind gets sleep, talks, breaks and enjoyment.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1326","type":"build","hook":"Build the steps to be kinder to your mind after a mistake. In order.","prompt":"Order the kind steps after a mistake.","pieces":["Notice the harsh thought","Pause","Say it kindly instead","Try again"],"mode":"sequence","key":["Notice the harsh thought","Pause","Say it kindly instead","Try again"],"relearn":"After a mistake: notice the harsh thought, pause, be kind, try again.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1327","type":"build","hook":"Build a list of people you could turn to. Pick trusted helpers.","prompt":"Choose people who listen and help.","pieces":["A parent you trust","A teacher you like","A near-peer like Asha","Childline 1098"],"mode":"assemble","key":["A parent you trust","A teacher you like","A near-peer like Asha","Childline 1098"],"relearn":"Trusted helpers: a parent, a teacher, a near-peer, or Childline 1098.","persona":"Asha","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1328","type":"build","hook":"Build a wind-down for a wound-up mind. Put the calm steps in order.","prompt":"Order the steps to wind down your mind.","pieces":["Put the screen away","Slow your breathing","Do something gentle","Let your mind rest"],"mode":"sequence","key":["Put the screen away","Slow your breathing","Do something gentle","Let your mind rest"],"relearn":"Wind down a busy mind: screen away, slow breaths, something gentle, rest.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1329","type":"build","hook":"Build a kit of things that lift your mood. Pick the real mood-lifters.","prompt":"Choose what genuinely lifts a low mood.","pieces":["Move your body","Time with people who care","Something you enjoy","A little fresh air"],"mode":"assemble","key":["Move your body","Time with people who care","Something you enjoy","A little fresh air"],"relearn":"Movement, caring company, enjoyment and fresh air genuinely lift a mood.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1330","type":"build","hook":"Build the steps to check in with your own mind. In order.","prompt":"Order the steps for a mind check-in.","pieces":["Pause for a moment","Notice how you feel","Name the feeling","Choose one kind thing"],"mode":"sequence","key":["Pause for a moment","Notice how you feel","Name the feeling","Choose one kind thing"],"relearn":"Check in with your mind: pause, notice, name it, choose one kind thing.","persona":"any","source":"self-awareness","cat":"mind-matters-too"},
  {"id":"mm-1331","type":"role-play","hook":"A friend laughs that 'only weak people get stressed.'","setup":"Speak up for the truth. Say:","yourLine":[{"text":"\"Stress is normal; everyone feels it. It doesn't mean you're weak.\"","best":true},{"text":"\"Yeah, I guess only weak people feel it.\""}],"relearn":"Stress is a normal response everyone feels; it isn't weakness.","persona":"Aarav","source":"de-stigmatise","cat":"mind-matters-too"},
  {"id":"mm-1332","type":"role-play","hook":"Your mind feels heavy and a trusted adult asks how you are.","setup":"Be honest with them. Say:","yourLine":[{"text":"\"Honestly, I've been feeling low. Can we talk?\"","best":true},{"text":"\"I'm fine,\" while feeling far from it."}],"relearn":"Saying 'I'm not okay, can we talk?' is a brave, healthy move.","persona":"any","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1333","type":"role-play","hook":"A younger cousin says they feel silly for feeling sad.","setup":"Reassure them. Say:","yourLine":[{"text":"\"Feeling sad isn't silly; it's human, and it passes.\"","best":true},{"text":"\"Don't be a baby about it.\""}],"relearn":"All feelings are okay and human; reassuring beats dismissing.","persona":"any","source":"peer support","cat":"mind-matters-too"},
  {"id":"mm-1334","type":"role-play","hook":"You catch yourself thinking 'I'm useless' after one mistake.","setup":"Speak to yourself like a friend. Say:","yourLine":[{"text":"\"That was hard. I'm still learning, and I can try again.\"","best":true},{"text":"\"See? I'm just useless.\""}],"relearn":"Talk to yourself as kindly as you'd talk to a friend.","persona":"any","source":"self-compassion","cat":"mind-matters-too"},
  {"id":"mm-1335","type":"role-play","hook":"A classmate brags they 'never need anyone's help.'","setup":"Offer the kinder truth. Say:","yourLine":[{"text":"\"Asking for help is brave, not weak. Everyone needs it sometimes.\"","best":true},{"text":"\"Right, needing help means you're weak.\""}],"relearn":"Asking for help is brave and a sign of strength.","persona":"Asha","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1336","type":"role-play","hook":"Your mind is asking for rest, but you feel guilty stopping.","setup":"Give yourself permission. Say:","yourLine":[{"text":"\"It's okay to rest. My mind needs a break to stay well.\"","best":true},{"text":"\"Resting now just means I'm lazy.\""}],"relearn":"Rest isn't lazy; your mind needs breaks to stay well.","persona":"any","source":"mind-care","cat":"mind-matters-too"},
  {"id":"mm-1337","type":"role-play","hook":"A friend admits they've been feeling low for a while.","setup":"Support them gently. Say:","yourLine":[{"text":"\"Thank you for telling me. A trusted adult or Childline 1098 can help too.\"","best":true},{"text":"\"You'll be fine, stop overthinking.\""}],"relearn":"For lasting low feelings, a trusted adult or Childline 1098 can help.","persona":"any","source":"help-seeking","cat":"mind-matters-too"},
  {"id":"mm-1338","type":"role-play","hook":"Someone says feeling many things at once makes you 'a bit crazy.'","setup":"Set it straight. Say:","yourLine":[{"text":"\"Feeling mixed-up feelings is completely normal, not crazy.\"","best":true},{"text":"\"Maybe you're right, that is weird.\""}],"relearn":"Feeling two things at once is normal; it doesn't make you 'crazy'.","persona":"any","source":"emotional literacy","cat":"mind-matters-too"},
  {"id":"mm-1350","cat":"stress-and-pressure","type":"branch","hook":"Back-to-back tuition and homework leave you no time to breathe.","options":[{"text":"Tell a parent the load is too much and plan it together","consequence":"You share the weight and the week feels lighter.","outcome":"supported","best":true},{"text":"Skip sleep to fit it all in","consequence":"A calm talk and a real plan help more than cramming all night."}],"debrief":"When the load is too heavy, naming it and planning together eases the pressure.","relearn":"If the load is too much, tell a caring adult and plan it together.","persona":"Rohit","source":"stress / overload"},
  {"id":"mm-1351","cat":"stress-and-pressure","type":"branch","hook":"Results come out tomorrow and your thoughts are racing.","options":[{"text":"Breathe slowly and remind yourself one result isn't your worth","consequence":"The racing thoughts settle a little.","outcome":"grounded","best":true},{"text":"Imagine every worst outcome on a loop","consequence":"A slow breath and a kinder thought calm racing what-ifs."}],"debrief":"A result measures one test, not you; breathing slows the worry.","relearn":"One result isn't your worth; slow breaths calm racing thoughts.","persona":"any","source":"exam pressure / India"},
  {"id":"mm-1352","cat":"stress-and-pressure","type":"branch","hook":"Relatives keep comparing you to your topper cousin and it stings.","options":[{"text":"Remind yourself your path is your own and let their words pass","consequence":"You feel steadier and less small.","outcome":"grounded","best":true},{"text":"Decide you'll never be good enough","consequence":"Your path is your own; one comparison isn't the full story."}],"debrief":"Comparison rarely tells the true story; your own progress is what counts.","relearn":"Your path is your own; don't measure it by a cousin's marks.","persona":"Diya","source":"comparison / family"},
  {"id":"mm-1353","cat":"stress-and-pressure","type":"branch","hook":"You keep putting off a big project and the dread keeps growing.","options":[{"text":"Open the book and do just five minutes to start","consequence":"Starting small melts most of the dread.","outcome":"unstuck","best":true},{"text":"Keep avoiding it and feel worse","consequence":"A tiny five-minute start beats the dread of avoiding."}],"debrief":"Dread grows while you avoid; one small start shrinks it.","relearn":"Beat task-dread by starting with just five small minutes.","persona":"any","source":"stress / procrastination"},
  {"id":"mm-1354","cat":"stress-and-pressure","type":"branch","hook":"It's your turn to speak at assembly and your hands are shaking.","options":[{"text":"Take three slow breaths and remember nerves are normal","consequence":"Your body steadies enough to begin.","outcome":"coped","best":true},{"text":"Tell yourself you'll definitely mess up","consequence":"Slow breaths steady you; some nerves are just your body powering up."}],"debrief":"Nerves before speaking are normal; slow breathing steadies you.","relearn":"Three slow breaths steady you; pre-stage nerves are normal.","persona":"any","source":"performance nerves"},
  {"id":"mm-1355","cat":"stress-and-pressure","type":"branch","hook":"Your timetable is so packed you feel like a wound-up spring.","options":[{"text":"Block in one real break to rest and reset","consequence":"A short break lets you keep going steadier.","outcome":"balanced","best":true},{"text":"Cut every break to do even more","consequence":"A planned break helps a packed day more than skipping rest."}],"debrief":"Breaks aren't wasted time; they keep a stressed mind working.","relearn":"Build a real break into a packed day; rest keeps you going.","persona":"any","source":"stress / rest"},
  {"id":"mm-1356","cat":"stress-and-pressure","type":"branch","hook":"A surprise test is announced and panic floods in.","options":[{"text":"Pause, breathe, and recall what you do already know","consequence":"The panic eases and your memory clears.","outcome":"coped","best":true},{"text":"Freeze and decide it's hopeless","consequence":"A breath clears the fog so you can use what you know."}],"debrief":"Panic blanks the mind; a breath brings back what you know.","relearn":"Pause and breathe; panic fades and what you know returns.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-1357","cat":"stress-and-pressure","type":"branch","hook":"Everyone's exam-prep posts online make you feel hopelessly behind.","options":[{"text":"Close the app and focus on your own next small step","consequence":"You feel calmer and back in control.","outcome":"grounded","best":true},{"text":"Scroll and feel worse for an hour","consequence":"Feeds show highlight reels; your own next step is what counts."}],"debrief":"Online study-flexing is a highlight reel, not the whole truth.","relearn":"Close the comparing app; focus on your own next small step.","persona":"Aarav","source":"comparison / online"},
  {"id":"mm-1358","cat":"stress-and-pressure","type":"branch","hook":"You're so stressed you've started skipping meals without noticing.","options":[{"text":"Eat something and tell a trusted adult how stressed you feel","consequence":"Your body and mind both get cared for.","outcome":"supported","best":true},{"text":"Push on and ignore the hunger","consequence":"Eating and telling an adult care for body and mind together."}],"debrief":"Stress can hit your body; food and a trusted adult both help.","relearn":"If stress steals your appetite, eat and tell a trusted adult.","persona":"any","source":"stress / body-mind"},
  {"id":"mm-1359","cat":"stress-and-pressure","type":"branch","hook":"You finished an essay but keep redoing it, never satisfied.","options":[{"text":"Decide it's good enough and let yourself stop","consequence":"You free up calm and energy.","outcome":"balanced","best":true},{"text":"Redo it for hours chasing perfect","consequence":"'Good enough' protects your calm; perfect chasing drains it."}],"debrief":"Chasing perfect fuels stress; 'good enough' is often plenty.","relearn":"Let 'good enough' be enough; perfect-chasing drains you.","persona":"any","source":"perfectionism / stress"},
  {"id":"mm-1360","cat":"stress-and-pressure","type":"branch","hook":"Three deadlines land in the same week and your head spins.","options":[{"text":"List them and tackle the nearest one first","consequence":"The spin slows once you have an order.","outcome":"unstuck","best":true},{"text":"Try to do all three at once","consequence":"One ordered list calms the spin better than juggling all at once."}],"debrief":"A spinning head settles once tasks have an order and a first step.","relearn":"List clashing deadlines and start with the nearest one.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-1361","cat":"stress-and-pressure","type":"branch","hook":"A friend looks crushed by exam stress and doesn't know what to do.","options":[{"text":"Sit with them, breathe together, and suggest one small step","consequence":"They feel less alone and a bit calmer.","outcome":"caring","best":true},{"text":"Tell them to just stop stressing","consequence":"Sitting with them and a small step help more than 'just stop'."}],"debrief":"You can ease a friend's stress by being there and breaking it small.","relearn":"Help a stressed friend by being present and suggesting one small step.","persona":"any","source":"peer support / stress"},
  {"id":"mm-1362","cat":"stress-and-pressure","type":"branch","hook":"A power cut wipes out your study evening and you feel like crying.","options":[{"text":"Accept what you can't control and plan tomorrow calmly","consequence":"You let go of the panic you can't fix.","outcome":"grounded","best":true},{"text":"Spiral about all the lost time","consequence":"Letting go of what you can't control beats spiralling over it."}],"debrief":"Some things are out of your hands; calm planning beats spiralling.","relearn":"Let go of what you can't control; plan the next bit calmly.","persona":"any","source":"stress / control"},
  {"id":"mm-1363","cat":"stress-and-pressure","type":"branch","hook":"Coaching, school and chores leave you snapping at everyone.","options":[{"text":"Notice you're overloaded and ask to drop or share one thing","consequence":"The pressure valve opens a little.","outcome":"supported","best":true},{"text":"Push through and keep snapping","consequence":"Noticing overload and sharing a task eases the short fuse."}],"debrief":"A short fuse can mean overload; sharing the load helps.","relearn":"Snapping can mean overload; ask to share or drop one task.","persona":"Rohit","source":"stress / overload"},
  {"id":"mm-1364","cat":"stress-and-pressure","type":"branch","hook":"Before a big match your stomach is in knots.","options":[{"text":"Shake it out, breathe, and treat the nerves as ready-energy","consequence":"The knots loosen into focus.","outcome":"coped","best":true},{"text":"Decide the knots mean you'll lose","consequence":"Nerves can be ready-energy; breathing turns knots into focus."}],"debrief":"Pre-match nerves are your body getting ready, not a bad sign.","relearn":"Breathe and reframe match-nerves as your body getting ready.","persona":"any","source":"performance nerves"},
  {"id":"mm-1365","cat":"stress-and-pressure","type":"branch","hook":"A group project partner isn't helping and the stress is mounting.","options":[{"text":"Calmly say what you need and split the work clearly","consequence":"The pressure shares out more fairly.","outcome":"resolved","best":true},{"text":"Silently do it all and seethe","consequence":"Speaking up and splitting the work eases the stress better than seething."}],"debrief":"Naming what you need calmly shares the load and the stress.","relearn":"Calmly ask for a fair split instead of carrying it all alone.","persona":"any","source":"stress / assertiveness"},
  {"id":"mm-1366","cat":"stress-and-pressure","type":"branch","hook":"You've been staring at the same page for an hour, nothing going in.","options":[{"text":"Take a short break, move, then return refreshed","consequence":"A reset helps the page finally make sense.","outcome":"unstuck","best":true},{"text":"Force yourself to keep staring","consequence":"A short movement break beats forcing a tired, stuck mind."}],"debrief":"A stuck, tired mind needs a reset more than more staring.","relearn":"When nothing sinks in, take a short movement break, then return.","persona":"any","source":"stress / focus"},
  {"id":"mm-1367","cat":"stress-and-pressure","type":"branch","hook":"A teacher's tough feedback leaves your chest tight all day.","options":[{"text":"Breathe, take the useful part, and let the sting pass","consequence":"You learn from it without carrying the weight.","outcome":"grounded","best":true},{"text":"Replay the criticism on repeat","consequence":"Taking the useful part and letting the sting pass beats replaying it."}],"debrief":"Feedback can sting; take what helps and let the rest pass.","relearn":"Keep the useful part of feedback; let the sting pass.","persona":"any","source":"stress / resilience"},
  {"id":"mm-1368","cat":"stress-and-pressure","type":"branch","hook":"You feel pressure to top the class or you've 'failed'.","options":[{"text":"Set your own fair goal instead of an all-or-nothing one","consequence":"The pressure becomes something you can actually meet.","outcome":"balanced","best":true},{"text":"Tell yourself only first place counts","consequence":"A fair goal eases pressure; all-or-nothing only piles it on."}],"debrief":"All-or-nothing goals fuel stress; a fair goal is reachable.","relearn":"Swap 'top or fail' for a fair goal you can actually meet.","persona":"Diya","source":"exam pressure / India"},
  {"id":"mm-1369","cat":"stress-and-pressure","type":"branch","hook":"Stress is so high you feel frozen, unable to start anything.","options":[{"text":"Name the smallest possible first step and do only that","consequence":"The freeze cracks and you're moving.","outcome":"unstuck","best":true},{"text":"Wait for the freeze to lift on its own","consequence":"The tiniest first step cracks a freeze better than waiting."}],"debrief":"You're never truly stuck; there's always one small first step.","relearn":"You're never stuck; one tiny first step breaks the freeze.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-1370","cat":"stress-and-pressure","type":"branch","hook":"Festival visitors keep asking about your marks and you're tense.","options":[{"text":"Breathe, give a calm short answer, and step away if needed","consequence":"You handle it without the tension taking over.","outcome":"coped","best":true},{"text":"Let every question wind you up tighter","consequence":"A calm short answer and a step away stop the tension taking over."}],"debrief":"You can meet pressure questions calmly and step away to reset.","relearn":"Answer marks-questions calmly and step away to reset if needed.","persona":"any","source":"stress / family"},
  {"id":"mm-1371","cat":"stress-and-pressure","type":"branch","hook":"You feel you must keep going or you'll let your parents down.","options":[{"text":"Tell them honestly you need a rest day to keep going well","consequence":"They understand and you recover.","outcome":"supported","best":true},{"text":"Hide the exhaustion and push on","consequence":"Telling them you need rest invites support; hiding it wears you down."}],"debrief":"Caring adults would rather you rest than burn out in silence.","relearn":"You can tell parents you need a rest day to keep going well.","persona":"Rohit","source":"stress / help-seeking"},
  {"id":"mm-1372","cat":"stress-and-pressure","type":"branch","hook":"Worry about a test is keeping you up, heart pounding.","options":[{"text":"Try slow square breathing to settle your body for sleep","consequence":"Your heart slows and rest comes.","outcome":"rested","best":true},{"text":"Lie there rehearsing every question","consequence":"Slow breathing settles a pounding heart better than rehearsing all night."}],"debrief":"Slow breathing calms a racing body so a stressed mind can rest.","relearn":"Use slow square breathing to settle a pounding heart at night.","persona":"any","source":"stress / sleep"},
  {"id":"mm-1373","cat":"stress-and-pressure","type":"sort","hook":"Sort: a healthy way to ease stress, or a risky 'trick'?","items":[{"id":"a","text":"Slow breathing"},{"id":"b","text":"Bottling it all up"},{"id":"c","text":"A walk outside"},{"id":"d","text":"Numbing out for hours"},{"id":"e","text":"Talking to someone you trust"},{"id":"f","text":"Hiding from everyone for days"}],"bins":[{"id":"healthy","label":"Healthy way","valence":"pos"},{"id":"risky","label":"Not a real tool","valence":"neg"}],"key":{"a":"healthy","b":"risky","c":"healthy","d":"risky","e":"healthy","f":"risky"},"relearn":"Breathing, walking and talking ease stress; bottling up, numbing and hiding never do.","persona":"any","source":"stress management"},
  {"id":"mm-1374","cat":"stress-and-pressure","type":"sort","hook":"Sort: a thought that fuels stress, or one that eases it?","items":[{"id":"a","text":"\"I can take this one step at a time\""},{"id":"b","text":"\"Everyone's doing better than me\""},{"id":"c","text":"\"This feeling will pass\""},{"id":"d","text":"\"I have to be perfect\""},{"id":"e","text":"\"I can ask for help\""},{"id":"f","text":"\"If I fail once, it's over\""}],"bins":[{"id":"eases","label":"Eases stress","valence":"pos"},{"id":"fuels","label":"Fuels stress","valence":"neg"}],"key":{"a":"eases","b":"fuels","c":"eases","d":"fuels","e":"eases","f":"fuels"},"relearn":"'One step', 'this passes' and 'I can ask' ease stress; comparison and perfectionism fuel it.","persona":"any","source":"cognitive / stress"},
  {"id":"mm-1375","cat":"stress-and-pressure","type":"sort","hook":"Sort: a smart first move when overwhelmed, or one that makes it worse?","items":[{"id":"a","text":"Breathe slowly"},{"id":"b","text":"Try to do everything at once"},{"id":"c","text":"Break it into small steps"},{"id":"d","text":"Skip sleep to cram"},{"id":"e","text":"Ask a trusted adult"},{"id":"f","text":"Tell yourself you'll fail"}],"bins":[{"id":"smart","label":"Smart first move","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"smart","b":"worse","c":"smart","d":"worse","e":"smart","f":"worse"},"relearn":"Breathe, break it small and ask for help; doing-it-all, no sleep and self-blame make it worse.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-1376","cat":"stress-and-pressure","type":"sort","hook":"Sort: a body or mind sign of stress, or not a stress sign at all?","items":[{"id":"a","text":"Racing thoughts"},{"id":"b","text":"Feeling extra hungry for fun"},{"id":"c","text":"A clenched jaw"},{"id":"d","text":"Whistling a happy tune"},{"id":"e","text":"Snapping at people"},{"id":"f","text":"Laughing with friends"}],"bins":[{"id":"sign","label":"A stress sign","valence":"uhoh"},{"id":"not","label":"Not a stress sign","valence":"neutral"}],"key":{"a":"sign","b":"not","c":"sign","d":"not","e":"sign","f":"not"},"relearn":"Racing thoughts, a clenched jaw and snapping can be stress signs worth noticing.","persona":"any","source":"stress signals"},
  {"id":"mm-1377","cat":"stress-and-pressure","type":"sort","hook":"Sort: stress that's normal and passes, or stress to tell an adult about?","items":[{"id":"a","text":"Nerves the night before exams"},{"id":"b","text":"Dreading every day for weeks"},{"id":"c","text":"A racing heart before a race"},{"id":"d","text":"Stress so big you can't eat"},{"id":"e","text":"Worry that fades after the test"},{"id":"f","text":"Feeling you can't cope at all"}],"bins":[{"id":"normal","label":"Normal, passes","valence":"neutral"},{"id":"tell","label":"Tell an adult","valence":"tell"}],"key":{"a":"normal","b":"tell","c":"normal","d":"tell","e":"normal","f":"tell"},"relearn":"Short nerves pass; big, lasting stress that stops you eating means tell an adult.","persona":"any","source":"stress / help-seeking"},
  {"id":"mm-1378","cat":"stress-and-pressure","type":"sort","hook":"Sort: helps you recover after a stressful day, or drains you more?","items":[{"id":"a","text":"A good night's sleep"},{"id":"b","text":"Doomscrolling till midnight"},{"id":"c","text":"Time with people who care"},{"id":"d","text":"Replaying every mistake"},{"id":"e","text":"Doing something you enjoy"},{"id":"f","text":"Skipping rest to do more"}],"bins":[{"id":"helps","label":"Helps you recover","valence":"pos"},{"id":"drains","label":"Drains you more","valence":"neg"}],"key":{"a":"helps","b":"drains","c":"helps","d":"drains","e":"helps","f":"drains"},"relearn":"Sleep, kind company and enjoyment recover you; scrolling, replaying and no rest drain you.","persona":"any","source":"stress / recovery"},
  {"id":"mm-1379","cat":"stress-and-pressure","type":"sort","hook":"Sort: eases exam pressure, or piles it higher?","items":[{"id":"a","text":"A realistic study plan"},{"id":"b","text":"Comparing yourself to toppers"},{"id":"c","text":"Short breaks between subjects"},{"id":"d","text":"Pulling an all-nighter"},{"id":"e","text":"Telling a parent you're stressed"},{"id":"f","text":"\"My marks are my whole worth\""}],"bins":[{"id":"eases","label":"Eases pressure","valence":"pos"},{"id":"piles","label":"Piles it higher","valence":"neg"}],"key":{"a":"eases","b":"piles","c":"eases","d":"piles","e":"eases","f":"piles"},"relearn":"A plan, breaks and talking ease exam pressure; comparison, all-nighters and 'marks=worth' pile it on.","persona":"Diya","source":"exam pressure / India"},
  {"id":"mm-1380","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"If I let myself rest, I'm being lazy and will fall behind.\"","myth":{"un":"Resting when stressed means I'm lazy.","re":"Rest helps a stressed mind work better, not worse.","why":"A rested mind learns and copes more easily."},"relearn":"Rest isn't lazy; it helps a stressed mind work better.","persona":"any","source":"stress / rest"},
  {"id":"mm-1381","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Real toppers never feel stressed.\"","myth":{"un":"Successful people never feel stressed.","re":"Even capable, successful people feel stress under pressure.","why":"Stress is a normal human response, not weakness."},"relearn":"Even capable people feel stress; it isn't a sign of weakness.","persona":"Aarav","source":"stress / de-stigmatise"},
  {"id":"mm-1382","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"The more I worry, the better I'll do.\"","myth":{"un":"Worrying more will make me perform better.","re":"Too much worry blocks your thinking; calm helps you do well.","why":"A calm mind remembers and works more clearly."},"relearn":"Endless worry blocks thinking; calm helps you do your best.","persona":"any","source":"stress / performance"},
  {"id":"mm-1383","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"If I'm stressed, I just have to push through it alone.\"","myth":{"un":"I must push through stress completely alone.","re":"Sharing stress with someone you trust makes it easier to carry.","why":"A worry shared is a worry halved."},"relearn":"You don't push through stress alone; sharing it makes it lighter.","persona":"any","source":"stress / help-seeking"},
  {"id":"mm-1384","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Stress means something is wrong with me.\"","myth":{"un":"Feeling stressed means something is wrong with me.","re":"Stress is your body's normal response to pressure.","why":"It's a signal, not a flaw."},"relearn":"Stress is a normal response to pressure, not proof something's wrong.","persona":"any","source":"stress / normalising"},
  {"id":"mm-1385","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Taking a break when stressed is a waste of time.\"","myth":{"un":"Breaks are a waste of time when I'm stressed.","re":"A short break resets your focus so the next bit goes better.","why":"Your mind works better after a brief pause."},"relearn":"A short break resets focus; it isn't wasted time.","persona":"any","source":"stress / rest"},
  {"id":"mm-1386","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Everyone else finds this easy, so my stress means I'm not smart.\"","myth":{"un":"My stress means I'm less smart than everyone else.","re":"Most people hide their stress; you're seeing their calm side only.","why":"Comparison shows a highlight reel, not the full story."},"relearn":"Others hide their stress too; your stress doesn't mean you're not smart.","persona":"Diya","source":"comparison / stress"},
  {"id":"mm-1387","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"A boy shouldn't show he's stressed.\"","myth":{"un":"Boys shouldn't show they're stressed.","re":"Everyone feels stress; showing it and handling it is strength.","why":"Naming a feeling is braver than hiding it."},"relearn":"Everyone feels stress; showing and handling it is strength, not weakness.","persona":"Aarav","source":"stress / de-stigmatise"},
  {"id":"mm-1388","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"If a task feels huge, I'll never be able to do it.\"","myth":{"un":"A huge task is impossible for me.","re":"Any big task breaks into small steps you can start.","why":"You're never stuck; there's always a first small step."},"relearn":"Big tasks break into small steps; there's always a first one.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-1389","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"My exam result decides my whole future.\"","myth":{"un":"One exam result decides my entire future.","re":"One result is a single moment, not the whole story of your life.","why":"There are many paths and chances ahead."},"relearn":"One result is a moment, not your whole future.","persona":"any","source":"exam pressure / India"},
  {"id":"mm-1390","cat":"stress-and-pressure","type":"strike-rewrite","hook":"\"Slow breathing is silly and can't really help stress.\"","myth":{"un":"Slow breathing is silly and useless for stress.","re":"Slow breathing genuinely calms the body's stress response.","why":"It slows your heart and settles your mind."},"relearn":"Slow breathing really does calm the body's stress response.","persona":"any","source":"stress / breathing"},
  {"id":"mm-1391","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: where do you usually feel stress in your body first?","prompt":"Notice it (just for you).","options":["Tight chest","Knotted tummy","Racing thoughts","Clenched shoulders"],"affirm":"Noticing your stress signal early is the first step to easing it.","relearn":"Spotting your body's stress signal early helps you ease it sooner.","persona":"any","source":"self-awareness"},
  {"id":"mm-1392","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: which calming move would you reach for when stress hits?","prompt":"Pick your go-to.","options":["Slow breaths","A short walk","Talk to someone","A quick break"],"affirm":"Having a go-to move ready makes stressful moments easier.","relearn":"Having a calming go-to ready makes stress easier to meet.","persona":"any","source":"coping / self-awareness"},
  {"id":"mm-1393","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: stress that's huge and won't lift is a signal, not a failing. Sit with that?","prompt":"What do you think?","options":["Yes","It's a signal to tell someone","Good to know"],"affirm":"Big, lasting stress is a signal to tell a trusted adult, never a weakness.","relearn":"Big, lasting stress is a signal to tell a trusted adult.","persona":"any","source":"stress / help-seeking"},
  {"id":"mm-1394","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: what's one thing you can let go of when this week feels too full?","prompt":"Name one (to yourself).","options":["A bit of screen time","One extra activity","Doing it all perfectly","Comparing myself"],"affirm":"Letting one thing go can lift a surprising amount of pressure.","relearn":"Letting one thing go can ease a week that feels too full.","persona":"any","source":"stress / self-care"},
  {"id":"mm-1395","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: think of a stressful day you got through. Proof you can again?","prompt":"What do you think?","options":["Yes","I've coped before","I'm more able than I feel"],"affirm":"You've handled stress before; that's real proof you can again.","relearn":"Remembering past coping reminds you that stress passes and you manage.","persona":"any","source":"resilience / stress"},
  {"id":"mm-1396","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: when stress spikes, try slow breathing: four counts in, six counts out. Worth a go?","prompt":"What do you think?","options":["I'll try it","Calms me down","Easy to remember"],"affirm":"Slowing your out-breath tells your body it's safe to settle.","relearn":"Long, slow out-breaths help your body calm a stress spike.","persona":"any","source":"coping-skill"},
  {"id":"mm-1397","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: who could you tell if stress ever got too big to carry alone?","prompt":"Picture one person.","options":["A parent","A teacher","A friend","Asha didi"],"affirm":"Knowing your person makes reaching out far easier when you need it.","relearn":"Knowing who you'd tell makes asking for help easier when stress is big.","persona":"any","source":"help-seeking"},
  {"id":"mm-1398","cat":"stress-and-pressure","type":"reflect","hook":"Lensy: this hard, stressed feeling won't last forever. Does that help?","prompt":"What do you think?","options":["Yes","Feelings pass","I can ride it out"],"affirm":"Stress rises, peaks and passes, like weather, never the climate.","relearn":"Stress rises, peaks and passes; no feeling is permanent.","persona":"any","source":"normalising"},
  {"id":"mm-1399","cat":"stress-and-pressure","type":"build","hook":"Build your steps for a sudden wave of exam panic.","prompt":"Order a calm-down for panic.","pieces":["stop and notice the panic","take three slow breaths","recall one thing you know","start with that one part"],"mode":"sequence","key":["stop and notice the panic","take three slow breaths","recall one thing you know","start with that one part"],"relearn":"For exam panic: notice it, breathe, recall what you know, start there.","persona":"any","source":"stress / coping"},
  {"id":"mm-1400","cat":"stress-and-pressure","type":"build","hook":"Build a calm study plan for a pressured week.","prompt":"Order a stress-friendly study plan.","pieces":["list everything due","sort by what's nearest","break each into small parts","add a short break after each"],"mode":"sequence","key":["list everything due","sort by what's nearest","break each into small parts","add a short break after each"],"relearn":"A calm plan: list it, order it, break it small, and rest between.","persona":"any","source":"stress / planning"},
  {"id":"mm-1401","cat":"stress-and-pressure","type":"build","hook":"Build your toolkit for the night before a big test.","prompt":"Pick calm-before-the-test tools.","pieces":["finish revising early","slow breaths in bed","a calming routine","enough sleep"],"mode":"assemble","key":["finish revising early","slow breaths in bed","a calming routine","enough sleep"],"relearn":"The night before: stop early, breathe, wind down calmly, and sleep.","persona":"any","source":"stress / sleep"},
  {"id":"mm-1402","cat":"stress-and-pressure","type":"build","hook":"Build a 'shrink an overwhelming pile' plan.","prompt":"Order how to handle a pile that feels too big.","pieces":["name what's overwhelming you","split it into small parts","do just the first part","ask for help if you're stuck"],"mode":"sequence","key":["name what's overwhelming you","split it into small parts","do just the first part","ask for help if you're stuck"],"relearn":"Shrink overwhelm: name it, split it, do the first part, ask if stuck.","persona":"any","source":"stress / overwhelm"},
  {"id":"mm-1403","cat":"stress-and-pressure","type":"build","hook":"Build a quick stress-reset for a tense moment.","prompt":"Pick healthy quick resets.","pieces":["a few slow breaths","stretch or shake it out","a sip of water","step outside for air"],"mode":"assemble","key":["a few slow breaths","stretch or shake it out","a sip of water","step outside for air"],"relearn":"A quick stress-reset: breathe, move, water, and a breath of fresh air.","persona":"any","source":"stress / coping"},
  {"id":"mm-1404","cat":"stress-and-pressure","type":"build","hook":"Build your steps for when comparison starts stressing you out.","prompt":"Order a way to beat the comparison trap.","pieces":["notice you're comparing","close the app or look away","name one thing you're glad of","take your own next small step"],"mode":"sequence","key":["notice you're comparing","close the app or look away","name one thing you're glad of","take your own next small step"],"relearn":"Beat comparison stress: notice it, look away, find one good thing, step on.","persona":"Diya","source":"comparison / stress"},
  {"id":"mm-1405","cat":"stress-and-pressure","type":"build","hook":"Build a pre-match nerve-calmer.","prompt":"Order a calm-down before you compete.","pieces":["notice the nerves","breathe out slowly","tell yourself it's ready-energy","focus on the first move"],"mode":"sequence","key":["notice the nerves","breathe out slowly","tell yourself it's ready-energy","focus on the first move"],"relearn":"Before competing: notice nerves, breathe out, reframe them, focus on step one.","persona":"any","source":"performance nerves"},
  {"id":"mm-1406","cat":"stress-and-pressure","type":"build","hook":"Build a healthy after-school unwind for a stressful day.","prompt":"Pick healthy ways to unwind.","pieces":["a snack and some water","time outside or moving","talk about your day","something you enjoy"],"mode":"assemble","key":["a snack and some water","time outside or moving","talk about your day","something you enjoy"],"relearn":"Unwind after a hard day: refuel, move, talk it out, and enjoy something.","persona":"any","source":"stress / recovery"},
  {"id":"mm-1407","cat":"stress-and-pressure","type":"role-play","hook":"A parent keeps adding pressure and you're at your limit.","setup":"Speak up kindly. Say:","yourLine":[{"text":"\"I really want to do well, but I'm feeling too much pressure right now.\"","best":true},{"text":"Say nothing and let it build up"}],"relearn":"You can tell a parent you're feeling too much pressure.","persona":"Rohit","source":"stress / assertiveness"},
  {"id":"mm-1408","cat":"stress-and-pressure","type":"role-play","hook":"A friend is stressing about the same exam as you.","setup":"Steady them. Say:","yourLine":[{"text":"\"We've got this. Let's take it one small step at a time.\"","best":true},{"text":"\"You should be way more worried.\""}],"relearn":"You can steady a stressed friend by breaking it into small steps.","persona":"any","source":"peer support / stress"},
  {"id":"mm-1409","cat":"stress-and-pressure","type":"role-play","hook":"A teacher set work you genuinely can't finish in time.","setup":"Ask for help honestly. Say:","yourLine":[{"text":"\"This is a lot for the time we have. Could we talk about it?\"","best":true},{"text":"Panic silently and hand in nothing"}],"relearn":"You can honestly tell a teacher when the workload is too much.","persona":"any","source":"stress / help-seeking"},
  {"id":"mm-1410","cat":"stress-and-pressure","type":"role-play","hook":"Someone teases you for taking a break to de-stress.","setup":"Hold your ground. Say:","yourLine":[{"text":"\"A break helps me focus better. It's not slacking.\"","best":true},{"text":"\"You're right, I'll skip my break.\""}],"relearn":"You can stand up for taking a break; rest helps you focus.","persona":"Aarav","source":"stress / de-stigmatise"},
  {"id":"mm-1411","cat":"stress-and-pressure","type":"role-play","hook":"You want to ask a sibling to share the chores so you can study calmly.","setup":"Ask clearly. Say:","yourLine":[{"text":"\"I'm swamped with exams. Could you take a few chores this week?\"","best":true},{"text":"Do it all yourself and feel resentful"}],"relearn":"You can ask family to share the load when you're under pressure.","persona":"any","source":"stress / assertiveness"},
  {"id":"mm-1412","cat":"stress-and-pressure","type":"role-play","hook":"A classmate brags about their marks and you feel the stress rise.","setup":"Protect your calm. Say:","yourLine":[{"text":"\"Good for you. I'm focusing on my own progress.\"","best":true},{"text":"\"I'm clearly hopeless next to you.\""}],"relearn":"You can stay grounded in your own progress, not someone's bragging.","persona":"Diya","source":"comparison / stress"},
  {"id":"mm-1413","cat":"stress-and-pressure","type":"role-play","hook":"You're overwhelmed and want to tell Asha didi how stressed you are.","setup":"Open up. Say:","yourLine":[{"text":"\"Didi, everything's piling up and I'm really stressed. Can we talk?\"","best":true},{"text":"Pretend everything's fine"}],"relearn":"You can tell a trusted near-peer like Asha when stress piles up.","persona":"Asha","source":"stress / help-seeking"},
  {"id":"mm-1414","cat":"stress-and-pressure","type":"role-play","hook":"Your inner voice is shouting that you'll fail the exam.","setup":"Answer it kindly. Say:","yourLine":[{"text":"\"One step at a time. I've handled hard things before.\"","best":true},{"text":"\"Yeah, I'm definitely going to fail.\""}],"relearn":"You can answer a panicking inner voice with calm, kind self-talk.","persona":"any","source":"self-talk / stress"},
  {"id":"mm-1415","cat":"stress-and-pressure","type":"match","hook":"Match the stress signal to a calming response.","pairs":[{"left":"Tight, fast breathing","right":"Slow square breaths"},{"left":"A spinning to-do list","right":"Write it down, pick one"},{"left":"Restless, jumpy body","right":"A short walk"},{"left":"Harsh \"I'll fail\" thoughts","right":"Kind self-talk"},{"left":"Feeling all alone in it","right":"Talk to someone you trust"}],"relearn":"Each stress signal has a healthy calming response that fits it.","persona":"any","source":"coping / stress"},
  {"id":"mm-1416","cat":"stress-and-pressure","type":"match","hook":"Match the pressure moment to a helpful first move.","pairs":[{"left":"Surprise test announced","right":"Breathe, recall what you know"},{"left":"Too much homework","right":"Tell a caring adult"},{"left":"Can't start anything","right":"Do one tiny first step"},{"left":"Can't sleep from worry","right":"Slow wind-down routine"},{"left":"Comparing yourself online","right":"Close the app"}],"relearn":"Every pressure moment has a healthy first move you can choose.","persona":"any","source":"coping / stress"},
  {"id":"mm-1417","cat":"stress-and-pressure","type":"match","hook":"Match the stress myth to the truth.","pairs":[{"left":"\"Stress means I'm weak\"","right":"Stress is a normal response"},{"left":"\"Marks are my worth\"","right":"Marks measure one test"},{"left":"\"I must cope alone\"","right":"Sharing makes it lighter"},{"left":"\"Rest is lazy\"","right":"Rest helps you do better"},{"left":"\"Worry helps me\"","right":"Calm helps me think"}],"relearn":"The beliefs that worsen stress are myths; the truths ease it.","persona":"any","source":"stress / de-stigmatise"},
  {"id":"mm-1418","cat":"stress-and-pressure","type":"match","hook":"Match each stress tool to what it does.","pairs":[{"left":"Square breathing","right":"Calms a racing body"},{"left":"Breaking it small","right":"Makes a big task doable"},{"left":"A short break","right":"Resets your focus"},{"left":"Talking it out","right":"Lightens the worry"},{"left":"Moving your body","right":"Shifts a tense mood"}],"relearn":"Each healthy stress tool eases pressure in its own way.","persona":"any","source":"coping / stress"},
  {"id":"mm-1419","cat":"stress-and-pressure","type":"match","hook":"Match the stressful feeling to a kinder thought.","pairs":[{"left":"\"I'll never finish this\"","right":"\"One step at a time\""},{"left":"\"Everyone's ahead of me\"","right":"\"My path is my own\""},{"left":"\"This stress won't end\"","right":"\"Feelings rise and pass\""},{"left":"\"I have to be perfect\"","right":"\"Good enough is okay\""},{"left":"\"I can't cope alone\"","right":"\"I can ask for help\""}],"relearn":"A kinder thought can ease the sting of a stressful one.","persona":"any","source":"cognitive / stress"},
  {"id":"mm-1420","cat":"stress-and-pressure","type":"match","hook":"Match the pressure source to a healthy way to handle it.","pairs":[{"left":"Packed timetable","right":"Build in a real break"},{"left":"Relatives comparing you","right":"Let their words pass"},{"left":"Group project strain","right":"Ask for a fair split"},{"left":"Tough feedback","right":"Keep the useful part"},{"left":"Lasting heavy stress","right":"Tell a trusted adult"}],"relearn":"Every pressure source has a healthy, doable way to handle it.","persona":"any","source":"coping / stress"},
  {"id":"mm-1421","cat":"stress-and-pressure","type":"match","hook":"Match the worry to who can help with it.","pairs":[{"left":"Workload at school","right":"A teacher"},{"left":"Pressure at home","right":"A trusted family adult"},{"left":"Wanting to talk it out","right":"Asha didi or a friend"},{"left":"Stress that won't lift","right":"A counsellor"},{"left":"Feeling you can't cope","right":"Childline 1098 / 112"}],"relearn":"Different stress worries each have a right person or helpline to turn to.","persona":"Asha","source":"help-routing / stress"},
  {"id":"mm-1422","cat":"stress-and-pressure","type":"sort","hook":"Sort: a kind way to support a stressed friend, or an unkind one?","items":[{"id":"a","text":"\"Want to take a breath together?\""},{"id":"b","text":"\"You're overreacting, relax\""},{"id":"c","text":"\"I'm here, what do you need?\""},{"id":"d","text":"\"Everyone has it worse than you\""},{"id":"e","text":"\"Let's break it into small steps\""},{"id":"f","text":"\"Just stop stressing\""}],"bins":[{"id":"kind","label":"Kind support","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Breathing together and offering help support a stressed friend; dismissing their stress doesn't.","persona":"any","source":"peer support / stress"},
  {"id":"mm-1423","cat":"stress-and-pressure","type":"match","hook":"Match the unhelpful stress habit to a healthier swap.","pairs":[{"left":"Pulling an all-nighter","right":"Study early, then sleep"},{"left":"Skipping meals to study","right":"Eat, then study calmer"},{"left":"Doomscrolling to escape","right":"A real break outdoors"},{"left":"Bottling it all up","right":"Talk to someone you trust"},{"left":"Chasing perfect","right":"Aim for good enough"}],"relearn":"Every unhelpful stress habit has a healthier swap that works better.","persona":"any","source":"coping / stress"},
];

